const a=JSON.parse('{"name":"بخاری","sections":{"1":"وحی","2":"عقیدہ"},"hadiths":[{"id":1,"text":"کو حمیدی نے یہ حدیث بیان کی، انہوں نے کہا کہ ہم کو سفیان نے یہ حدیث بیان کی، وہ کہتے ہیں ہم کو یحییٰ بن سعید انصاری نے یہ حدیث بیان کی، انہوں نے کہا کہ مجھے یہ حدیث محمد بن ابراہیم تیمی سے حاصل ہوئی۔ انہوں نے اس حدیث کو علقمہ بن وقاص لیثی سے سنا، ان کا بیان ہے کہ میں نے مسجد نبوی میں منبر رسول صلی اللہ علیہ وسلم پر عمر بن خطاب رضی اللہ عنہ کی زبان سے سنا، وہ فرما رہے تھے کہ میں نے جناب رسول اللہ صلی اللہ علیہ وسلم سے سنا آپ صلی اللہ علیہ وسلم فرما رہے تھے کہ تمام اعمال کا دارومدار نیت پر ہے اور ہر عمل کا نتیجہ ہر انسان کو اس کی نیت کے مطابق ہی ملے گا۔ پس جس کی ہجرت ( ترک وطن ) دولت دنیا حاصل کرنے کے لیے ہو یا کسی عورت سے شادی کی غرض ہو۔ پس اس کی ہجرت ان ہی چیزوں کے لیے ہو گی جن کے حاصل کرنے کی نیت سے اس نے ہجرت کی ہے۔","section":1,"grades":[]},{"id":2,"text":"ہم کو عبداللہ بن یوسف نے حدیث بیان کی، ان کو مالک نے ہشام بن عروہ کی روایت سے خبر دی، انہوں نے اپنے والد سے نقل کی، انہوں نے ام المؤمنین عائشہ صدیقہ رضی اللہ عنہا سے نقل کی آپ نے فرمایا کہ ایک شخص حارث بن ہشام نامی نے نبی کریم صلی اللہ علیہ وسلم سے سوال کیا تھا کہ یا رسول اللہ! آپ پر وحی کیسے نازل ہوتی ہے؟ آپ صلی اللہ علیہ وسلم نے فرمایا کہ وحی نازل ہوتے وقت کبھی مجھ کو گھنٹی کی سی آواز محسوس ہوتی ہے اور وحی کی یہ کیفیت مجھ پر بہت شاق گذرتی ہے۔ جب یہ کیفیت ختم ہوتی ہے تو میرے دل و دماغ پر اس ( فرشتے ) کے ذریعہ نازل شدہ وحی محفوظ ہو جاتی ہے اور کسی وقت ایسا ہوتا ہے کہ فرشتہ بشکل انسان میرے پاس آتا ہے اور مجھ سے کلام کرتا ہے۔ پس میں اس کا کہا ہوا یاد رکھ لیتا ہوں۔ عائشہ رضی اللہ عنہا کا بیان ہے کہ میں نے سخت کڑاکے کی سردی میں نبی کریم صلی اللہ علیہ وسلم کو دیکھا ہے کہ آپ صلی اللہ علیہ وسلم پر وحی نازل ہوئی اور جب اس کا سلسلہ موقوف ہوا تو آپ صلی اللہ علیہ وسلم کی پیشانی پسینے سے شرابور تھی۔","section":1,"grades":[]},{"id":3,"text":"ہم کو یحییٰ بن بکیر نے یہ حدیث بیان کی، وہ کہتے ہیں کہ اس حدیث کی ہم کو لیث نے خبر دی، لیث عقیل سے روایت کرتے ہیں۔ عقیل ابن شہاب سے، وہ عروہ بن زبیر سے، وہ ام المؤمنین عائشہ رضی اللہ عنہا سے نقل کرتے ہیں کہ انہوں نے بتلایا کہ نبی کریم صلی اللہ علیہ وسلم پر وحی کا ابتدائی دور اچھے سچے پاکیزہ خوابوں سے شروع ہوا۔ آپ صلی اللہ علیہ وسلم خواب میں جو کچھ دیکھتے وہ صبح کی روشنی کی طرح صحیح اور سچا ثابت ہوتا۔ پھر من جانب قدرت آپ صلی اللہ علیہ وسلم تنہائی پسند ہو گئے اور آپ صلی اللہ علیہ وسلم نے غار حرا میں خلوت نشینی اختیار فرمائی اور کئی کئی دن اور رات وہاں مسلسل عبادت اور یاد الٰہی و ذکر و فکر میں مشغول رہتے۔ جب تک گھر آنے کو دل نہ چاہتا توشہ ہمراہ لیے ہوئے وہاں رہتے۔ توشہ ختم ہونے پر ہی اہلیہ محترمہ خدیجہ رضی اللہ عنہا کے پاس تشریف لاتے اور کچھ توشہ ہمراہ لے کر پھر وہاں جا کر خلوت گزیں ہو جاتے، یہی طریقہ جاری رہا یہاں تک کہ آپ صلی اللہ علیہ وسلم پر حق منکشف ہو گیا اور آپ صلی اللہ علیہ وسلم غار حرا ہی میں قیام پذیر تھے کہ اچانک جبرائیل علیہ السلام آپ صلی اللہ علیہ وسلم کے پاس حاضر ہوئے اور کہنے لگے کہ اے محمد! پڑھو آپ صلی اللہ علیہ وسلم فرماتے ہیں کہ میں نے کہا کہ میں پڑھنا نہیں جانتا، آپ صلی اللہ علیہ وسلم فرماتے ہیں کہ فرشتے نے مجھے پکڑ کر اتنے زور سے بھینچا کہ میری طاقت جواب دے گئی، پھر مجھے چھوڑ کر کہا کہ پڑھو، میں نے پھر وہی جواب دیا کہ میں پڑھا ہوا نہیں ہوں۔ اس فرشتے نے مجھ کو نہایت ہی زور سے بھینچا کہ مجھ کو سخت تکلیف محسوس ہوئی، پھر اس نے کہا کہ پڑھ! میں نے کہا کہ میں پڑھا ہوا نہیں ہوں۔ فرشتے نے تیسری بار مجھ کو پکڑا اور تیسری مرتبہ پھر مجھ کو بھینچا پھر مجھے چھوڑ دیا اور کہنے لگا کہ پڑھو اپنے رب کے نام کی مدد سے جس نے پیدا کیا اور انسان کو خون کی پھٹکی سے بنایا، پڑھو اور آپ کا رب بہت ہی مہربانیاں کرنے والا ہے۔ پس یہی آیتیں آپ صلی اللہ علیہ وسلم جبرائیل علیہ السلام سے سن کر اس حال میں غار حرا سے واپس ہوئے کہ آپ صلی اللہ علیہ وسلم کا دل اس انوکھے واقعہ سے کانپ رہا تھا۔ آپ صلی اللہ علیہ وسلم خدیجہ کے ہاں تشریف لائے اور فرمایا کہ مجھے کمبل اڑھا دو، مجھے کمبل اڑھا دو۔ لوگوں نے آپ صلی اللہ علیہ وسلم کو کمبل اڑھا دیا۔ جب آپ صلی اللہ علیہ وسلم کا ڈر جاتا رہا۔ تو آپ صلی اللہ علیہ وسلم نے اپنی زوجہ محترمہ خدیجہ رضی اللہ عنہا کو تفصیل کے ساتھ یہ واقعہ سنایا اور فرمانے لگے کہ مجھ کو اب اپنی جان کا خوف ہو گیا ہے۔ آپ صلی اللہ علیہ وسلم کی اہلیہ محترمہ خدیجہ رضی اللہ عنہا نے آپ صلی اللہ علیہ وسلم کی ڈھارس بندھائی اور کہا کہ آپ کا خیال صحیح نہیں ہے۔ اللہ کی قسم! آپ کو اللہ کبھی رسوا نہیں کرے گا، آپ تو اخلاق فاضلہ کے مالک ہیں، آپ تو کنبہ پرور ہیں، بے کسوں کا بوجھ اپنے سر پر رکھ لیتے ہیں، مفلسوں کے لیے آپ کماتے ہیں، مہمان نوازی میں آپ بےمثال ہیں اور مشکل وقت میں آپ امر حق کا ساتھ دیتے ہیں۔ ایسے اوصاف حسنہ والا انسان یوں بے وقت ذلت و خواری کی موت نہیں پا سکتا۔ پھر مزید تسلی کے لیے خدیجہ رضی اللہ عنہا آپ صلی اللہ علیہ وسلم کو ورقہ بن نوفل کے پاس لے گئیں، جو ان کے چچا زاد بھائی تھے اور زمانہ جاہلیت میں نصرانی مذہب اختیار کر چکے تھے اور عبرانی زبان کے کاتب تھے، چنانچہ انجیل کو بھی حسب منشائے خداوندی عبرانی زبان میں لکھا کرتے تھے۔ ( انجیل سریانی زبان میں نازل ہوئی تھی پھر اس کا ترجمہ عبرانی زبان میں ہوا۔ ورقہ اسی کو لکھتے تھے ) وہ بہت بوڑھے ہو گئے تھے یہاں تک کہ ان کی بینائی بھی رخصت ہو چکی تھی۔ خدیجہ رضی اللہ عنہا نے ان کے سامنے آپ صلی اللہ علیہ وسلم کے حالات بیان کیے اور کہا کہ اے چچا زاد بھائی! اپنے بھتیجے ( محمد صلی اللہ علیہ وسلم ) کی زبانی ذرا ان کی کیفیت سن لیجیئے وہ بولے کہ بھتیجے آپ نے جو کچھ دیکھا ہے، اس کی تفصیل سناؤ۔ چنانچہ آپ صلی اللہ علیہ وسلم نے از اول تا آخر پورا واقعہ سنایا، جسے سن کر ورقہ بے اختیار ہو کر بول اٹھے کہ یہ تو وہی ناموس ( معزز راز دان فرشتہ ) ہے جسے اللہ نے موسیٰ علیہ السلام پر وحی دے کر بھیجا تھا۔ کاش، میں آپ کے اس عہد نبوت کے شروع ہونے پر جوان عمر ہوتا۔ کاش میں اس وقت تک زندہ رہتا جب کہ آپ کی قوم آپ کو اس شہر سے نکال دے گی۔ رسول اللہ صلی اللہ علیہ وسلم نے یہ سن کر تعجب سے پوچھا کہ کیا وہ لوگ مجھ کو نکال دیں گے؟ ( حالانکہ میں تو ان میں صادق و امین و مقبول ہوں ) ورقہ بولا ہاں یہ سب کچھ سچ ہے۔ مگر جو شخص بھی آپ کی طرح امر حق لے کر آیا لوگ اس کے دشمن ہی ہو گئے ہیں۔ اگر مجھے آپ کی نبوت کا وہ زمانہ مل جائے تو میں آپ کی پوری پوری مدد کروں گا۔ مگر ورقہ کچھ دنوں کے بعد انتقال کر گئے۔ پھر کچھ عرصہ تک وحی کی آمد موقوف رہی۔","section":1,"grades":[]},{"id":4,"text":"ابن شہاب کہتے ہیں مجھ کو ابوسلمہ بن عبدالرحمٰن نے جابر بن عبداللہ انصاری رضی اللہ عنہما سے یہ روایت نقل کی کہ آپ صلی اللہ علیہ وسلم نے وحی کے رک جانے کے زمانے کے حالات بیان فرماتے ہوئے کہا کہ ایک روز میں چلا جا رہا تھا کہ اچانک میں نے آسمان کی طرف ایک آواز سنی اور میں نے اپنا سر آسمان کی طرف اٹھایا کیا دیکھتا ہوں کہ وہی فرشتہ جو میرے پاس غار حرا میں آیا تھا وہ آسمان و زمین کے بیچ میں ایک کرسی پر بیٹھا ہوا ہے۔ میں اس سے ڈر گیا اور گھر آنے پر میں نے پھر کمبل اوڑھنے کی خواہش ظاہر کی۔ اس وقت اللہ پاک کی طرف سے یہ آیات نازل ہوئیں۔ اے لحاف اوڑھ کر لیٹنے والے! اٹھ کھڑا ہو اور لوگوں کو عذاب الٰہی سے ڈرا اور اپنے رب کی بڑائی بیان کر اور اپنے کپڑوں کو پاک صاف رکھ اور گندگی سے دور رہ۔ اس کے بعد وحی تیزی کے ساتھ پے در پے آنے لگی۔ اس حدیث کو یحییٰ بن بکیر کے علاوہ لیث بن سعد سے عبداللہ بن یوسف اور ابوصالح نے بھی روایت کیا ہے۔ اور عقیل کے علاوہ زہری سے ہلال بن رواد نے بھی روایت کیا ہے۔ یونس اور معمر نے اپنی روایت میں لفظ «فواده» کی جگہ «بوادره» نقل کیا ہے۔","section":1,"grades":[]},{"id":5,"text":"موسیٰ بن اسماعیل نے ہم سے حدیث بیان کی، ان کو ابوعوانہ نے خبر دی، ان سے موسیٰ ابن ابی عائشہ نے بیان کی، ان سے سعید بن جبیر نے انہوں نے ابن عباس رضی اللہ عنہما سے کلام الٰہی «لا تحرك به لسانك لتعجل به‏» الخ کی تفسیر کے سلسلہ میں سنا کہ رسول اللہ صلی اللہ علیہ وسلم نزول قرآن کے وقت بہت سختی محسوس فرمایا کرتے تھے اور اس کی ( علامتوں ) میں سے ایک یہ تھی کہ یاد کرنے کے لیے آپ اپنے ہونٹوں کو ہلاتے تھے۔ ابن عباس رضی اللہ عنہما نے کہا میں اپنے ہونٹ ہلاتا ہوں جس طرح آپ ہلاتے تھے۔ سعید کہتے ہیں میں بھی اپنے ہونٹ ہلاتا ہوں جس طرح ابن عباس رضی اللہ عنہما کو میں نے ہلاتے دیکھا۔ پھر انہوں نے اپنے ہونٹ ہلائے۔ ( ابن عباس رضی اللہ عنہما نے کہا ) پھر یہ آیت اتری کہ اے محمد! قرآن کو جلد جلد یاد کرنے کے لیے اپنی زبان نہ ہلاؤ۔ اس کا جمع کر دینا اور پڑھا دینا ہمارا ذمہ ہے۔ ابن عباس رضی اللہ عنہما کہتے ہیں یعنی قرآن آپ صلی اللہ علیہ وسلم کے دل میں جما دینا اور پڑھا دینا ہمارے ذمہ ہے۔ پھر جب ہم پڑھ چکیں تو اس پڑھے ہوئے کی اتباع کرو۔ ابن عباس رضی اللہ عنہما فرماتے ہیں ( اس کا مطلب یہ ہے ) کہ آپ اس کو خاموشی کے ساتھ سنتے رہو۔ اس کے بعد مطلب سمجھا دینا ہمارے ذمہ ہے۔ پھر یقیناً یہ ہماری ذمہ داری ہے کہ آپ اس کو پڑھو ( یعنی اس کو محفوظ کر سکو ) چنانچہ اس کے بعد جب آپ کے پاس جبرائیل علیہ السلام ( وحی لے کر ) آتے تو آپ ( توجہ سے ) سنتے۔ جب وہ چلے جاتے تو رسول اللہ صلی اللہ علیہ وسلم اس ( وحی ) کو اسی طرح پڑھتے جس طرح جبرائیل علیہ السلام نے اسے پڑھا تھا۔","section":1,"grades":[]},{"id":6,"text":"ہم کو عبدان نے حدیث بیان کی، انہیں عبداللہ بن مبارک نے خبر دی، ان کو یونس نے، انہوں نے زہری سے یہ حدیث سنی۔ (دوسری سند یہ ہے کہ) ہم سے بشر بن محمد نے یہ حدیث بیان کی۔ ان سے عبداللہ بن مبارک نے، ان سے یونس اور معمر دونوں نے، ان دونوں نے زہری سے روایت کی پہلی سند کے مطابق زہری سے عبیداللہ بن عبداللہ نے، انہوں نے ابن عباس رضی اللہ عنہما سے یہ روایت نقل کی کہ رسول اللہ صلی اللہ علیہ وسلم سب لوگوں سے زیادہ جواد ( سخی ) تھے اور رمضان میں ( دوسرے اوقات کے مقابلہ میں جب ) جبرائیل علیہ السلام آپ صلی اللہ علیہ وسلم سے ملتے بہت ہی زیادہ جود و کرم فرماتے۔ جبرائیل علیہ السلام رمضان کی ہر رات میں آپ صلی اللہ علیہ وسلم سے ملاقات کرتے اور آپ صلی اللہ علیہ وسلم کے ساتھ قرآن کا دورہ کرتے، غرض نبی کریم صلی اللہ علیہ وسلم لوگوں کو بھلائی پہنچانے میں بارش لانے والی ہوا سے بھی زیادہ جود و کرم فرمایا کرتے تھے۔","section":1,"grades":[]},{"id":7,"text":"ہم کو ابوالیمان حکم بن نافع نے حدیث بیان کی، انہیں اس حدیث کی شعیب نے خبر دی۔ انہوں نے زہری سے یہ حدیث سنی۔ انہیں عبیداللہ ابن عبداللہ ابن عتبہ بن مسعود نے خبر دی کہ عبداللہ بن عباس سے ابوسفیان بن حرب نے یہ واقعہ بیان کیا کہ ہرقل ( شاہ روم ) نے ان کے پاس قریش کے قافلے میں ایک آدمی بلانے کو بھیجا اور اس وقت یہ لوگ تجارت کے لیے ملک شام گئے ہوئے تھے اور یہ وہ زمانہ تھا جب رسول اللہ صلی اللہ علیہ وسلم نے قریش اور ابوسفیان سے ایک وقتی عہد کیا ہوا تھا۔ جب ابوسفیان اور دوسرے لوگ ہرقل کے پاس ایلیاء پہنچے جہاں ہرقل نے دربار طلب کیا تھا۔ اس کے گرد روم کے بڑے بڑے لوگ ( علماء وزراء امراء ) بیٹھے ہوئے تھے۔ ہرقل نے ان کو اور اپنے ترجمان کو بلوایا۔ پھر ان سے پوچھا کہ تم میں سے کون شخص مدعی رسالت کا زیادہ قریبی عزیز ہے؟ ابوسفیان کہتے ہیں کہ میں بول اٹھا کہ میں اس کا سب سے زیادہ قریبی رشتہ دار ہوں۔ ( یہ سن کر ) ہرقل نے حکم دیا کہ اس کو ( ابوسفیان کو ) میرے قریب لا کر بٹھاؤ اور اس کے ساتھیوں کو اس کی پیٹھ کے پیچھے بٹھا دو۔ پھر اپنے ترجمان سے کہا کہ ان لوگوں سے کہہ دو کہ میں ابوسفیان سے اس شخص کے ( یعنی محمد صلی اللہ علیہ وسلم کے ) حالات پوچھتا ہوں۔ اگر یہ مجھ سے کسی بات میں جھوٹ بول دے تو تم اس کا جھوٹ ظاہر کر دینا، ( ابوسفیان کا قول ہے کہ ) اللہ کی قسم! اگر مجھے یہ غیرت نہ آتی کہ یہ لوگ مجھ کو جھٹلائیں گے تو میں آپ صلی اللہ علیہ وسلم کی نسبت ضرور غلط گوئی سے کام لیتا۔ خیر پہلی بات جو ہرقل نے مجھ سے پوچھی وہ یہ کہ اس شخص کا خاندان تم لوگوں میں کیسا ہے؟ میں نے کہا وہ تو بڑے اونچے عالی نسب والے ہیں۔ کہنے لگا اس سے پہلے بھی کسی نے تم لوگوں میں ایسی بات کہی تھی؟ میں نے کہا نہیں کہنے لگا، اچھا اس کے بڑوں میں کوئی بادشاہ ہوا ہے؟ میں نے کہا نہیں۔ پھر اس نے کہا، بڑے لوگوں نے اس کی پیروی اختیار کی ہے یا کمزوروں نے؟ میں نے کہا نہیں کمزوروں نے۔ پھر کہنے لگا، اس کے تابعدار روز بڑھتے جاتے ہیں یا کوئی ساتھی پھر بھی جاتا ہے؟ میں نے کہا نہیں۔ کہنے لگا کہ کیا اپنے اس دعوائے ( نبوت ) سے پہلے کبھی ( کسی بھی موقع پر ) اس نے جھوٹ بولا ہے؟ میں نے کہا نہیں۔ اور اب ہماری اس سے ( صلح کی ) ایک مقررہ مدت ٹھہری ہوئی ہے۔ معلوم نہیں وہ اس میں کیا کرنے والا ہے۔ ( ابوسفیان کہتے ہیں ) میں اس بات کے سوا اور کوئی ( جھوٹ ) اس گفتگو میں شامل نہ کر سکا۔ ہرقل نے کہا کیا تمہاری اس سے کبھی لڑائی بھی ہوتی ہے؟ ہم نے کہا کہ ہاں۔ بولا پھر تمہاری اور اس کی جنگ کا کیا حال ہوتا ہے؟ میں نے کہا، لڑائی ڈول کی طرح ہے، کبھی وہ ہم سے ( میدان جنگ ) جیت لیتے ہیں اور کبھی ہم ان سے جیت لیتے ہیں۔ ہرقل نے پوچھا۔ وہ تمہیں کس بات کا حکم دیتا ہے؟ میں نے کہا وہ کہتا ہے کہ صرف ایک اللہ ہی کی عبادت کرو، اس کا کسی کو شریک نہ بناؤ اور اپنے باپ دادا کی ( شرک کی ) باتیں چھوڑ دو اور ہمیں نماز پڑھنے، سچ بولنے، پرہیزگاری اور صلہ رحمی کا حکم دیتا ہے۔ ( یہ سب سن کر ) پھر ہرقل نے اپنے ترجمان سے کہا کہ ابوسفیان سے کہہ دے کہ میں نے تم سے اس کا نسب پوچھا تو تم نے کہا کہ وہ ہم میں عالی نسب ہے اور پیغمبر اپنی قوم میں عالی نسب ہی بھیجے جایا کرتے ہیں۔ میں نے تم سے پوچھا کہ ( دعویٰ نبوت کی ) یہ بات تمہارے اندر اس سے پہلے کسی اور نے بھی کہی تھی، تو تم نے جواب دیا کہ نہیں، تب میں نے ( اپنے دل میں ) کہا کہ اگر یہ بات اس سے پہلے کسی نے کہی ہوتی تو میں سمجھتا کہ اس شخص نے بھی اسی بات کی تقلید کی ہے جو پہلے کہی جا چکی ہے۔ میں نے تم سے پوچھا کہ اس کے بڑوں میں کوئی بادشاہ بھی گزرا ہے، تم نے کہا کہ نہیں۔ تو میں نے ( دل میں ) کہا کہ ان کے بزرگوں میں سے کوئی بادشاہ ہوا ہو گا تو کہہ دوں گا کہ وہ شخص ( اس بہانہ ) اپنے آباء و اجداد کی بادشاہت اور ان کا ملک ( دوبارہ ) حاصل کرنا چاہتا ہے۔ اور میں نے تم سے پوچھا کہ اس بات کے کہنے ( یعنی پیغمبری کا دعویٰ کرنے ) سے پہلے تم نے کبھی اس کو دروغ گوئی کا الزام لگایا ہے؟ تم نے کہا کہ نہیں۔ تو میں نے سمجھ لیا کہ جو شخص آدمیوں کے ساتھ دروغ گوئی سے بچے وہ اللہ کے بارے میں کیسے جھوٹی بات کہہ سکتا ہے۔ اور میں نے تم سے پوچھا کہ بڑے لوگ اس کے پیرو ہوتے ہیں یا کمزور آدمی۔ تم نے کہا کمزوروں نے اس کی اتباع کی ہے، تو ( دراصل ) یہی لوگ پیغمبروں کے متبعین ہوتے ہیں۔ اور میں نے تم سے پوچھا کہ اس کے ساتھی بڑھ رہے ہیں یا کم ہو رہے ہیں۔ تم نے کہا کہ وہ بڑھ رہے ہیں اور ایمان کی کیفیت یہی ہوتی ہے۔ حتیٰ کہ وہ کامل ہو جاتا ہے اور میں نے تم سے پوچھا کہ آیا کوئی شخص اس کے دین سے ناخوش ہو کر مرتد بھی ہو جاتا ہے تم نے کہا نہیں، تو ایمان کی خاصیت بھی یہی ہے جن کے دلوں میں اس کی مسرت رچ بس جائے وہ اس سے لوٹا نہیں کرتے۔ اور میں نے تم سے پوچھا کہ آیا وہ کبھی عہد شکنی کرتے ہیں۔ تم نے کہا نہیں، پیغمبروں کا یہی حال ہوتا ہے، وہ عہد کی خلاف ورزی نہیں کرتے۔ اور میں نے تم سے کہا کہ وہ تم سے کس چیز کے لیے کہتے ہیں۔ تم نے کہا کہ وہ ہمیں حکم دیتے ہیں کہ اللہ کی عبادت کرو، اس کے ساتھ کسی کو شریک نہ ٹھہراؤ اور تمہیں بتوں کی پرستش سے روکتے ہیں۔ سچ بولنے اور پرہیزگاری کا حکم دیتے ہیں۔ لہٰذا اگر یہ باتیں جو تم کہہ رہے ہو سچ ہیں تو عنقریب وہ اس جگہ کا مالک ہو جائے گا کہ جہاں میرے یہ دونوں پاؤں ہیں۔ مجھے معلوم تھا کہ وہ ( پیغمبر ) آنے والا ہے۔ مگر مجھے یہ معلوم نہیں تھا کہ وہ تمہارے اندر ہو گا۔ اگر میں جانتا کہ اس تک پہنچ سکوں گا تو اس سے ملنے کے لیے ہر تکلیف گوارا کرتا۔ اگر میں اس کے پاس ہوتا تو اس کے پاؤں دھوتا۔ ہرقل نے رسول اللہ صلی اللہ علیہ وسلم وہ خط منگایا جو آپ نے دحیہ کلبی رضی اللہ عنہ کے ذریعہ حاکم بصریٰ کے پاس بھیجا تھا اور اس نے وہ ہرقل کے پاس بھیج دیا تھا۔ پھر اس کو پڑھا تو اس میں ( لکھا تھا ) : اللہ کے نام کے ساتھ جو نہایت مہربان اور رحم والا ہے۔ اللہ کے بندے اور اس کے پیغمبر محمد صلی اللہ علیہ وسلم کی طرف سے یہ خط ہے شاہ روم کے لیے۔ اس شخص پر سلام ہو جو ہدایت کی پیروی کرے اس کے بعد میں آپ کے سامنے دعوت اسلام پیش کرتا ہوں۔ اگر آپ اسلام لے آئیں گے تو ( دین و دنیا میں ) سلامتی نصیب ہو گی۔ اللہ آپ کو دوہرا ثواب دے گا اور اگر آپ ( میری دعوت سے ) روگردانی کریں گے تو آپ کی رعایا کا گناہ بھی آپ ہی پر ہو گا۔ اور اے اہل کتاب! ایک ایسی بات پر آ جاؤ جو ہمارے اور تمہارے درمیان یکساں ہے۔ وہ یہ کہ ہم اللہ کے سوا کسی کی عبادت نہ کریں اور کسی کو اس کا شریک نہ ٹھہرائیں اور نہ ہم میں سے کوئی کسی کو اللہ کے سوا اپنا رب بنائے۔ پھر اگر وہ اہل کتاب ( اس بات سے ) منہ پھیر لیں تو ( مسلمانو! ) تم ان سے کہہ دو کہ ( تم مانو یا نہ مانو ) ہم تو ایک اللہ کے اطاعت گزار ہیں۔ ابوسفیان کہتے ہیں: جب ہرقل نے جو کچھ کہنا تھا کہہ دیا اور خط پڑھ کر فارغ ہوا تو اس کے اردگرد بہت شور و غوغہ ہوا، بہت سی آوازیں اٹھیں اور ہمیں باہر نکال دیا گیا۔ تب میں نے اپنے ساتھیوں سے کہا کہ ابوکبشہ کے بیٹے ( نبی کریم صلی اللہ علیہ وسلم ) کا معاملہ تو بہت بڑھ گیا ( دیکھو تو ) اس سے بنی اصفر ( روم ) کا بادشاہ بھی ڈرتا ہے۔ مجھے اس وقت سے اس بات کا یقین ہو گیا کہ نبی کریم صلی اللہ علیہ وسلم عنقریب غالب ہو کر رہیں گے۔ حتیٰ کہ اللہ نے مجھے مسلمان کر دیا۔ ( راوی کا بیان ہے کہ ) ابن ناطور ایلیاء کا حاکم ہرقل کا مصاحب اور شام کے نصاریٰ کا لاٹ پادری بیان کرتا تھا کہ ہرقل جب ایلیاء آیا، ایک دن صبح کو پریشان اٹھا تو اس کے درباریوں نے دریافت کیا کہ آج ہم آپ کی حالت بدلی ہوئی پاتے ہیں۔ ( کیا وجہ ہے؟ ) ابن ناطور کا بیان ہے کہ ہرقل نجومی تھا، علم نجوم میں وہ پوری مہارت رکھتا تھا۔ اس نے اپنے ہم نشینوں کو بتایا کہ میں نے آج رات ستاروں پر نظر ڈالی تو دیکھا کہ ختنہ کرنے والوں کا بادشاہ ہمارے ملک پر غالب آ گیا ہے۔ ( بھلا ) اس زمانے میں کون لوگ ختنہ کرتے ہیں؟ انہوں نے کہا کہ یہود کے سوا کوئی ختنہ نہیں کرتا۔ سو ان کی وجہ سے پریشان نہ ہوں۔ سلطنت کے تمام شہروں میں یہ حکم لکھ بھیجئے کہ وہاں جتنے یہودی ہوں سب قتل کر دئیے جائیں۔ وہ لوگ انہی باتوں میں مشغول تھے کہ ہرقل کے پاس ایک آدمی لایا گیا۔ جسے شاہ غسان نے بھیجا تھا۔ اس نے رسول اللہ صلی اللہ علیہ وسلم کے حالات بیان کئے۔ جب ہرقل نے ( سارے حالات ) سن لیے تو کہا کہ جا کر دیکھو وہ ختنہ کئے ہوئے ہے یا نہیں؟ انہوں نے اسے دیکھا تو بتلایا کہ وہ ختنہ کیا ہوا ہے۔ ہرقل نے جب اس شخص سے عرب کے بارے میں پوچھا تو اس نے بتلایا کہ وہ ختنہ کرتے ہیں۔ تب ہرقل نے کہا کہ یہ ہی ( محمد صلی اللہ علیہ وسلم ) اس امت کے بادشاہ ہیں جو پیدا ہو چکے ہیں۔ پھر اس نے اپنے ایک دوست کو رومیہ خط لکھا اور وہ بھی علم نجوم میں ہرقل کی طرح ماہر تھا۔ پھر وہاں سے ہرقل حمص چلا گیا۔ ابھی حمص سے نکلا نہیں تھا کہ اس کے دوست کا خط ( اس کے جواب میں ) آ گیا۔ اس کی رائے بھی نبی کریم صلی اللہ علیہ وسلم کے ظہور کے بارے میں ہرقل کے موافق تھی کہ محمد صلی اللہ علیہ وسلم ( واقعی ) پیغمبر ہیں۔ اس کے بعد ہرقل نے روم کے بڑے آدمیوں کو اپنے حمص کے محل میں طلب کیا اور اس کے حکم سے محل کے دروازے بند کر لیے گئے۔ پھر وہ ( اپنے خاص محل سے ) باہر آیا اور کہا ”اے روم والو! کیا ہدایت اور کامیابی میں کچھ حصہ تمہارے لیے بھی ہے؟ اگر تم اپنی سلطنت کی بقا چاہتے ہو تو پھر اس نبی کی بیعت کر لو اور مسلمان ہو جاؤ“ ( یہ سننا تھا کہ ) پھر وہ لوگ وحشی گدھوں کی طرح دروازوں کی طرف دوڑے ( مگر ) انہیں بند پایا۔ آخر جب ہرقل نے ( اس بات سے ) ان کی یہ نفرت دیکھی اور ان کے ایمان لانے سے مایوس ہو گیا تو کہنے لگا کہ ان لوگوں کو میرے پاس لاؤ۔ ( جب وہ دوبارہ آئے ) تو اس نے کہا میں نے جو بات کہی تھی اس سے تمہاری دینی پختگی کی آزمائش مقصود تھی سو وہ میں نے دیکھ لی۔ تب ( یہ بات سن کر ) وہ سب کے سب اس کے سامنے سجدے میں گر پڑے اور اس سے خوش ہو گئے۔ بالآخر ہرقل کی آخری حالت یہ ہی رہی۔ ابوعبداللہ کہتے ہیں کہ اس حدیث کو صالح بن کیسان، یونس اور معمر نے بھی زہری سے روایت کیا ہے۔","section":1,"grades":[]},{"id":8,"text":"ہم سے عبیداللہ بن موسیٰ نے یہ حدیث بیان کی۔ انہوں نے کہا کہ ہمیں اس کی بابت حنظلہ بن ابی سفیان نے خبر دی۔ انہوں نے عکرمہ بن خالد سے روایت کی انہوں نے عبداللہ بن عمر رضی اللہ عنہما سے روایت کی کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا اسلام کی بنیاد پانچ چیزوں پر قائم کی گئی ہے۔ اول گواہی دینا کہ اللہ کے سوا کوئی معبود نہیں اور بیشک محمد صلی اللہ علیہ وسلم اللہ کے سچے رسول ہیں اور نماز قائم کرنا اور زکوٰۃ ادا کرنا اور حج کرنا اور رمضان کے روزے رکھنا۔","section":2,"grades":[]},{"id":9,"text":"ہم سے بیان کیا عبداللہ بن محمد جعفی نے، انہوں نے کہا ہم سے بیان کیا ابوعامر عقدی نے، انہوں نے کہا ہم سے بیان کیا سلیمان بن بلال نے، انہوں نے عبداللہ بن دینار سے، انہوں نے روایت کیا ابوصالح سے، انہوں نے نقل کیا ابوہریرہ رضی اللہ عنہ سے، انہوں نے نقل فرمایا جناب نبی کریم صلی اللہ علیہ وسلم سے آپ صلی اللہ علیہ وسلم نے فرمایا کہ ایمان کی ساٹھ سے کچھ اوپر شاخیں ہیں۔ اور حیاء ( شرم ) بھی ایمان کی ایک شاخ ہے۔","section":2,"grades":[]},{"id":10,"text":"ہم سے آدم بن ابی ایاس نے یہ حدیث بیان کی، ان کو شعبہ نے وہ عبداللہ بن ابی السفر اور اسماعیل سے روایت کرتے ہیں، وہ دونوں شعبی سے نقل کرتے ہیں، انہوں نے عبداللہ بن عمرو بن عاص رضی اللہ عنہما سے، وہ نبی کریم صلی اللہ علیہ وسلم سے روایت کرتے ہیں کہ آپ صلی اللہ علیہ وسلم نے فرمایا مسلمان وہ ہے جس کی زبان اور ہاتھ سے مسلمان بچے رہیں اور مہاجر وہ ہے جو ان کاموں کو چھوڑ دے جن سے اللہ نے منع فرمایا۔ ابوعبداللہ ( امام بخاری رحمہ اللہ ) نے فرمایا اور ابومعاویہ نے کہ ہم کو حدیث بیان کی داؤد بن ابی ہند نے، انہوں نے روایت کی عامر شعبی سے، انہوں نے کہا کہ میں نے سنا عبداللہ بن عمرو بن عاص سے، وہ حدیث بیان کرتے ہیں جناب نبی کریم صلی اللہ علیہ وسلم سے ( وہی مذکورہ حدیث ) اور کہا کہ عبدالاعلیٰ نے روایت کیا داؤد سے، انہوں نے عامر سے، انہوں نے عبداللہ بن عمرو بن عاص سے، انہوں نے نبی کریم صلی اللہ علیہ وسلم سے۔","section":2,"grades":[]},{"id":11,"text":"ہم کو سعید بن یحییٰ بن سعید اموی قریشی نے یہ حدیث سنائی، انہوں نے اس حدیث کو اپنے والد سے نقل کیا، انہوں نے ابوبردہ بن عبداللہ بن ابی بردہ سے، انہوں نے ابی بردہ سے، انہوں نے ابوموسیٰ رضی اللہ عنہ سے، وہ کہتے ہیں کہ لوگوں نے پوچھا یا رسول اللہ! کون سا اسلام افضل ہے؟ تو نبی کریم صلی اللہ علیہ وسلم نے فرمایا وہ جس کے ماننے والے مسلمانوں کی زبان اور ہاتھ سے سارے مسلمان سلامتی میں رہیں۔","section":2,"grades":[]},{"id":12,"text":"ہم سے حدیث بیان کی عمرو بن خالد نے، ان کو لیث نے، وہ روایت کرتے ہیں یزید سے، وہ ابوالخیر سے، وہ عبداللہ بن عمرو بن عاص رضی اللہ عنہما سے کہ ایک دن ایک آدمی نے نبی کریم صلی اللہ علیہ وسلم سے پوچھا کہ کون سا اسلام بہتر ہے؟ فرمایا کہ تم کھانا کھلاؤ، اور جس کو پہچانو اس کو بھی اور جس کو نہ پہچانو اس کو بھی، الغرض سب کو سلام کرو۔","section":2,"grades":[]},{"id":13,"text":"ہم سے حدیث بیان کی مسدد نے، ان کو یحییٰ نے، انہوں نے شعبہ سے نقل کیا، انہوں نے قتادہ سے، انہوں نے انس رضی اللہ عنہ خادم رسول اللہ صلی اللہ علیہ وسلم سے، انہوں نے نبی کریم صلی اللہ علیہ وسلم سے روایت کیا۔ اور شعبہ نے حسین معلم سے بھی روایت کیا، انہوں نے قتادہ سے، انہوں نے انس رضی اللہ عنہ سے، انہوں نے نبی کریم صلی اللہ علیہ وسلم سے نقل فرمایا کہ نبی کریم صلی اللہ علیہ وسلم نے فرمایا تم میں سے کوئی شخص ایماندار نہ ہو گا جب تک اپنے بھائی کے لیے وہ نہ چاہے جو اپنے نفس کے لیے چاہتا ہے۔","section":2,"grades":[]},{"id":14,"text":"ہم سے ابوالیمان نے حدیث بیان کی، ان کو شعیب نے، ان کو ابولزناد نے اعرج سے، انہوں نے ابوہریرہ رضی اللہ عنہ سے نقل کی کہ بیشک رسول اللہ صلی اللہ علیہ وسلم نے فرمایا، قسم ہے اس ذات کی جس کے ہاتھ میں میری جان ہے۔ تم میں سے کوئی بھی ایماندار نہ ہو گا جب تک میں اس کے والد اور اولاد سے بھی زیادہ اس کا محبوب نہ بن جاؤں۔","section":2,"grades":[]},{"id":15,"text":"ہمیں حدیث بیان کی یعقوب بن ابراہیم نے، ان کو ابن علیہ نے، وہ عبدالعزیز بن صہیب سے روایت کرتے ہیں، وہ انس رضی اللہ عنہ سے وہ نبی کریم صلی اللہ علیہ وسلم سے نقل کرتے ہیں اور ہم کو آدم بن ابی ایاس نے حدیث بیان کی، ان کو شعبہ نے، وہ قتادہ سے نقل کرتے ہیں، وہ انس رضی اللہ عنہ سے کہ نبی کریم صلی اللہ علیہ وسلم نے فرمایا تم میں سے کوئی شخص ایماندار نہ ہو گا جب تک اس کے والد اور اس کی اولاد اور تمام لوگوں سے زیادہ اس کے دل میں میری محبت نہ ہو جائے۔","section":2,"grades":[]},{"id":16,"text":"ہمیں محمد بن مثنیٰ نے یہ حدیث بیان کی، ان کو عبدالوہاب ثقفی نے، ان کو ایوب نے، وہ ابوقلابہ سے روایت کرتے ہیں، وہ انس رضی اللہ عنہ سے ناقل ہیں وہ نبی کریم صلی اللہ علیہ وسلم سے آپ صلی اللہ علیہ وسلم نے فرمایا تین خصلتیں ایسی ہیں کہ جس میں یہ پیدا ہو جائیں اس نے ایمان کی مٹھاس کو پا لیا۔ اول یہ کہ اللہ اور اس کا رسول اس کے نزدیک سب سے زیادہ محبوب بن جائیں، دوسرے یہ کہ وہ کسی انسان سے محض اللہ کی رضا کے لیے محبت رکھے۔ تیسرے یہ کہ وہ کفر میں واپس لوٹنے کو ایسا برا جانے جیسا کہ آگ میں ڈالے جانے کو برا جانتا ہے۔","section":2,"grades":[]},{"id":17,"text":"ہم سے اس حدیث کو ابوالولید نے بیان کیا، ان سے شعبہ نے، انہیں عبداللہ بن جبیر نے خبر دی، وہ کہتے ہیں کہ ہم نے انس بن مالک رضی اللہ عنہ سے اس کو سنا، وہ رسول اللہ صلی اللہ علیہ وسلم سے روایت کرتے ہیں کہ آپ صلی اللہ علیہ وسلم نے فرمایا انصار سے محبت رکھنا ایمان کی نشانی ہے اور انصار سے کینہ رکھنا نفاق کی نشانی ہے۔","section":2,"grades":[]},{"id":18,"text":"ہم سے اس حدیث کو ابوالیمان نے بیان کیا، ان کو شعیب نے خبر دی، وہ زہری سے نقل کرتے ہیں، انہیں ابوادریس عائذ اللہ بن عبداللہ نے خبر دی کہ عبادہ بن صامت رضی اللہ عنہ جو بدر کی لڑائی میں شریک تھے اور لیلۃالعقبہ کے ( بارہ ) نقیبوں میں سے تھے۔ فرماتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے اس وقت جب آپ کے گرد صحابہ کی ایک جماعت بیٹھی ہوئی تھی فرمایا کہ مجھ سے بیعت کرو اس بات پر کہ اللہ کے ساتھ کسی کو شریک نہ کرو گے، چوری نہ کرو گے، زنا نہ کرو گے، اپنی اولاد کو قتل نہ کرو گے اور نہ عمداً کسی پر کوئی ناحق بہتان باندھو گے اور کسی بھی اچھی بات میں ( اللہ کی ) نافرمانی نہ کرو گے۔ جو کوئی تم میں ( اس عہد کو ) پورا کرے گا تو اس کا ثواب اللہ کے ذمے ہے اور جو کوئی ان ( بری باتوں ) میں سے کسی کا ارتکاب کرے اور اسے دنیا میں ( اسلامی قانون کے تحت ) سزا دے دی گئی تو یہ سزا اس کے ( گناہوں کے ) لیے بدلا ہو جائے گی اور جو کوئی ان میں سے کسی بات میں مبتلا ہو گیا اور اللہ نے اس کے ( گناہ ) کو چھپا لیا تو پھر اس کا ( معاملہ ) اللہ کے حوالہ ہے، اگر چاہے معاف کرے اور اگر چاہے سزا دیدے۔ ( عبادہ کہتے ہیں کہ ) پھر ہم سب نے ان ( سب باتوں ) پر آپ صلی اللہ علیہ وسلم سے بیعت کر لی۔","section":2,"grades":[]},{"id":19,"text":"ہم سے (اس حدیث کو) عبداللہ بن مسلمہ نے بیان کیا، انہوں نے اسے مالک رحمہ اللہ سے نقل کیا، انہوں نے عبدالرحمٰن بن عبداللہ بن ابی صعصعہ سے، انہوں نے اپنے باپ (عبداللہ رحمہ اللہ) سے، وہ ابو سعید خدری سے نقل کرتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا وہ وقت قریب ہے جب مسلمان کا ( سب سے ) عمدہ مال ( اس کی بکریاں ہوں گی ) ۔ جن کے پیچھے وہ پہاڑوں کی چوٹیوں اور برساتی وادیوں میں اپنے دین کو بچانے کے لیے بھاگ جائے گا۔","section":2,"grades":[]},{"id":20,"text":"یہ حدیث ہم سے محمد بن سلام نے بیان کی، وہ کہتے ہیں کہ انہیں اس کی عبدہ نے خبر دی، وہ ہشام سے نقل کرتے ہیں، ہشام عائشہ رضی اللہ عنہا سے وہ فرماتی ہیں کہ رسول اللہ صلی اللہ علیہ وسلم لوگوں کو کسی کام کا حکم دیتے تو وہ ایسا ہی کام ہوتا جس کے کرنے کی لوگوں میں طاقت ہوتی ( اس پر ) صحابہ رضی اللہ عنہم نے عرض کیا کہ یا رسول اللہ! ہم لوگ تو آپ جیسے نہیں ہیں ( آپ تو معصوم ہیں ) اور آپ کی اللہ پاک نے اگلی پچھلی سب لغزشیں معاف فرما دی ہیں۔ ( اس لیے ہمیں اپنے سے کچھ زیادہ عبادت کرنے کا حکم فرمائیے ) ( یہ سن کر ) آپ صلی اللہ علیہ وسلم ناراض ہوئے حتیٰ کہ خفگی آپ صلی اللہ علیہ وسلم کے چہرہ مبارک سے ظاہر ہونے لگی۔ پھر فرمایا کہ بیشک میں تم سب سے زیادہ اللہ سے ڈرتا ہوں اور تم سب سے زیادہ اسے جانتا ہوں۔ ( پس تم مجھ سے بڑھ کر عبادت نہیں کر سکتے ) ۔","section":2,"grades":[]},{"id":21,"text":"اس حدیث کو ہم سے سلیمان بن حرب نے بیان کیا، ان سے شعبہ نے، وہ قتادہ سے روایت کرتے ہیں، وہ انس رضی اللہ عنہ سے، اور وہ نبی کریم صلی اللہ علیہ وسلم سے نقل کرتے ہیں کہ آپ صلی اللہ علیہ وسلم نے فرمایا، جس شخص میں یہ تین باتیں ہوں گی وہ ایمان کا مزہ پالے گا، ایک یہ کہ وہ شخص جسے اللہ اور اس کا رسول ان کے ماسوا سے زیادہ عزیز ہوں اور دوسرے یہ کہ جو کسی بندے سے محض اللہ ہی کے لیے محبت کرے اور تیسری بات یہ کہ جسے اللہ نے کفر سے نجات دی ہو، پھر دوبارہ کفر اختیار کرنے کو وہ ایسا برا سمجھے جیسا آگ میں گر جانے کو برا جانتا ہے۔","section":2,"grades":[]},{"id":22,"text":"ہم سے اسماعیل نے یہ حدیث بیان کی، وہ کہتے ہیں ان سے مالک نے، وہ عمرو بن یحییٰ المازنی سے نقل کرتے ہیں، وہ اپنے باپ سے روایت کرتے ہیں اور وہ ابو سعید خدری رضی اللہ عنہ اور وہ نبی اکرم صلی اللہ علیہ وسلم سے نقل کرتے ہیں کہ آپ صلی اللہ علیہ وسلم نے فرمایا جب جنتی جنت میں اور دوزخی دوزخ میں داخل ہو جائیں گے۔ اللہ پاک فرمائے گا، جس کے دل میں رائی کے دانے کے برابر ( بھی ) ایمان ہو، اس کو بھی دوزخ سے نکال لو۔ تب ( ایسے لوگ ) دوزخ سے نکال لیے جائیں گے اور وہ جل کر کوئلے کی طرح سیاہ ہو چکے ہوں گے۔ پھر زندگی کی نہر میں یا بارش کے پانی میں ڈالے جائیں گے۔ ( یہاں راوی کو شک ہو گیا ہے کہ اوپر کے راوی نے کون سا لفظ استعمال کیا ) اس وقت وہ دانے کی طرح اگ آئیں گے جس طرح ندی کے کنارے دانے اگ آتے ہیں۔ کیا تم نے نہیں دیکھا کہ دانہ زردی مائل پیچ در پیچ نکلتا ہے۔ وہیب نے کہا کہ ہم سے عمرو نے ( «حياء» کی بجائے ) «حياة»،‏‏‏‏ اور ( «خردل من ايمان» ) کی بجائے ( «خردل من خير» ) کا لفظ بیان کیا۔","section":2,"grades":[]},{"id":23,"text":"ہم سے محمد بن عبیداللہ نے یہ حدیث بیان کی، ان سے ابراہیم بن سعد نے، وہ صالح سے روایت کرتے ہیں، وہ ابن شہاب سے، وہ ابوامامہ بن سہل بن حنیف سے راوی ہیں، وہ ابو سعید خدری رضی اللہ عنہ سے، وہ کہتے تھے کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا کہ میں ایک وقت سو رہا تھا، میں نے خواب میں دیکھا کہ لوگ میرے سامنے پیش کیے جا رہے ہیں اور وہ کرتے پہنے ہوئے ہیں۔ کسی کا کرتہ سینے تک ہے اور کسی کا اس سے نیچا ہے۔ ( پھر ) میرے سامنے عمر بن الخطاب لائے گئے۔ ان ( کے بدن ) پر ( جو ) کرتا تھا۔ اسے وہ گھسیٹ رہے تھے۔ ( یعنی ان کا کرتہ زمین تک نیچا تھا ) صحابہ نے پوچھا کہ یا رسول اللہ! اس کی کیا تعبیر ہے؟ آپ صلی اللہ علیہ وسلم نے فرمایا کہ ( اس سے ) دین مراد ہے۔","section":2,"grades":[]},{"id":24,"text":"عبداللہ بن یوسف نے ہم سے بیان کیا، وہ کہتے ہیں کہ ہمیں مالک بن انس نے ابن شہاب سے خبر دی، وہ سالم بن عبداللہ سے نقل کرتے ہیں، وہ اپنے باپ (عبداللہ بن عمر رضی اللہ عنہما) سے کہ ایک دفعہ رسول اللہ صلی اللہ علیہ وسلم ایک انصاری شخص کے پاس سے گزرے اس حال میں کہ وہ اپنے ایک بھائی سے کہہ رہے تھے کہ تم اتنی شرم کیوں کرتے ہو۔ آپ صلی اللہ علیہ وسلم نے اس انصاری سے فرمایا کہ اس کو اس کے حال پر رہنے دو کیونکہ حیاء بھی ایمان ہی کا ایک حصہ ہے۔","section":2,"grades":[]},{"id":25,"text":"اس حدیث کو ہم سے عبداللہ بن محمد مسندی نے بیان کیا، ان سے ابوروح حرمی بن عمارہ نے، ان سے شعبہ نے، وہ واقد بن محمد سے روایت کرتے ہیں، وہ کہتے ہیں میں نے یہ حدیث اپنے باپ سے سنی، وہ ابن عمر رضی اللہ عنہما سے روایت کرتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا، مجھے ( اللہ کی طرف سے ) حکم دیا گیا ہے کہ لوگوں سے جنگ کروں اس وقت تک کہ وہ اس بات کا اقرار کر لیں کہ اللہ کے سوا کوئی معبود نہیں ہے اور یہ کہ محمد صلی اللہ علیہ وسلم اللہ کے سچے رسول ہیں اور نماز ادا کرنے لگیں اور زکوٰۃ دیں، جس وقت وہ یہ کرنے لگیں گے تو مجھ سے اپنے جان و مال کو محفوظ کر لیں گے، سوائے اسلام کے حق کے۔ ( رہا ان کے دل کا حال تو ) ان کا حساب اللہ کے ذمے ہے۔","section":2,"grades":[]},{"id":26,"text":"ہم سے احمد بن یونس اور موسیٰ بن اسماعیل دونوں نے بیان کیا، انہوں نے کہا ہم سے ابراہیم بن سعید نے بیان کیا، انہوں نے کہا ہم سے ابن شہاب نے بیان کیا، وہ سعید بن المسیب رضی اللہ عنہ سے روایت کرتے ہیں، وہ ابوہریرہ رضی اللہ عنہ سے کہ رسول اللہ صلی اللہ علیہ وسلم سے دریافت کیا گیا کہ کون سا عمل سب سے افضل ہے؟ آپ صلی اللہ علیہ وسلم نے فرمایا ”اللہ اور اس کے رسول پر ایمان لانا“ کہا گیا، اس کے بعد کون سا؟ آپ صلی اللہ علیہ وسلم نے فرمایا کہ ”اللہ کی راہ میں جہاد کرنا“ کہا گیا، پھر کیا ہے؟ آپ صلی اللہ علیہ وسلم نے فرمایا ”حج مبرور“۔","section":2,"grades":[]},{"id":27,"text":"ہم سے ابوالیمان نے بیان کیا، وہ کہتے ہیں کہ ہمیں شعیب نے زہری سے خبر دی، انہیں عامر بن سعد بن ابی وقاص نے اپنے والد سعد رضی اللہ عنہ سے سن کر یہ خبر دی کہ رسول اللہ صلی اللہ علیہ وسلم نے چند لوگوں کو کچھ عطیہ دیا اور سعد وہاں موجود تھے۔ ( وہ کہتے ہیں کہ ) رسول اللہ صلی اللہ علیہ وسلم نے ان میں سے ایک شخص کو کچھ نہ دیا۔ حالانکہ وہ ان میں مجھے سب سے زیادہ پسند تھا۔ میں نے کہا: یا رسول اللہ! آپ نے فلاں کو کچھ نہ دیا حالانکہ میں اسے مومن گمان کرتا ہوں۔ آپ صلی اللہ علیہ وسلم نے فرمایا مومن یا مسلمان؟ میں تھوڑی دیر چپ رہ کر پھر پہلی بات دہرانے لگا۔ نبی کریم صلی اللہ علیہ وسلم نے بھی دوبارہ وہی جواب دیا۔ پھر آپ صلی اللہ علیہ وسلم نے فرمایا کہ اے سعد! باوجود یہ کہ ایک شخص مجھے زیادہ عزیز ہے ( پھر بھی میں اسے نظر انداز کر کے ) کسی اور دوسرے کو اس خوف کی وجہ سے یہ مال دے دیتا ہوں کہ ( وہ اپنی کمزوری کی وجہ سے اسلام سے پھر جائے اور ) اللہ اسے آگ میں اوندھا ڈال دے۔ اس حدیث کو یونس، صالح، معمر اور زہری کے بھتیجے عبداللہ نے زہری سے روایت کیا۔","section":2,"grades":[]},{"id":28,"text":"ہم سے قتیبہ نے بیان کیا، انہوں نے کہا ہم سے لیث نے بیان کیا، انہوں نے یزید بن ابی حبیب سے، انہوں نے ابوالخیر سے، انہوں نے عبداللہ بن عمرو رضی اللہ عنہما سے کہ ایک آدمی نے رسول اللہ صلی اللہ علیہ وسلم سے پوچھا کون سا اسلام بہتر ہے؟ آپ صلی اللہ علیہ وسلم نے فرمایا کہ تو کھانا کھلائے اور ہر شخص کو سلام کرے خواہ اس کو تو جانتا ہو یا نہ جانتا ہو۔","section":2,"grades":[]},{"id":29,"text":"اس حدیث کو ہم سے عبداللہ بن مسلمہ نے بیان کیا، وہ امام مالک سے، وہ زید بن اسلم سے، وہ عطاء بن یسار سے، وہ عبداللہ ابن عباس رضی اللہ عنہما سے نقل کرتے ہیں کہ نبی کریم صلی اللہ علیہ وسلم نے فرمایا مجھے دوزخ دکھلائی گئی تو اس میں زیادہ تر عورتیں تھیں جو کفر کرتی ہیں۔ کہا گیا یا رسول اللہ! کیا وہ اللہ کے ساتھ کفر کرتی ہیں؟ آپ صلی اللہ علیہ وسلم نے فرمایا کہ خاوند کی ناشکری کرتی ہیں۔ اور احسان کی ناشکری کرتی ہیں۔ اگر تم عمر بھر ان میں سے کسی کے ساتھ احسان کرتے رہو۔ پھر تمہاری طرف سے کبھی کوئی ان کے خیال میں ناگواری کی بات ہو جائے تو فوراً کہہ اٹھے گی کہ میں نے کبھی بھی تجھ سے کوئی بھلائی نہیں دیکھی۔","section":2,"grades":[]},{"id":30,"text":"ہم سے سلیمان بن حرب نے بیان کیا، کہا ہم سے شعبہ نے بیان کیا، انہوں نے اسے واصل احدب سے، انہوں نے معرور سے، کہا میں ابوذر سے ربذہ میں ملا وہ ایک جوڑا پہنے ہوئے تھے اور ان کا غلام بھی جوڑا پہنے ہوئے تھا۔ میں نے اس کا سبب دریافت کیا تو کہنے لگے کہ میں نے ایک شخص یعنی غلام کو برا بھلا کہا تھا اور اس کی ماں کی غیرت دلائی ( یعنی گالی دی ) تو رسول اللہ صلی اللہ علیہ وسلم نے یہ معلوم کر کے مجھ سے فرمایا اے ابوذر! تو نے اسے ماں کے نام سے غیرت دلائی، بیشک تجھ میں ابھی کچھ زمانہ جاہلیت کا اثر باقی ہے۔ ( یاد رکھو ) ماتحت لوگ تمہارے بھائی ہیں۔ اللہ نے ( اپنی کسی مصلحت کی بنا پر ) انہیں تمہارے قبضے میں دے رکھا ہے تو جس کے ماتحت اس کا کوئی بھائی ہو تو اس کو بھی وہی کھلائے جو آپ کھاتا ہے اور وہی کپڑا اسے پہنائے جو آپ پہنتا ہے اور ان کو اتنے کام کی تکلیف نہ دو کہ ان کے لیے مشکل ہو جائے اور اگر کوئی سخت کام ڈالو تو تم خود بھی ان کی مدد کرو۔","section":2,"grades":[]}]}'),i=JSON.parse('{"name":"مسلم","sections":{"0":"تعارف","1":"ایمان کی کتاب"},"hadiths":[{"id":3,"text":"حضرت انس بن مالک ‌رضی ‌اللہ ‌عنہ ‌ ‌ سے روایت ہے ، کہا : مجھے تمہارے سامنے زیادہ احادیث بیان کرنے سے یہ بات روکتی ہے کہ رسول اللہﷺ نے فرمایا تھا : ’’جس نے عمداً مجھ پر جھوٹ بولا وہ آگ میں اپنا ٹھکانا بنا لے","section":0,"grades":[]},{"id":4,"text":"حضرت ابو ہریرہ ‌رضی ‌اللہ ‌عنہ ‌ ‌ سے روایت ہے ، کہا : رسول اللہﷺ نے فرمایا : ’’جس نے عمداً مجھ پر جھوٹ بولا وہ آگ میں اپنا ٹھکانا بنا لے ۔","section":0,"grades":[]},{"id":15,"text":"محمد بن عبد اللہ بن نمیر ‘ زہیر بن حرب ‘ عبداللہ بن یزید ‘ سعد بن ابی ایوب ‘ ابوہانی نے ابو عثمان مسلم بن یسار سے ، انہوں نے ابوہریرہ ‌رضی ‌اللہ ‌عنہ ‌ ‌ سے ، انہوں نے رسول اللہﷺ سے روایت کی کہ آپ نے فرمایا : ’’میری امت کے آخری زمانے میں ایسے لوگ ہوں گے جو تمہارے سامنے ایسی حدیثیں بیان کریں گے جو تم نے سنی ہوں گی نہ تمہارے آباء نے ، تم اس قماش کے لوگوں سے دور رہنا ۔ ‘ ‘","section":0,"grades":[]},{"id":93,"text":"کہمس سے ا بن بریدہ سے ، انہوں نے یحیی بن یعمر سےروایت کی ، انہوں نے کہا کہ سب سے پہلا شخص جس نے بصرہ میں تقدیر ( سے انکار ) کی بات کی ، معبد جہنی تھا میں ( یحیی ) اور حمید بن عبد الرحمن خمیری حج یا عمرے کے ارادے سے نکلے ، ہم نے ( آپس میں ) کہا : کاش! رسول اللہ ﷺ کے صحابہ میں سے کسی کے ساتھ ہماری ملاقات ہو جائے تو ہم ان سے تقدیر کے بارے میں ان ( آج کل کے ) لوگوں کی کہی ہوئی باتوں کے متعلق دریافت کر لیں ۔ توفیق الہٰی سے ہمیں حضرت عبد اللہ بن عمر بن خطاب ‌رضی ‌اللہ ‌عنہ ‌ ‌ مسجد میں داخل ہوتے ہوئے مل گئے ۔ میں اور میرے ساتھ نے ان کے درمیان میں لے لیا ، ایک ان کی دائیں طرف تھا اور دوسرا ان کی بائیں طرف ۔ مجھے اندازہ تھا کہ میرا ساتھی گفتگو ( کامعاملہ ) میرے سپرد کرے گا ، چنانچہ میں نے عرض کی : اے ابو عبدالرحمن ! ( یہ عبد اللہ بن عمر ‌رضی ‌اللہ ‌عنہ ‌ ‌ کی کنیت ہے ) واقعہ یہ ہے کہ ہماری طرف کچھ ایسے لوگ ظاہر ہوئے جو قرآن مجید پڑھتے ہیں اور علم حاصل کرتے ہیں ( اور ان کے حالات بیان کیے ) ان لوگوں کا خیال ہے کہ تقدیر کچھ نہیں ، ( ہر ) کام نئے سرے سے ہو رہا ہے ( پہلے اس بارے میں نہ کچھ طے ہے ، نہ اللہ کا اس کاعلم ہے ۔ ) ابن عمر ‌رضی ‌اللہ ‌عنہ ‌ ‌ نے فرمایا : جب تمہاری ان لوگوں سے ملاقات ہو تو انہیں بتا دینا کہ میں ان سے بری ہوں اور وہ مجھ سے بری ہیں ۔ اس ( ذات ) کی قسم جس ( کے نام ) کے ساتھ عبد اللہ بن عمر حلف اٹھاتا ہے ! اگر ان میں سے کسی کو پاس احد پہاڑ کے برابر سونا ہو اور وہ اسے خرچ ( بھی ) کر دے تو اللہ تعالیٰ اس کی طرف سے اس کوقبول نہیں فرمائے گا یہاں تک کہ وہ تقدیر پر ایمان لے آئے ، پھر کہا : مجھے میرے والد عمر بن خطاب ‌رضی ‌اللہ ‌عنہ ‌ ‌ نے بتایا : ایک دن ہم رسول ا للہ ﷺ کی خدمت میں حاضر تھے کہ اچانک ایک شخص ہمارے سامنے نمودار ہوا ۔ اس کے کپڑے انتہائی سفید اوربا ل انتہائی سیاہ تھے ۔ اس پر سفر کا کوئی اثر دکھائی دیتا تھا نہ ہم میں سے کوئی اسے پہچانتا تھا حتیٰ کہ وہ آ کر نبی اکرمﷺ کے پاس بیٹھ گیا اور اپنے گھٹنے آپ کے گھٹنوں سے ملا دیے ، اور اپنے ہاتھ آپﷺ کی را نوں پر رکھ دیے ، اور کہا : اے محمد ( ﷺ ) ! مجھے اسلام کے بارے میں بتائیے ۔ رسول اللہ ﷺ نے فرمایا : ’’اسلام یہ ہے کہ تم اس بات کی گواہی دو کہ اللہ تعالیٰ کے سوا کوئی عبادت کےلائق نہیں اور محمدﷺ اس کے رسول ہیں ، نماز کا اہتمام کرو ، زکاۃ ادا کرو ، رمضان کے روزے رکھو اور اگر اللہ کے گھر تک راستہ ( طے کرنے ) کی استطاعت ہو تو اس کا حج کرو ۔ ‘ ‘ اس نے کہا : آپ نے سچ فرمایا ۔ ( حضرت عمر ‌رضی ‌اللہ ‌عنہ ‌ ‌ نے ) کہا : ہمیں اس پر تعجب ہوا کہ آپ سے پوچھتا ہے اور ( خود ہی ) آپ کی تصدیق کرتا ہے ۔ اس نے کہا : مجھے ایمان کے بارے میں بتائیے ۔ آپ نے فرمایا : ’’یہ کہ تم اللہ تعالیٰ ، اس کے فرشتوں ، اس کی کتابوں ، اس کے رسولوں اور آخری دن ( یوم قیامت ) پر ایمان رکھو اور اچھی اور بری تقدیر پر بھی ایمان لاؤ ۔ ‘ ‘ اس نے کہا : آپ نے درست فرمایا ۔ ( پھر ) اس نے کہا : مجھے احسان کے بارے میں بتائیے ۔ آپ نے فرمایا : یہ کہ تم اللہ تعالیٰ کی عبادت اس طرح کرو گویا تم اسے دیکھ رہے ہو اور اگر تم اسے نہیں دیکھ رہے تو وہ تمہیں دیکھ رہا ہے ۔ ‘ ‘ اس نے کہا : تومجھے قیات کے بارے میں بتائیے ۔ آپ نے فرمایا : ’’جس سے اس ( قیامت ) کے بارے میں سوال کیا جا رہا ہے ، وہ پوچھنے والے سے زیادہ نہیں جانتا ۔ ‘ ‘ اس نے کہا : تو مجھے اس کی علامات بتا دیجیے ۔ آپ نے فرمایا : ’’ ( علامات یہ ہیں کہ ) لونڈی اپنی مالکہ کو جنم دے اور یہ کہ تم ننگے پاؤں ، ننگے بدن ، محتاج ، بکریاں چرانے والوں کو دیکھو کہ وہ اونچی سے اونچی عمارتیں بنانے میں ایک دوسرے کے ساتھ مقابلہ کر رہے ہیں ۔ ‘ ‘ حضرت عمر ‌رضی ‌اللہ ‌عنہ ‌ ‌ نےکہا : پھر وہ سائل چلا گیا ، میں کچھ دیر اسی عالم میں رہا ، پھر آپ ﷺ نے مجھ سے کہا : ’’اے عمر !تمہیں معلوم ہے کہ پوچھنے والا کون تھا؟ ‘ ‘ میں نے عرض کی : اللہ اور اس کا رسول زیادہ آگاہ ہیں ۔ آپﷺ نے فرمایا : ’’وہ جبرئیل تھے ، تمہارے پاس آئے تھے ، تمہیں تمہارا دین سکھا رہے تھے ۔ ‘ ‘","section":1,"grades":[]},{"id":94,"text":"کہمس کے بجائے مطر وراق نےعبد اللہ بن بریدہ سے ، انہوں نے یحیی بن یعمر سے نقل کیا کہ جب معبد ( جہنی ) نے تقدیر کے بارے میں وہ ( سب ) کہا جو کہا ، تو ہم نے اسے سخت ناپسند کیا ( یحییٰ نے کہا ) میں اور حمید بن عبد الرحمٰن حمیری نے حج کیا .... اس کے بعد انہوں نے کہمس کے واسطے سے بیان کردہ حدیث کے مطابق حدیث بیان کی ، البتہ الفاظ میں کچھ کمی بیشی ہے","section":1,"grades":[]},{"id":95,"text":"(عبد اللہ بن بریدہ کے ایک تیسرے شاگرد ) عثمان بن غیاث نے یحییٰ بن یعمر اور حمید بن عبد الرحمٰن دونوں سے روایت کی ، دونوں نےکہا : ہم عبد اللہ بن عمر ‌رضی ‌اللہ ‌عنہ ‌ ‌ سے ملے اور ہم سے تقدیر کی بات کی اور وہ لوگ ( منکرین تقدیر ) جو کچھ کہتے ہیں ، اس کا ذکر کیا ۔ اس کے بعد ( عثمان بن غیاث نے ) سابقہ راویوں کے مطابق حضرت عمر ‌رضی ‌اللہ ‌عنہ ‌ ‌ سے مرفوعاً روایت کی ۔ اس روایت میں کچھ الفاظ زیادہ ہیں اور کچھ انہوں نے کم کیے ہیں ۔","section":1,"grades":[]},{"id":96,"text":"معتمر کے والد ( سلیمان بن طرخان ) نے یحییٰ بن یعمر سے ، انہوں نے عبد اللہ بن عمر ‌رضی ‌اللہ ‌عنہ ‌ ‌ سے ، انہوں نے حضرت عمر ‌رضی ‌اللہ ‌عنہ ‌ ‌ سے اور انہوں نے نبی ﷺ سے اسی طرح روایت کی جس طرح مذکورہ اساتذہ نے روایت کی ۔","section":1,"grades":[]},{"id":97,"text":"اسماعیل بن ابراہیم ( ابن علیہ ) نے ابو حیان سے ، انہوں نے ابو زرعہ بن عمرو بن جریر سے اور انہوں نے حضرت ابو ہریرہ ‌رضی ‌اللہ ‌عنہ ‌ ‌ سے روایت کی ، کہا : رسول اللہ ﷺ ایک دن لوگوں کے سامنے ( تشریف فرما ) تھے ، ایک آدمی آپﷺ کے پاس آیا اور پوچھا : اے اللہ کے رسول ! ایمان کیا ہے ؟ آپ نے فرمایا : ’’تم اللہ تعالیٰ ، اس کے فرشتوں ، اس کی کتاب ، ( قیامت کے روز ) اس سے ملاقات ( اس کے سامنے حاضری ) اور اس کے رسولوں پر ایمان لاؤ اور آخری ( بار زندہ ہو کر ) اٹھنے پر ( بھی ) ایمان لے آؤ ۔ ‘ ‘ اس نے کہا : اے اللہ کے رسول ! اسلام کیا ہے ؟ آپﷺ نے فرمایا : ’’اسلام یہ ہے کہ اللہ تعالیٰ کی عبادت کرو اور اس کے ساتھ کسی چیز کو شریک نہ ٹھہراؤ ، لکھی ( فرض کی ) گئی نمازوں کی ‎پابندی کرو ، فرض کی گئی زکاۃ ادا کرو ۔ اور رمضان کے روزے رکھو ۔ ‘ ‘ اس نے کہا : اے اللہ کے رسول ! احسان کیا ہے ؟ آپﷺ نے فرمایا : ’’ اللہ تعالیٰ کی عبادت اس طرح کرو گویا تم اسے دیکھ رہے ہو اور اگر تم اسے نہیں دیکھ رہے ہو تو وہ یقیناً تمہیں دیکھ رہا ہے ۔ ‘ ‘ اس نے کہا : اے اللہ کے رسول ! قیامت کب ( قائم ) ہو گی ؟ آپ ﷺ نے فرمایا : ’’جس سے سوال کیا گیا ہے ، وہ ا س کے بارے میں پوچھنے والے سےزیادہ آگاہ نہیں ۔ لیکن میں تمہیں قیامت کی نشانیاں بتائے دیتا ہوں : جب لونڈی اپنا مالک جنے گی تو یہ اس کی نشانیوں میں سے ہے ، اور جب ننگے بدن اور ننگے پاؤں والے لوگوں کے سردار بن جائیں گے تو یہ اس کی نشانیوں میں سے ہے ، اور جب بھیڑ بکریاں چرانے والے ، اونچی اونچی عمارتیں بنانے میں ایک دوسرے سے مقابلہ کریں گے تو یہ اس کی علامات میں سے ہے ۔ ( قیامت کے وقت کا علم ) ان پانچ چیزوں میں سے ہے جنہیں اللہ تعالیٰ کے سوا کوئی نہیں جانتا ہے ‘ ‘ پھر آپ ﷺ نے یہ آیت پڑھی : ’’بے شک اللہ تعالیٰ ہی کے پاس قیامت کا علم ہے ، وہی بارش برساتا ہے اور وہی جانتا ہے کہ ارحام ( ماؤں کے پیٹوں ) میں کیا ہے ، کوئی ذی روح نہیں جانتا کہ وہ کل کیا کرے گا ، نہ کسی متنفس کویہ معلوم ہے کہ وہ زمین کے کس حصے میں فوت ہو گا ، بلاشبہ اللہ تعالیٰ علم والا خبردار ہے ۔ ‘ ‘ حضرت ابو ہریرہ ‌رضی ‌اللہ ‌عنہ ‌ ‌ نے ) کہا : پھر وہ آدمی واپس چلا گیا تو رسول اللہ ﷺ نے فرمایا : ’’ اس آ دمی کو میرے پاس واپس لاؤ ۔ ‘ ‘ صحابہ کرام ‌رضی ‌اللہ ‌عنہ ‌ ‌ اسے واپس لانے کے لیے بھاک دوڑ کرنےلگے تو انہیں کچھ نظر نہ آیا ، رسول اللہ نے فرمایا : ’’یہ جبریل ‌علیہ ‌السلام ‌ تھے جو لوگوں کو ان کا دین سکھانے آئے تھے ۔ ‘ ‘","section":1,"grades":[]},{"id":98,"text":"(ابن علیہ کے بجائے ) محمد بن بشر نےکہا : ہمیں ابو حیان نے سابقہ سند سے وہی حدیث بیان کی ، البتہ ان کی روایت میں : إذا ولدت الأمة بعلها ’’ جب لونڈی اپنا مالک جنے گی ‘ ‘ ( رب کی جگہ بعل ، یعنی مالک ) کے الفاظ ہیں ۔ ( أمة سے مملوکہ ) لونڈیاں مراد ہیں ۔","section":1,"grades":[]},{"id":99,"text":"حضرت ابو ہریرہ ‌رضی ‌اللہ ‌عنہ ‌ ‌ سے روایت ہے کہ رسول اللہ ﷺ نے فرمایا : ’’مجھ سے ( دین کے بارے میں ) پوچھ لو ۔ ‘ ‘ صحابہ کرام ‌رضی ‌اللہ ‌عنہ ‌ ‌ آپ ﷺ سے اتنے مرعوب ہوئے کہ سوال نہ کر سکے ، تب ایک آدمی آیا اور آپ ﷺ کے دونوں گھٹنوں کے قریب بیٹھ گیا ، پھر کہنے لگا : اے اللہ کے رسول ! اسلام کیا ؟ آپ نے فرمایا : ’’ تم اللہ تعالیٰ کے ساتھ کسی کو شریک نہ ٹھہراؤ ، نماز کا اہتمام کرو ، زکاۃ ادا کرو اور رمضان کے روزے رکھو ۔ ‘ ‘ اس نے کہا : آپ نے سچ فرمایا ۔ ( پھر ) پوچھا : اے اللہ کے رسول ! ایمان کیا ہے ؟ آپ نے فرمایا : ’’یہ کہ تم اللہ ، اس کے فرشتوں ، اس کی کتاب ، ( قیات کے روز ) اس سے ملاقات اور اس کے رسولوں پر ایمان لاؤ ، مرنے کے بعد اٹھنے پر ایمان لاؤ اور ہر ( امر کی ) تقدیر پر ایمان لاؤ ۔ ‘ ‘ اس نے کہا : آپ نے درست فرمایا ۔ ( پھر ) کہنے لگا : اے اللہ کے رسول ! احسان کیا ہے ؟ آپ نے فرمایا : ’’تم اللہ تعالیٰ سےاس طرح ڈرو گویا تم اسے دیکھ رہے ہو ، پھر اگر تم اسے نہیں رہے تو وہ یقینا ً تمہیں دیکھ رہا ہے ۔ ‘ ‘ اس نے کہا : آپ نے صحیح فرمایا : ( پھر ) پوچھا : اے اللہ کے رسول ! قیامت کب قائم ہو گی ؟ آپ نے جواب دیا : ’’جس سے قیامت کے بارے میں پوچھا جا رہا ہے ، وہ پوچھنے والے سے زیادہ نہیں جانتا ۔ میں تمہیں اس کی علامات بتائے دیتا ہوں : جب دیکھو کہ عورت اپنے آقا کو جنم دیتی ہے تو یہ اس کی نشانیوں میں سے ہے اور جب دیکھو کہ ننگے پاؤں اور ننگے بدن والے ، گونگے اور بہرے زمین کے بادشاہ ہیں تو یہ اس کی علامات میں سے ہے اور جب دیکھو کہ بھیڑ بکریوں کے چروا ہے اونچی سے اونچی عمارات بنانے میں باہم مقابلہ کر رہے ہیں تو یہ بھی اس کی نشانیوں میں سے ہے ۔ یہ ( قیامت کا وقوع ) غیب کی ان پانچ چیزوں میں سے ہے ۔ جن کو اللہ تعالیٰ کے سوا کوئی نہیں جانتا ۔ ‘ ‘ پھر آپ نے یہ آیت پڑھی : ’’بے شک اللہ تعالیٰ ہی کے پاس قیامت کا علم ہے ، وہی بارش برساتا ہے اور وہی جانتا ہے کہ ارحام ( ماؤں کے پیٹوں ) میں کیا ہےاور کوئی شخص نہیں جانتا کہ وہ آنے والے کل میں کیا کرے گا اور کوئی شخص نہیں جانتا کہ وہ ( کہاں ) کس زمین میں فوت ہو گا ...... ‘ ‘ سورت کے آخر تک ۔ حضرت ابو ہریرہ ‌رضی ‌اللہ ‌عنہ ‌ ‌ نے کہا : پھر وہ آدمی کھڑا ہو گیا ( اور چلا گیا ) تو رسول اللہ ﷺ نے فرمایا : ’’اسے میرے پاس واپس لاؤ ۔ ‘ ‘ اسے تلاش کیا گیا تو وہ انہیں ( صحابہ کرام کو ) نہ ملا ۔ رسو ل اللہ ﷺ نے فرمایا : ’’ یہ جبریل تھے ، انہوں نے چاہا کہ تم نہیں پوچھ رہے تو تم ( دین ) سیکھ لو ( انہوں نے آکر تمہاری طرف سے سوال کیا)","section":1,"grades":[]},{"id":100,"text":"مالک بن انس نے ابو سہیل سے ، اور انہوں نے اپنے والد سے روایت کی ، انہوں نے حضرت طلحہ بن عبیداللہ ‌رضی ‌اللہ ‌عنہ ‌ ‌ سےسنا ، وہ کہہ رہے تھے کہ رسول اللہ ﷺ کے پاس اہل نجد میں سے ایک آدمی آیا ، اس کے بال پراگندہ تھے ، ہم اس کی ہلکی سی آواز سن رہے تھے لیکن جوکچھ وہ کہہ رہا تھا ہم اس کو سمجھ نہیں رہے تھے حتی کہ وہ رسو ل اللہ ﷺ کے قریب آ گیا ، وہ آپ سے اسلام کے بارے میں پوچھ رہا تھا ، رسول اللہ ﷺ نے فرمایا : ’’دن اور رات میں پانچ نمازیں ( فرض ) ہیں ۔ ‘ ‘ اس نے پوچھا : کیا ان کے علاوہ ( اور نمازیں ) بھی میرے ذمے ہیں ؟ آپ نے فرمایا : ’’نہیں : الا یہ کہ تم نفلی نماز پڑھو اور ماہ رمضان کے روزے ہیں ۔ ‘ ‘ اس نے پوچھا : کیا میرے ذمے اس کے علاوہ بھی ( روزے ) ہیں ؟ فرمایا : ’’نہیں ، الا یہ کہ تم نفلی روزے رکھو ۔ ‘ ‘ پھر رسول اللہ ﷺ اسے زکاۃ کے بارے میں بتایا تو اس نے سوال کیا : کیا میرے ذمے اس کےسوا بھی کچھ ہے ؟ آپ نے جواب دیا : ’’نہیں ، سوائے اس کے کہ تم اپنی مرضی سے ( نفلی صدقہ ) دو ۔ ‘ ‘ ( حضرت طلحہ نے ) کہا : پھر وہ آدمی واپس ہوا تو کہہ رہا تھا : اللہ کی قسم ! میں نے اس پر کوئی اضافہ کروں گا نہ اس میں کوئی کمی کروں گا ۔ اس پر رسول اللہ ﷺ نے فرمایا : ’’یہ فلاح پا گیا اگر اس نے سچ کر دکھایا ۔ ‘ ‘","section":1,"grades":[]},{"id":101,"text":"اسماعیل بن جعفر نے ابو سہیل سے ، انہوں نے اپنے والد سے ، انہوں نےحضرت طلحہ بن عبید اللہ ‌رضی ‌اللہ ‌عنہ ‌ ‌ سے اور انہوں نے نبی ﷺ سے ، مالک سے حدیث کی طرح روایت کی ، سوائے اس کے کہ کہا : رسول اللہ ﷺ نے فرمایا : ’’کامیاب ہوا ، اس کے باپ کی قسم ! اگر اس نے سچ کر دکھایا ِ ‘ ‘ یا ( فرمایا : ) ’’جنت میں داخل ہو گا ، اس کے باپ کی قسم ! اگر اس نے سچ کر دکھایا ۔ ‘ ‘","section":1,"grades":[]},{"id":102,"text":"ہاشم بن قاسم ابونضر نے کہا : ہمیں سلیمان بن مغیرہ نے ثابت کے حوالے سے یہ حدیث سنائی ، انہوں نے حضرت انس بن مالک ‌رضی ‌اللہ ‌عنہ ‌ ‌ سے روایت کی کہ ہمیں رسول اللہ ﷺ سے ( غیر ضروری طور پر ) کسی چیز کے بارے میں سوال کرنے سے روک دیا گیا تو ہمیں بہت اچھا لگتا تھا کہ کوئی سمجھ دار بادیہ نشیں آپ کی خدمت میں حاضر ہوا اور آپ سے سوال کرے اور ہم ( بھی جواب ) سنیں ، چنانچہ ایک بدوی آیا اور کہنے لگا ، اے محمد ( ﷺ ) ! آپ کا قاصد ہمارے پاس آیا تھا ، اس نے ہم سے کہا کہ آپ نے فرماتے ہیں : اللہ تعالیٰ نے آپ کو رسول بنا کر بھیجا ہے ۔ آپ نے فرمایا : ’’ اس نے سچ کہا ۔ ‘ ‘ اس نے پوچھا : آسمان کس نے بنایا ہے ؟ آپ نے جواب دیا : ’’ اللہ نے ۔ ‘ ‘ اس نےکہا : زمین کس نےبنائی ؟ آپ نے فرمایا : ’’اللہ نے ۔ ‘ ‘ اس نے سوال کیا : یہ پہاڑ کس نے گاڑے ہیں اور ان میں جو کچھ رکھا ہے کس نے رکھا ہے ؟ آپ نے فرمایا : ’’ اللہ نے ۔ ‘ ‘ بدوی نے کہا : اس ذات کی قسم ہے جس نے آسمان بنایا ، زمین بنائی اور یہ پہاڑ نصب کیے ! کیا اللہ ہی نے آپ کو ( رسول بنا کر ) بھیجا ہے ؟ آپ نے جواب دیا : ’’ ہاں! ‘ ‘ اس نے کہا : آپ کے قاصد نے بتایا ہے کہ ہمارے دن او رات میں پانچ نمازیں ہیں ۔ آپ نے فرمایا : ’’اس نے درست کہا ۔ ‘ ‘ اس نے کہا : اس ذات کی قسم جس نے آپ کو بھیجا ہے ! کیا اللہ ہی نے آپ کو اس کاحکم دیا ہے ؟ آپ نے جواب دیا : ’’ہاں ! ‘ ‘ اس نے کہا : آپ کو ایلچی کا خیال ہے کہ ہمارے ذمے ہمارے مالوں کی زکاۃ ہے ۔ آپ نے فرمایا : ’’ اس نے سچ کہا ۔ ‘ ‘ بدوی نے کہا : ا س ذات کی قسم جس نے آپ کو رسول بنا یا ! کیا اللہ ہی نے آپ کو یہ حکم دیا ہے ؟ آپ نے جواب دیا : ’’ہاں ! ‘ ‘ اعرابی نے کہا : آپ کو ایلچی کا خیال ہے کہ ہمارے سال میں ہمارے ذمے ماہ رمضان کے روزے ہیں ۔ آپ نے فرمایا : ’’ اس نے صحیح کہا ۔ ‘ ‘ اس نے کہا : اس ذات کی قسم جس نے آپ کو بھیجا ہے ! کیا للہ ہی نے آپ کو اس کاحکم دیا ہے ؟ آپ نے فرمایا : ’’ہاں ! ‘ ‘ وہ کہنے لگا : آپ کے بھیجے ہوئے ( قاصد ) کا خیال ہے کہ ہم پر بیت اللہ کا حج فرض ہے ، اس شخص پر جو اس کے راستے ( کو طے کرنے ) کی استطاعت رکھتا ہو ۔ آپ نے فرمایا ، ’’ اس نے سچ کہا ۔ ‘ ‘ ( حضرت انس ‌رضی ‌اللہ ‌عنہ ‌ ‌ نے کہا : ) پھر وہ واپس چل پڑا اور ( چلتے چلتے ) کہا : اس ذات کی قسم جس نے آپ کو حق کے ساتھ بھیجا ہے! میں ان پر کوئی اضافہ کروں گا نہ ان میں کوئی کمی کروں گا ۔ اس پر نبی کریم ﷺ نے فرمایا : ’’اگر اس نے سچ کر دکھایا تو یقیناً جنت میں داخل ہو گا ۔ ‘ ‘","section":1,"grades":[]},{"id":103,"text":"بہزنے کہا : ہمیں سلیمان بن مغیرہ نے ثابت سے حدیث سنائی اور انہوں نے حضرت انس ‌رضی ‌اللہ ‌عنہ ‌ ‌ سے روایت کی ، انہون نےکہا : ہمیں قرآن مجید میں اس بات سے منع کر دیا گیا کہ ( بلاضرورت ) کسی چیز کے بارے میں آپ سے سوال کریں .... اس کے بعد ( بہزنے ) اسی کی مانند حدیث بیان کی ۔","section":1,"grades":[]},{"id":104,"text":"عمر و بن عثمان نے کہا : ہمیں موسیٰ بن طلحہ نےحدیث سنائی ، انہوں نےکہا : مجھےحضرت ابوایوب ‌رضی ‌اللہ ‌عنہ ‌ ‌ نےحدیث سنائی کہ رسول ا للہ ﷺ ایک سفر میں تھے جب ایک اعرابی ( دیہاتی ) آپ کے سامنے آ کھڑا ہوا ، اس نے آپ کی اونٹنی کی مہار یانکیل پکڑ لی ، پھر کہا : اے اللہ کے رسول ! ( یا اے محمد! ) مجھے وہ بات بتائیے جو مجھے جنت کے قریب اور آگ سے دور کر دے ۔ ابو ایوب نے کہا کہ رسول اللہ ﷺ رک گئے ، پھر اپنے ساتھیوں پر نظر دوڑائی ، پھر فرمایا ، ’’اس کو توفیق ملی ) ( یا ہدایت ملی ) ‘ ‘ پھر بدوی نے پوچھا : ’’تم نے کیا بات کی ؟ ‘ ‘ اس نے اپنی بات دہرائی تو نبی ا کرمﷺ نے فرمایا : ’’تم اللہ تعالیٰ کی بندگی کرو ، اس کے ساتھ کسی کو شریک نہ ٹھہراؤ ، نماز قائم کرو ، زکاۃ ادا کرو اورصلہ رحمی کرو ۔ ( اب ) اونٹنی کو چھوڑ دو ۔ ‘ ‘","section":1,"grades":[]},{"id":105,"text":"محمد بن عثمان بن عبد اللہ بن موہب اور ان کے والد عثمان دونوں موسیٰ بن طلحہ سے سنا وہ حضرت ابو ایوب ‌رضی ‌اللہ ‌عنہ ‌ ‌ سے اور وہ نبی کریم ﷺ سے سابقہ حدیث کی مانند بیان کرتے تھے ۔","section":1,"grades":[]},{"id":106,"text":"یحییٰ بن یحییٰ تمیمی او رابوبکر بن ابی شیبہ نے کہا : ہمیں ابو احوص نے حدیث بیان کی ، انہوں نے ابو اسحاق سے ، انہوں نے موسیٰ بن طلحہ سے او رانہوں حضرت ابو ایوب ‌رضی ‌اللہ ‌عنہ ‌ ‌ سے روایت کی ، انہوں نے کہا : ایک آدمی نبی ﷺ کےپاس آیا اور پوچھا : مجھے کوئی ایسا کام بتائیے جس پر میں عمل کروں تو وہ مجھے جنت کے قریب اور آگ سے دور کر دے ۔ آپ نے فرمایا : ’’ یہ کہ تو اللہ کی بندگی کرے اس کے ساتھ کسی کو شریک نہ ٹھہرائے ، نماز کی پابندی کرے ، زکاۃ ادا کرے اور اپنے رشتہ داروں سے صلہ رحمی کرے ۔ ‘ ‘ جب وہ پیٹھ پھیر کر چل دیا تو رسول اللہ ﷺ نے فرمایا : ’’ اگر اس نے ان چیزوں کی پابندی کی جن کا اسے حکم دیا گیا ہے تو جنت میں داخل ہو گا ۔ ‘ ‘ ابن ابی شیبہ کی روایت میں ہے ، ’’اگر اس نے اس کی پابندی کی ( تو جنت میں داخل ہو گا ۔ ) ‘ ‘","section":1,"grades":[]},{"id":107,"text":"حضرت ابو ہریرہ ‌رضی ‌اللہ ‌عنہ ‌ ‌ سے روایت ہے کہ ایک اعرابی رسول اللہ ﷺ کے پاس آیا اور کہا : اے اللہ کے رسول ! مجھے ایسا عمل بتائیے کہ جب میں اس پر عمل کروں تو جنت میں داخل ہو جاؤں ۔ آپ نے فرمایا : ’’تم اللہ کی بندگی کرو اس کے ساتھ کسی کو شریک نہ ٹھہراؤ ، نماز قائم کرو جو تم پر لکھ دی گئی ہے ، فرض زکاۃ ادا کرو او ررمضان کے روزے رکھو ۔ ‘ ‘ وہ کہنے لکا : اس ذات کی قسم جس کے ہاتھ میں میری جان ہے ! میں نہ کبھی اس پر کسی چیز کا اضافہ کروں گا اور نہ اس میں گمی کروں گا ۔ جب وہ واپس جانے لگا تو نبی اکریم ﷺ نے فرمایا : ’’جسے اس بات سے خوشی ہو کہ وہ ایک جنتی آدمی دیکھے تو وہ اسے دیکھ لے ۔ ‘ ‘","section":1,"grades":[]},{"id":108,"text":"ابومعاویہ نے اعمش سے حدیث سنائی ، انہوں نے ابو سفیان سے اور انہوں نے حضرت جابر ‌رضی ‌اللہ ‌عنہ ‌ ‌ سے روایت کی کہ رسول اللہ ﷺ کے پاس نعمان بن قوقل ‌رضی ‌اللہ ‌عنہ ‌ ‌ آئے اور کہا : اے اللہ کے رسول ! آپ کیا فرماتے ہیں کہ جب میں فرض نماز ادا کروں ، حرام کو حرام اور حلال کو حلال سمجھوں تو کیا میں جنت میں داخل ہو جاؤں گا ؟ نبی ﷺ نے فرمایا : ’’ہاں! ‘ ‘","section":1,"grades":[]},{"id":109,"text":"شیبان نے اعمش سے ، انہوں نے ابو صالح اور ابو سفیان سے اور انہوں نے حضرت جابر ‌رضی ‌اللہ ‌عنہ ‌ ‌ سے روایت کی ، انہوں نے کہا : نعمان بن قوقل ‌رضی ‌اللہ ‌عنہ ‌ ‌ نے عرض کی : اے اللہ کےرسول !..... پھر اس سابقہ روایت کی طرح ہے اور اس میں یہ اضافہ کیا : اور اس پر کسی چیز کا اضافہ نہ کروں گا ۔","section":1,"grades":[]},{"id":110,"text":"سلمہ بن شبیب ‘ حسن بن اعین ‘ معقل یعنی عبد اللہ ‘ ابوالزبیر ‘ جابر سے روایت ہے کہ ایک شخص نے رسول اللہﷺکی خدمت میں حاضر ہو کر عرض کیا کہ اگر میں فرض نماز پڑھتا رہوں اور ‌رمضان ‌كے ‌روزے ‌ركھوں ‌اور حلال کو حلال سمجھوں ‌اور ‌حرام ‌كو ‌حرام ‌، ‌اس ‌سے ‌زیادہ ‌كچھ ‌نہ ‌كروں تو آپﷺ کی کیا رائے ہے کہ کیا میں جنت میں داخل ہو جاؤ نگا؟تو آپﷺ نے فرمایا ہاں!اس شخص نے عرض کیا اللہ کی قسم میں اس سے زیادہ کچھ نہیں کرونگا ۔","section":1,"grades":[]},{"id":111,"text":"ابو خالد سلیمان بن حیان احمر نے ابومالک اشجعی سے ، انہوں نے سعد بن عبیدہ سے ، انہوں نے حضرت ابن عمر ‌رضی ‌اللہ ‌عنہ ‌ ‌ سے اور انہوں نے نبی اکرم ﷺ سے روایت کی ، آپ ﷺ نے فرمایا : ’’ اسلام کی بنیاد پانچ چیزوں پر رکھی گئی ہے : اللہ کو یکتا قرار دینے ، نمازقائم کرنے ، زکاۃ ادا کرنے ، رمضان کے روزے رکھنے اور حج کرنے پر ۔ ‘ ‘ ایک شخص نے کہ : حج کرنے اور رمضان کے روزے رکھنے پر ؟ ابن عمر ‌رضی ‌اللہ ‌عنہ ‌ ‌ نے کہا : نہیں ! رمضان کے روزے رکھنے اور حج کرنے پر ۔ میں نے رسول اللہ ﷺ سے یہ بات اسی طرح ( اسی ترتیب سے ) سنی تھی ۔","section":1,"grades":[]},{"id":112,"text":"یحییٰ بن زکریا نے ہمیں حدیث بیان کی ، کہا : مجھے سعد بن طارق ( ابو مالک اشجعی ) نے حدیث بیان کی ۔ وہ حضرت ابن عمر ‌رضی ‌اللہ ‌عنہ ‌ ‌ سے ، انہوں نے نبی ﷺ سے روایت کی کہ نبیﷺ نے فرمایا : ’’اسلام کی بنیاد پانچ چیزوں پر ہے : اس پر کہ اللہ کی عبادت کی جائے اور اس کے سوا ہر کسی کی عبادت سے انکار کیا جائے ، نماز قائم کرنے ، زکاۃ دینے ، بیت اللہ کاحج کرنے اور رمضان کے روزے رکھنے پر","section":1,"grades":[]},{"id":113,"text":"عاصم بن محمد بن زید عبد اللہ بن عمر نے اپنے والد سے حدیث بیان کی ، کہا : حضرت عبد اللہ بن عمر ‌رضی ‌اللہ ‌عنہ ‌ ‌ نے کہا کہ رسول اللہ ﷺ نے فرمایا : ’’اسلام کی بنیاد پانچ ( رکنوں ) پر رکھی گئی ہے : اس حقیقت کی ( دل ، زبان اور بعد میں ذکر کیے گئے بنیادی اعمال کے ذریعے سے ) گواہی دینا کہ اللہ تعالیٰ کےسوا کوئی معبود نہیں اور حضرت محمد ﷺ اس کے بندے اور اس کے رسول ہیں ، نماز قائم کرنا ، زکاۃ ادا کرنا ، بیت اللہ کا حج کرنا اور رمضان کے روزے رکھنا ۔ ‘ ‘","section":1,"grades":[]},{"id":114,"text":"عکرمہ بن خالد ، طاؤس کو حدیث سنا رہے تھے کہ ایک آدمی نے حضرت عبد اللہ بن عمر ‌رضی ‌اللہ ‌عنہ ‌ ‌ سے کہا : کیا آپ جہاد میں حصہ نہیں لیتے ؟ انہوں نےجواب دیا : بلاشبہ میں نے رسول اللہ ﷺ سے سنا ، آپ فرما رہے تھے ، ’’اسلام کی بنیاد پانچ چیزوں پر رکھی گئی ہے : ( اس حقیقت کی ) گواہی دینے پر کہ اللہ کے سوا کوئی معبود نہیں ، نماز قائم کرنے ، زکاۃ ادا کرنے ، رمضان کے روزے رکھنے اور بیت اللہ کاحج کرنے پر ۔ ‘ ‘","section":1,"grades":[]},{"id":115,"text":"خلف بن ہشام نے بیان کیا ( کہا ) ہمیں حماد بن زید نے ابو جمرہ سے حدیث بیان کی ، انہوں نے کہا : میں نے عبد اللہ بن عباس ‌رضی ‌اللہ ‌عنہ ‌ ‌ سے سنا ، نیز یحییٰ بن یحییٰ نے کہا : ( الفاظ انہی کے ہیں ) ہمیں عباد بن عباد نے ابو جمرہ سے خبر دی کہ حضرت ابن عباس ‌رضی ‌اللہ ‌عنہ ‌ ‌ نے کہا : رسول اللہﷺ کی خدمت میں عبدالقیس کا وفد آیا ۔ وہ ( لوگ ) کہنے لگے : اے اللہ کے رسول ! ہم لوگ ( یعنی ) بنو ربیعہ کا یہ قبیلہ ہے ۔ ہمارے اور آپ کے درمیان ( قبیلہ ) مضر کے کافر حائل ہیں اور ہم حرمت والے مہینے کے سوا بحفاظت آپ تک نہیں پہنچ سکتے ، لہٰذا آپ ہمیں وہ حکم دیجیے جس پر خود بھی عمل کریں اور جو پیچھے ہیں ان کو بھی اس کی دعوت دیں ۔ آپﷺ نے فرمایا : ’’ میں تمہیں چار چیزوں کا حکم دیتا ہوں اور چار چیزوں سے روکتا ہوں : ( جن کا حکم دیتا ہوں وہ ہیں : ) ’’اللہ تعالیٰ پر ایمان لانا ‘ ‘ پھر آپ نے ان کے سامنے ایمان باللہ کی وضاحت کی ، فرمایا : ’’ اس حقیقت کی گواہی دینا کہ اللہ تعالیٰ کے سوا کوئی عبادت کے لائق نہیں اور محمدﷺ بالیقین اللہ کے رسول ہیں ۔ نماز قائم کرنا ، زکاۃ ادا کرنا اور جومال غنیمت تمہیں حاصل ہو ، اس میں سے خمس ( پانچواں حصہ ) ادا کرنا ۔ اور میں تمہیں روکتا ہوں کدو کے برتن ، سبز گھڑے ، لکڑی کے اندر سے کھود کر ( بنائے ہوئے ) برتن اور ا یسے برتنوں کے استعمال سے جن پر تارکول ملا گیا ہو ۔ ‘ ‘ خلف نےاپنی روایت میں یہ اضافہ کیا : ’’ اس ( سچائی ) کی گواہی دینا کہ اللہ تعالیٰ کے سوا کوئی عبادت کے لائق نہیں ۔ ‘ ‘ اسے انہوں نےانگلی کے اشارے سے ایک شمار کیا ۔","section":1,"grades":[]},{"id":116,"text":"شعبہ نے ابو جمرہ سے حدیث بیان کی ، انہوں نے کہا : میں حضرت عبد اللہ بن عباس ‌رضی ‌اللہ ‌عنہ ‌ ‌ اور ( دوسرے ) لوگوں کے درمیان ترجمان تھا ، ان کے پاس ایک عورت آئی ، وہ ان سے گھڑے کی نبیذ کے بارے میں سوال کر رہی تھی توحضرت ابن عباس ‌رضی ‌اللہ ‌عنہ ‌ ‌ نے جواب دیا : رسول اللہ ﷺ کی خدمت میں عبد القیس کا وفد آیا ۔ رسول اللہ ﷺ نے پوچھا : ’’یہ کون سا وفد ہے ؟ ( یا فرمایا : یہ کو ن لوگ ہیں ؟ ) ‘ ‘ انہوں نے کہا : ربیعہ ( قبیلہ سے ہیں ۔ ) فرمایا : ’’ اس قوم ( یا وفد ) کو خوش آمدید جو رسوا ہوئے نہ نادم ۔ ‘ ‘ ( ابن عباس ‌رضی ‌اللہ ‌عنہ ‌ ‌ نے ) کہا ، ان لوگوں نے عرض کی : اے اللہ کےرسول ! ہم لوگ آپ کے پاس بہت دور سے آتے ہیں ، ہمارے اور آپ کے درمیان مضر کے کافروں کا یہ قبیلہ ( حائل ) ہے ، ہم ( کسی ) حرمت والے مہینے کے سوا آپ کے پاس نہیں آ سکتے ، آپ ہمیں فیصلہ کن بات بتائیے جو ہم اپنے ( گھروں میں ) پیچھے لوگوں کو ( بھی ) بتائیں اور اس کے ذریعے سے ہم جنت میں داخل ہو جائیں ۔ ابن عباس ‌رضی ‌اللہ ‌عنہ ‌ ‌ نے بتایا : آپ نے ان چار باتوں کا حکم دیا اور چار چیزیں سے روکا ۔ آپ نے ان کو اکیلے اللہ تعالیٰ پر ایمان لانا کا حکم دیا اور پوچھا : ’’جانتے ہو ، صرف اللہ پر ایمان لانا کیا ہے ؟ ‘ ‘ انہوں نے کہا : اللہ اور اس کے رسول ہی زیادہ جاننے والے ہیں ۔ آپ نے فرمایا : ’’اس حقیقت کی گواہی دینا کہ اللہ کے سوا کوئی الٰہ نہیں اور محمد ﷺ اللہ کے رسول ہیں ، نماز قائم کرنا ، زکاۃ دینا ، رمضان کے روزے رکھنا اور یہ کہ تم مال غنیمت میں سے اس کا پانچواں حصہ ادا کرو ۔ ‘ ‘ اور انہیں خشک کدو سے بنائے ہوئے برتن ، سبز مٹکے اور تارکول ملے ہوئے برتن ( استعمال کرنے ) سے منع کیا ( شعبہ نے کہا : ) ابو جمرہ نے شاید نقیر ( لکڑی میں کھدائی کر کے بنایا ہوا برتن کہا یا شاید مقیر ( تارکول ملا ہوا برتن ) کہا ۔ اور آپ نے فرمایا : ’’ان کو خوب یاد رکھو اور اپنے پیچھے ( والوں کو ) بتا دو ۔ ‘ ‘ ابو بکر بن ابی شیبہ کی روایت میں ( من ورائکم کے بجائے ) من وراءکم ( ان کو ( بتاؤ ) جو تمہارے پیچھے ہیں ) کے الفاظ ہیں اور ان کی روایت میں مقیر کا ذکر نہیں ( بلکہ نقیر کا ہے ۔)","section":1,"grades":[]},{"id":117,"text":"قرہ بن خالد نے ابوجمرہ سے حدیث بیان کی ، انہوں نے حضرت ابن عباس ‌رضی ‌اللہ ‌عنہ ‌ ‌ سے اور انہوں نے نبی ﷺ سے شعبہ کی ( سابقہ روایت کی ) طرح حدیث بیان کی ( اس کے الفاظ ہیں : ) رسو ل اللہ ﷺ نے فرمایا : ’’میں تمہیں اس نبیذ سے منع کرتا ہوں جو خشک کدو کے برتن ، لکڑی سے تراشیدہ برتن ، سبز مٹکے اور تارکول ملے برتن میں تیار کی جائے ( اس میں زیادہ خمیر اٹھنے کا خدشہ ہے جس سے نبیذ شراب میں بدل جاتی ہے ۔ ) ‘ ‘ ابن معاذ نے اپنے والد کی روایت میں اضافہ کیا ہے کہ رسول اللہ ﷺ نے عبد القیس کے پیشانی پر زخم والے شخص ( اشج ) سے کہا : ’’تم میں دو خوبیاں ہیں جنہیں اللہ پسند فرماتا ہے : عقل اور تحمل ۔ ‘ ‘","section":1,"grades":[]},{"id":118,"text":"(اسماعیل ) ابن علیہ نے کہا : ہمیں سعید بن ابی عروبہ نے قتادہ سے حدیث سنائی ، انہوں نےکہا : مجھے اس شخص نے بتایا جو رسو ل اللہ ﷺ کی خدمت میں حاضر ہونے والے عبد القیس کے وفد سے ملے تھا ( سعید نےکہا : قتادہ نے ابو نضرہ کا نام لیا تھا یہ وفد سے ملے تھے ، اور تفصیل حضرت ابو سعید سے سن کر بیان کی ) انہوں نےحضرت ابو سعید خدری ‌رضی ‌اللہ ‌عنہ ‌ ‌ سے یہ روایت کی کہ عبد القیس کے کچھ لوگ رسول اللہ ﷺ کے پاس آئے اور عرض کی : اے اللہ کے رسول ! ہم ربیعہ کے لوگ ہیں ، ہمارے اور آپ کے درمیان مضر کے کافر حائل ہیں اور ہم حرمت والے مہینوں کے علاوہ آپ کی خدمت میں نہیں پہنچ سکتے ، اس لیے آپ ہمیں وہ حکم دیجیے جو ہم اپنے پچھلوں کو بتائیں اور اگر اس پر عمل کر لیں تو ہم ( سب ) جنت میں داخل ہو جائیں ۔ رسول اللہ ﷺ نے فرمایا : ’’میں تمہیں چار چیزوں کا حکم دیتا ہوں اور چار چیزوں سے روکتا ہ و : ( حکم دیتا ہوں کہ ) اللہ تعالیٰ کی بندگی کرو اور اس کے ساتھ کسی چیز کو شریک نہ ٹھہراؤ ، نماز کی پابندی کرو ، زکاۃ دیتے رہو ، رمضان کے روزے رکھو اور غنیمتوں کا پانچواں حصہ ادا کرو ۔ اور چار چیزیں سے میں تمہیں روکتا ہوں : خشک کدو کے برتن سے ، سبز مٹکے سے ، ایسے برتن سے جس کو روغن زفت ( تارکول ) لگایا گیا ہو اور نقیر ( لکڑی کے تراشے ہوئے برتن ) سے ۔ ‘ ‘ ان لوگوں نے کہا : اے اللہ کے نبی ! آپ کو نقیر کے بارے میں کیا علم ہے ؟ فرمایا : ’’کیوں نہیں ! ( یہ ) تنا ہے ، تم اسے اندر سے کھوکھلا کرتے ہو ، اس میں ملی جلی چھوٹی کھجوریں ڈالتے ہو ) پھر اس میں پانی ڈالتے ہو ، پھر جب اس کا جوش ( خمیر اٹھنے کے بعد کا جھاگ ) ختم ہو جاتا ہے تواسے پی لیتے ہو یہاں تک کہ تم میں سے ایک ( یا ان میں ایک ) اپنے چچازاد کو تلوار کا نشانہ بناتا ہے ۔ ‘ ‘ ابو سعید نے کہا : لوگوں میں ایک آدمی تھا جس کو اسی طرح ایک زخم لگا تھا ۔ اس نے کہا : میں شرم و حیا کی بنا پر اسے رسول اللہ ﷺ سے چھپا رہا تھا ، پھر میں نے پوچھا : اے اللہ کے رسول ! تو ہم کس پیا کریں ؟ آپ نے فرمایا : ’’چمڑے کی ان مشکوں میں پیو جن کے منہ ( دھاگے وغیرہ سے ) باندھ دیے جاتے ہیں ۔ ‘ ‘ اہل وفد بولے : اے اللہ کے رسول ! ہماری زمین میں چوہے بہت ہیں ، وہاں چمڑے کے مشکیزے نہیں بچ پاتے ۔ اللہ کے نبی ﷺ نے فرمایا : ’’چاہے انہیں چوہے کھا جائیں ، چاہے انہیں چوہے کھا جائیں ، چاہے انہیں کھا جائیں ۔ ‘ ‘ کہا : ( پھر ) رسول اللہ ﷺ نے عبد القیس کے اس شخص سے جس کے چہرے پر زخم تھا ، فرمایا : ’’تمہارے اندر دو ایسی خوبیاں ہیں جنہیں اللہ تعالیٰ پسند فرماتا ہے : عقل اور تحمل ۔ ‘ ‘","section":1,"grades":[]},{"id":119,"text":"ابن ابی عدی نے سعید کےحوالے سے قتادہ سے روایت کی ، انہوں نے کہا کہ مجھے عبد القیس کے وفد سے ملاقات کرنےوالے ایک سے زائد افراد نے بتایا اور ان میں سے ابو نضرہ کانام لیا ( ابو نضرہ نے ) حضرت ابو سعیدخدری ‌رضی ‌اللہ ‌عنہ ‌ ‌ سے روایت کی کہ جب عبدالقیس کا وفد رسول اللہﷺ کی خدمت میں حاضر ہوا .... ، پھر ابن علیہ کی حدیث کے مانند روایت بیان کی ، البتہ اس میں یہ الفاظ ہیں : ’’تم اس میں ملی جلی کھجوریں ، ( عام ) کھجوریں اور پانی ڈالتے ہو ۔ ‘ ‘ ( اور ابن ابی عدی نے اپنی روایت میں ) یہ الفاظ ذکر نہیں کیے کہ سعید نے کہا ، یا آپﷺ نے فرمایا : ’’کچھ کھجوریں ڈالتے ہو ۔ ‘ ‘","section":1,"grades":[]}]}'),e=JSON.parse('{"name":"ابو داؤد","sections":{"1":"طہارت (کتاب الطہارۃ)"},"hadiths":[{"id":1,"text":"مغیرہ بن شعبہ رضی اللہ عنہ کہتے ہیں کہ نبی اکرم صلی اللہ علیہ وسلم جب قضائے حاجت ( یعنی پیشاب اور پاخانہ ) کے لیے جاتے تو دور تشریف لے جاتے تھے۔","section":1,"grades":[{"name":"Al-Albani","grade":"Hasan Sahih"},{"name":"Muhammad Muhyi Al-Din Abdul Hamid","grade":"Hasan Sahih"},{"name":"Shuaib Al Arnaut","grade":"Sahih Lighairihi"},{"name":"Zubair Ali Zai","grade":"Isnaad Hasan"}]},{"id":2,"text":"جابر بن عبداللہ رضی اللہ عنہما کہتے ہیں کہ نبی اکرم صلی اللہ علیہ وسلم جب قضائے حاجت ( پیشاب و پاخانہ ) کا ارادہ کرتے تو ( اتنی دور ) جاتے کہ کوئی آپ صلی اللہ علیہ وسلم کو دیکھ نہ پاتا تھا۔","section":1,"grades":[{"name":"Al-Albani","grade":"Sahih"},{"name":"Muhammad Muhyi Al-Din Abdul Hamid","grade":"Sahih"},{"name":"Shuaib Al Arnaut","grade":"Sahih Lighairihi"},{"name":"Zubair Ali Zai","grade":"Daif"}]},{"id":3,"text":"ابوالتیاح کہتے ہیں کہ مجھے ایک شیخ نے بتایا کہ سیدنا عبداللہ بن عباس رضی اللہ عنہا جب بصرہ میں ( بحثیت گورنر ) تشریف لائے تو لوگ انہیں سیدنا ابوموسیٰ اشعری رضی اللہ عنہ سے سنی ہوئی احادیث بیان کرتے تھے ۔ ( تو اس ضمن میں ) سیدنا عبداللہ بن عباس رضی اللہ عنہا نے سیدنا ابوموسیٰ رضی اللہ عنہ کے نام ایک خط لکھا : جس میں ان سے کچھ مسائل دریافت کیے چنانچہ سیدنا ابوموسیٰ رضی اللہ عنہ نے انہیں جواب میں لکھا : میں ایک دن رسول اللہ صلی اللہ علیہ وسلم کی معیت میں تھا تو آپ صلی اللہ علیہ وسلم نے پیشاب کرنے کا ارادہ کیا ، پس آپ صلی اللہ علیہ وسلم ایک دیوار کی جڑ میں نرم مٹی کے پاس آئے اور پیشاب کیا ۔ اس کے بعد آپ صلی اللہ علیہ وسلم نے فرمایا ” تم میں سے جب کوئی پیشاب کرنا چاہے تو اس کے لیے ( مناسب نرم ) جگہ تلاش کر لیا کرے ۔ “","section":1,"grades":[{"name":"Al-Albani","grade":"Daif"},{"name":"Muhammad Muhyi Al-Din Abdul Hamid","grade":"Daif"},{"name":"Shuaib Al Arnaut","grade":"Daif"},{"name":"Zubair Ali Zai","grade":"Daif"}]},{"id":4,"text":"انس بن مالک رضی اللہ عنہ کہتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم جب پاخانہ جاتے ( حماد کی روایت میں ہے ) تو آپ صلی اللہ علیہ وسلم «اللهم إني أعوذ بك من الخبث والخبائث» اے اللہ! میں تیری پناہ چاہتا ہوں کہتے، اور عبدالوارث کی روایت میں ہے کہ آپ صلی اللہ علیہ وسلم «أعوذ بالله من الخبث والخبائث» میں ناپاک جن مردوں اور ناپاک جن عورتوں ( کے شر ) سے اللہ کی پناہ چاہتا ہوں کہتے۔","section":1,"grades":[{"name":"Al-Albani","grade":"Sahih"},{"name":"Muhammad Muhyi Al-Din Abdul Hamid","grade":"Sahih"},{"name":"Shuaib Al Arnaut","grade":"Sahih"},{"name":"Zubair Ali Zai","grade":"Sahih Bukhari (142) Sahih Muslim (375)"}]},{"id":5,"text":"انس بن مالک رضی اللہ عنہ سے یہی حدیث مروی ہے اس میں «اللهم إني أعوذ بك» ہے، یعنی اے اللہ میں تیری پناہ چاہتا ہوں ۔ شعبہ کا بیان ہے کہ عبدالعزیز نے ایک بار «أعوذ بالله» میں اللہ کی پناہ چاہتا ہوں کی بھی روایت کی ہے، اور وہیب نے عبدالعزیز بن صہیب سے جو روایت کی ہے اس میں «فليتعوذ بالله» چاہیئے کہ اللہ سے پناہ مانگے کے الفاظ ہیں۔","section":1,"grades":[{"name":"Al-Albani","grade":"Shadh"},{"name":"Muhammad Muhyi Al-Din Abdul Hamid","grade":"Shadh"},{"name":"Zubair Ali Zai","grade":"Isnaad Sahih"}]},{"id":6,"text":"زید بن ارقم رضی اللہ عنہ سے روایت ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا قضائے حاجت ( پیشاب و پاخانہ ) کی یہ جگہیں جن اور شیطان کے موجود رہنے کی جگہیں ہیں، جب تم میں سے کوئی شخص بیت الخلاء میں جائے تو یہ دعا پڑھے «أعوذ بالله من الخبث والخبائث» میں اللہ کی پناہ چاہتا ہوں ناپاک جن مردوں اور ناپاک جن عورتوں سے ۔","section":1,"grades":[{"name":"Al-Albani","grade":"Sahih"},{"name":"Muhammad Muhyi Al-Din Abdul Hamid","grade":"Sahih"},{"name":"Zubair Ali Zai","grade":"Isnaad Sahih"}]},{"id":7,"text":"سلمان رضی اللہ عنہ کہتے ہیں کہ ان سے ( بطور استہزاء ) یہ کہا گیا کہ تمہارے نبی نے تو تمہیں سب چیزیں سکھا دی ہیں حتیٰ کہ پاخانہ کرنا بھی، تو انہوں نے ( فخریہ انداز میں ) کہا: ہاں، بیشک ہمارے نبی صلی اللہ علیہ وسلم نے ہم کو پاخانہ اور پیشاب کے وقت قبلہ رخ ہونے، داہنے ہاتھ سے استنجاء کرنے، استنجاء میں تین سے کم پتھر استعمال کرنے اور گوبر اور ہڈی سے استنجاء کرنے سے منع فرمایا ہے۔","section":1,"grades":[{"name":"Al-Albani","grade":"Sahih"},{"name":"Muhammad Muhyi Al-Din Abdul Hamid","grade":"Sahih"},{"name":"Shuaib Al Arnaut","grade":"Sahih"},{"name":"Zubair Ali Zai","grade":"Sahih Muslim (262)"}]},{"id":8,"text":"ابوہریرہ رضی اللہ عنہ کہتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا ( لوگو! ) میں تمہارے لیے والد کے درجے میں ہوں، تم کو ( ہر چیز ) سکھاتا ہوں، تو جب تم میں سے کوئی شخص قضائے حاجت ( پیشاب و پاخانہ ) کے لیے جائے تو قبلہ کی طرف منہ اور پیٹھ کر کے نہ بیٹھے، اور نہ ( ہی ) داہنے ہاتھ سے استنجاء کرے آپ صلی اللہ علیہ وسلم ( استنجاء کے لیے ) تین پتھر لینے کا حکم فرماتے، اور گوبر اور ہڈی کے استعمال سے روکتے تھے۔","section":1,"grades":[{"name":"Al-Albani","grade":"Hasan"},{"name":"Muhammad Muhyi Al-Din Abdul Hamid","grade":"Hasan"},{"name":"Zubair Ali Zai","grade":"Isnaad Hasan"}]},{"id":9,"text":"ابوایوب انصاری رضی اللہ عنہ سے روایت ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا جب تم قضائے حاجت کے لیے آؤ تو پاخانہ اور پیشاب کرتے وقت قبلہ رو ہو کر نہ بیٹھو، بلکہ پورب یا پچھم کی طرف رخ کر لیا کرو ۱؎، ( ابوایوب رضی اللہ عنہ کہتے ہیں ) پھر ہم ملک شام آئے تو وہاں ہمیں بیت الخلاء قبلہ رخ بنے ہوئے ملے، تو ہم پاخانہ و پیشاب کرتے وقت قبلہ کی طرف سے رخ پھیر لیتے تھے، اور اللہ سے مغفرت طلب کرتے تھے۔","section":1,"grades":[{"name":"Al-Albani","grade":"Sahih"},{"name":"Muhammad Muhyi Al-Din Abdul Hamid","grade":"Sahih"},{"name":"Shuaib Al Arnaut","grade":"Sahih"},{"name":"Zubair Ali Zai","grade":"Sahih Bukhari (394) Sahih Muslim (264)"}]},{"id":10,"text":"معقل بن ابی معقل اسدی رضی اللہ عنہ کہتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے پیشاب اور پاخانہ کے وقت دونوں قبلوں ( بیت اللہ اور بیت المقدس ) کی طرف منہ کرنے سے منع فرمایا ہے۔ ابوداؤد کہتے ہیں: ابوزید بنی ثعلبہ کے غلام ہیں۔","section":1,"grades":[{"name":"Al-Albani","grade":"Daif"},{"name":"Muhammad Muhyi Al-Din Abdul Hamid","grade":"Munkar"},{"name":"Shuaib Al Arnaut","grade":"Daif"},{"name":"Zubair Ali Zai","grade":"Daif"}]},{"id":11,"text":"مروان اصفر کہتے ہیں میں نے عبداللہ بن عمر رضی اللہ عنہما کو دیکھا، انہوں نے قبلہ کی طرف اپنی سواری بٹھائی پھر بیٹھ کر اسی کی طرف رخ کر کے پیشاب کرنے لگے، میں نے پوچھا: ابوعبدالرحمٰن! ( عبداللہ بن عمر رضی اللہ عنہما کی کنیت ہے ) کیا اس سے منع نہیں کیا گیا ہے؟ تو انہوں نے جواب دیا: کیوں نہیں، اس سے صرف میدان میں روکا گیا ہے لیکن جب تمہارے اور قبلہ کے بیچ میں کوئی ایسی چیز ہو جو تمہارے لیے آڑ ہو تو کوئی حرج نہیں ۱؎۔","section":1,"grades":[{"name":"Al-Albani","grade":"Hasan"},{"name":"Muhammad Muhyi Al-Din Abdul Hamid","grade":"Hasan"},{"name":"Zubair Ali Zai","grade":"Daif"}]},{"id":12,"text":"عبداللہ بن عمر رضی اللہ عنہما کہتے ہیں کہ ( ایک روز ) میں ( کسی ضرورت سے ) گھر کی چھت پر چڑھا تو میں نے رسول اللہ صلی اللہ علیہ وسلم کو قضائے حاجت ( پیشاب و پاخانہ ) کے لیے دو اینٹوں پر اس طرح بیٹھے دیکھا کہ آپ صلی اللہ علیہ وسلم کا رخ بیت المقدس کی طرف تھا ۱؎۔","section":1,"grades":[{"name":"Al-Albani","grade":"Sahih"},{"name":"Muhammad Muhyi Al-Din Abdul Hamid","grade":"Sahih"},{"name":"Shuaib Al Arnaut","grade":"Sahih"},{"name":"Zubair Ali Zai","grade":"Sahih Bukhari (145) Sahih Muslim (266)"}]},{"id":13,"text":"جابر بن عبداللہ رضی اللہ عنہما کہتے ہیں کہ نبی اکرم صلی اللہ علیہ وسلم نے ہمیں پیشاب کے وقت قبلہ کی طرف رخ کرنے سے منع فرمایا، ( لیکن ) میں نے وفات سے ایک سال پہلے آپ صلی اللہ علیہ وسلم کو ( قضائے حاجت کی حالت میں ) قبلہ رو دیکھا ۱؎۔","section":1,"grades":[{"name":"Al-Albani","grade":"Hasan"},{"name":"Muhammad Muhyi Al-Din Abdul Hamid","grade":"Hasan"},{"name":"Shuaib Al Arnaut","grade":"Hasan"},{"name":"Zubair Ali Zai","grade":"Isnaad Hasan"}]},{"id":14,"text":"عبداللہ بن عمر رضی اللہ عنہما کہتے ہیں کہ نبی اکرم صلی اللہ علیہ وسلم جب قضائے حاجت ( پیشاب و پاخانہ ) کا ارادہ فرماتے تو اپنا کپڑا ( شرمگاہ سے اس وقت تک ) نہ اٹھاتے جب تک کہ زمین سے قریب نہ ہو جاتے تھے۔ ابوداؤد کہتے ہیں: اسے عبدالسلام بن حرب نے اعمش سے، انہوں نے انس بن مالک رضی اللہ عنہ سے روایت کی ہے، مگر یہ ضعیف ہے ۱؎۔","section":1,"grades":[{"name":"Al-Albani","grade":"Sahih"},{"name":"Muhammad Muhyi Al-Din Abdul Hamid","grade":"Sahih"},{"name":"Shuaib Al Arnaut","grade":"Daif"},{"name":"Zubair Ali Zai","grade":"Daif"}]},{"id":15,"text":"ابوسعید رضی اللہ عنہ کہتے ہیں کہ میں نے رسول اللہ صلی اللہ علیہ وسلم کو یہ فرماتے سنا دو آدمی قضائے حاجت ( پیشاب و پاخانہ ) کے وقت شرمگاہ کھولے ہوئے آپس میں باتیں نہ کریں کیونکہ اس سے اللہ تعالیٰ ناراض ہوتا ہے ۔ ابوداؤد کہتے ہیں: اس حدیث کو عکرمہ بن عمار کے علاوہ کسی اور نے مسنداً ( مرفوعاً ) روایت نہیں کیا ہے۔","section":1,"grades":[{"name":"Al-Albani","grade":"Daif"},{"name":"Muhammad Muhyi Al-Din Abdul Hamid","grade":"Daif"},{"name":"Shuaib Al Arnaut","grade":"Daif"},{"name":"Zubair Ali Zai","grade":"Daif"}]},{"id":16,"text":"عبداللہ بن عمر رضی اللہ عنہما کہتے ہیں کہ نبی اکرم صلی اللہ علیہ وسلم ( ایک دن ) پیشاب کر رہے تھے ( کہ اسی حالت میں ) ایک شخص آپ کے پاس سے گزرا اور اس نے آپ کو سلام کیا، تو آپ صلی اللہ علیہ وسلم نے اس کے سلام کا جواب نہیں دیا۔ ابوداؤد کہتے ہیں: ابن عمر وغیرہ سے مروی ہے کہ نبی اکرم صلی اللہ علیہ وسلم نے تیمم کیا، پھر اس آدمی کے سلام کا جواب دیا۔","section":1,"grades":[{"name":"Al-Albani","grade":"Hasan"},{"name":"Muhammad Muhyi Al-Din Abdul Hamid","grade":"Hasan"},{"name":"Shuaib Al Arnaut","grade":"Sahih"},{"name":"Zubair Ali Zai","grade":"Sahih Muslim (370)"}]},{"id":17,"text":"مہاجر بن قنفذ رضی اللہ عنہ کہتے ہیں کہ وہ نبی اکرم صلی اللہ علیہ وسلم کے پاس آئے، آپ صلی اللہ علیہ وسلم پیشاب کر رہے تھے تو انہوں نے آپ کو سلام کیا، آپ صلی اللہ علیہ وسلم نے سلام کا جواب نہیں دیا، یہاں تک کہ وضو کیا پھر ( سلام کا جواب دیا اور ) مجھ سے معذرت کی اور فرمایا مجھے یہ بات اچھی نہیں لگی کہ میں اللہ کا ذکر بغیر پاکی کے کروں ۔ راوی کو شک ہے «على طهر» کہا، یا «على طهارة» کہا۔","section":1,"grades":[{"name":"Al-Albani","grade":"Sahih"},{"name":"Muhammad Muhyi Al-Din Abdul Hamid","grade":"Sahih"},{"name":"Zubair Ali Zai","grade":"Daif"}]},{"id":18,"text":"ام المؤمنین عائشہ رضی اللہ عنہا کہتی ہیں کہ رسول اللہ صلی اللہ علیہ وسلم اللہ عزوجل کا ذکر ہر وقت کیا کرتے تھے۔","section":1,"grades":[{"name":"Al-Albani","grade":"Sahih"},{"name":"Muhammad Muhyi Al-Din Abdul Hamid","grade":"Sahih"},{"name":"Zubair Ali Zai","grade":"Sahih Muslim (373)"}]},{"id":19,"text":"انس رضی اللہ عنہ کہتے ہیں کہ کہ نبی اکرم صلی اللہ علیہ وسلم جب پاخانہ میں داخل ہوتے تو اپنی انگوٹھی نکال کر رکھ دیتے تھے۔ ابوداؤد کہتے ہیں کہ یہ حدیث منکر ہے، معروف وہ روایت ہے جسے ابن جریج نے زیاد بن سعد سے، زیاد نے زہری سے اور زہری نے انس رضی اللہ عنہ سے روایت کیا ہے کہ نبی اکرم صلی اللہ علیہ وسلم نے چاندی کی ایک انگوٹھی بنوائی ( اسے پہنا ) پھر اسے نکال کر پھینک دیا۔ اس حدیث میں ہمام راوی سے وہم ہوا ہے، اسے صرف ہمام ہی نے روایت کیا ہے۔","section":1,"grades":[{"name":"Al-Albani","grade":"Daif"},{"name":"Muhammad Muhyi Al-Din Abdul Hamid","grade":"Munkar"},{"name":"Zubair Ali Zai","grade":"Daif"}]},{"id":20,"text":"عبداللہ بن عباس رضی اللہ عنہما کہتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم کا گزر دو قبروں پر ہوا، آپ صلی اللہ علیہ وسلم نے فرمایا ( قبر میں مدفون ) ان دونوں کو عذاب دیا جا رہا ہے اور کسی بڑے گناہ کی وجہ سے نہیں، ان میں سے یہ شخص تو پیشاب سے پاکی حاصل نہیں کرتا تھا، اور رہا یہ تو یہ چغل خوری میں لگا رہتا تھا پھر آپ صلی اللہ علیہ وسلم نے کھجور کی ایک تازہ ٹہنی منگوائی، اور اسے بیچ سے پھاڑ کر دونوں قبروں پر ایک ایک شاخ گاڑ دی پھر فرمایا جب تک یہ ٹہنیاں خشک نہ ہوں شاید ان کا عذاب کم رہے ۔ ھناد نے «يستنزه» کی جگہ «يستتر» ( پردہ نہیں کرتا تھا ) ذکر کیا ہے۔","section":1,"grades":[{"name":"Al-Albani","grade":"Sahih"},{"name":"Muhammad Muhyi Al-Din Abdul Hamid","grade":"Sahih"},{"name":"Shuaib Al Arnaut","grade":"Sahih"},{"name":"Zubair Ali Zai","grade":"Sahih Bukhari (6052) Sahih Muslim (292)"}]},{"id":21,"text":"عبداللہ بن عباس رضی اللہ عنہما نے نبی اکرم اکرم صلی اللہ علیہ وسلم سے اسی مفہوم کی حدیث روایت کی ہے اس میں جریر نے «كان لا يستتر من بوله» کہا ہے، اور ابومعاویہ نے «يستتر» کی جگہ «يستنزه» وہ پاکی حاصل نہیں کرتا تھا کا لفظ ذکر کیا ہے۔","section":1,"grades":[{"name":"Al-Albani","grade":"Sahih"},{"name":"Muhammad Muhyi Al-Din Abdul Hamid","grade":"Sahih"},{"name":"Shuaib Al Arnaut","grade":"Sahih"},{"name":"Zubair Ali Zai","grade":"Sahih Bukhari (216)"}]},{"id":22,"text":"عبدالرحمٰن بن حسنہ کہتے ہیں: : میں اور عمرو بن العاص رضی اللہ عنہما دونوں نبی اکرم صلی اللہ علیہ وسلم کی طرف چلے تو ( دیکھا کہ ) آپ صلی اللہ علیہ وسلم ( باہر ) نکلے اور آپ کے ساتھ ایک ڈھال ہے، اس سے آپ صلی اللہ علیہ وسلم نے آڑ کی پھر پیشاب کیا، ہم نے کہا: آپ کو دیکھو عورتوں کی طرح ( چھپ کر ) پیشاب کر رہے ہیں، یہ سن کر آپ صلی اللہ علیہ وسلم نے فرمایا: کیا تمہیں اس چیز کا علم نہیں جس سے بنی اسرائیل کا ایک شخص دوچار ہوا؟ ان میں سے جب کسی شخص کو ( اس کے جسم کے کسی حصہ میں ) پیشاب لگ جاتا تو وہ اس جگہ کو کاٹ ڈالتا جہاں پیشاب لگ جاتا، اس شخص نے انہیں اس سے روکا تو اسے اس کی قبر میں عذاب دیا گیا ۔ ابوداؤد کہتے ہیں: منصور نے ابووائل سے، انہوں نے ابوموسیٰ رضی اللہ عنہ سے، ابوموسیٰ نے نبی اکرم صلی اللہ علیہ وسلم سے اس حدیث میں پیشاب لگ جانے پر اپنی کھال کاٹ ڈالنے کی روایت کی ہے، اور عاصم نے ابووائل سے، انہوں نے ابوموسیٰ سے، اور ابوموسیٰ نے نبی اکرم صلی اللہ علیہ وسلم سے اپنا جسم کاٹ ڈالنے کا ذکر کیا ہے۔","section":1,"grades":[{"name":"Al-Albani","grade":"Sahih Muquf"},{"name":"Muhammad Muhyi Al-Din Abdul Hamid","grade":"Sahih"},{"name":"Shuaib Al Arnaut","grade":"Sahih"},{"name":"Zubair Ali Zai","grade":"Daif"}]},{"id":23,"text":"حذیفہ رضی اللہ عنہ کہتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم ایک قوم کے کوڑے خانہ ( گھور ) پر آئے اور کھڑے ہو کر پیشاب کیا ۱؎ پھر پانی منگوایا ( اور وضو کیا ) اور اپنے دونوں موزوں پر مسح کیا۔ ابوداؤد کہتے ہیں: مسدد کا بیان ہے کہ حذیفہ رضی اللہ عنہ نے کہا: میں پیچھے ہٹنے چلا تو آپ صلی اللہ علیہ وسلم نے مجھے ( قریب ) بلایا ( میں آیا ) یہاں تک کہ میں آپ صلی اللہ علیہ وسلم کی ایڑیوں کے پاس ( کھڑا ) تھا۔","section":1,"grades":[{"name":"Al-Albani","grade":"Sahih"},{"name":"Muhammad Muhyi Al-Din Abdul Hamid","grade":"Sahih"},{"name":"Shuaib Al Arnaut","grade":"Sahih"},{"name":"Zubair Ali Zai","grade":"Sahih Bukhari (224) Sahih Muslim (273)"}]},{"id":24,"text":"امیمہ بنت رقیقہ رضی اللہ عنہا کہتی ہیں کہ کہ نبی اکرم صلی اللہ علیہ وسلم کے لیے آپ کے تخت کے نیچے لکڑی کا ایک پیالہ ( رہتا ) تھا، جس میں آپ صلی اللہ علیہ وسلم رات کو پیشاب کرتے تھے۔","section":1,"grades":[{"name":"Al-Albani","grade":"Hasan Sahih"},{"name":"Muhammad Muhyi Al-Din Abdul Hamid","grade":"Hasan Sahih"},{"name":"Zubair Ali Zai","grade":"Isnaad Hasan"}]},{"id":25,"text":"ابوہریرہ رضی اللہ عنہ کہتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: تم لعنت کے دو کاموں سے بچو ، لوگوں نے پوچھا: اللہ کے رسول! لعنت کے وہ دو کام کیا ہیں؟ آپ صلی اللہ علیہ وسلم نے فرمایا: وہ یہ ہیں کہ آدمی لوگوں کے راستے یا ان کے سائے کی جگہ میں پاخانہ کرے ۱؎ ۔","section":1,"grades":[{"name":"Al-Albani","grade":"Sahih"},{"name":"Muhammad Muhyi Al-Din Abdul Hamid","grade":"Sahih"},{"name":"Shuaib Al Arnaut","grade":"Sahih"},{"name":"Zubair Ali Zai","grade":"Sahih Muslim (269)"}]},{"id":26,"text":"معاذ بن جبل رضی اللہ عنہ کہتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: لعنت کی تین چیزوں سے بچو: مسافروں کے اترنے کی جگہ میں، عام راستے میں، اور سائے میں پاخانہ پیشاب کرنے سے ۔","section":1,"grades":[{"name":"Al-Albani","grade":"Hasan"},{"name":"Muhammad Muhyi Al-Din Abdul Hamid","grade":"Hasan"},{"name":"Shuaib Al Arnaut","grade":"Hasan Lighairihi"},{"name":"Zubair Ali Zai","grade":"Daif"}]},{"id":27,"text":"عبداللہ بن مغفل رضی اللہ عنہ کہتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: تم میں سے کوئی شخص ہرگز ایسا نہ کرے کہ اپنے غسل خانے ( حمام ) میں پیشاب کرے پھر اسی میں نہائے ۔ احمد کی روایت میں ہے: پھر اسی میں وضو کرے، کیونکہ اکثر وسوسے اسی سے پیدا ہوتے ہیں۔","section":1,"grades":[{"name":"Al-Albani","grade":"Daif"},{"name":"Muhammad Muhyi Al-Din Abdul Hamid","grade":"Sahih"},{"name":"Shuaib Al Arnaut","grade":"Sahih Lighairihi"},{"name":"Zubair Ali Zai","grade":"Daif"}]},{"id":28,"text":"حمید بن عبدالرحمٰن حمیری کہتے ہیں کہ میری ملاقات ایک ایسے شخص سے ہوئی جو نبی اکرم صلی اللہ علیہ وسلم کی صحبت میں اسی طرح رہا جیسے ابوہریرہ رضی اللہ عنہ آپ صلی اللہ علیہ وسلم کی صحبت میں رہے، اس نے کہا: رسول اللہ صلی اللہ علیہ وسلم نے منع کیا ہے کہ ہم میں سے کوئی ہر روز کنگھی کرے یا غسل خانہ میں پیشاب کرے۔","section":1,"grades":[{"name":"Al-Albani","grade":"Sahih"},{"name":"Muhammad Muhyi Al-Din Abdul Hamid","grade":"Sahih"},{"name":"Shuaib Al Arnaut","grade":"Sahih"},{"name":"Zubair Ali Zai","grade":"Isnaad Sahih"}]},{"id":29,"text":"عبدللہ بن سرجس رضی اللہ عنہ کہتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے سوراخ میں پیشاب کرنے سے منع فرمایا ہے۔ ہشام دستوائی کا بیان ہے کہ لوگوں نے قتادہ سے پوچھا: کس وجہ سے سوراخ میں پیشاب کرنا ناپسندیدہ ہے؟ انہوں نے کہا: کہا جاتا تھا کہ وہ جنوں کی جائے سکونت ( گھر ) ہے۔","section":1,"grades":[{"name":"Al-Albani","grade":"Daif"},{"name":"Muhammad Muhyi Al-Din Abdul Hamid","grade":"Daif"},{"name":"Zubair Ali Zai","grade":"Daif"}]},{"id":30,"text":"ابوبردہ کہتے ہیں کہ مجھ سے ام المؤمنین عائشہ رضی اللہ عنہا نے بیان کیا ہے کہ نبی اکرم صلی اللہ علیہ وسلم جب بیت الخلاء ( پاخانہ ) سے نکلتے تو فرماتے تھے: «غفرانك» اے اللہ! میں تیری بخشش چاہتا ہوں ۔","section":1,"grades":[{"name":"Al-Albani","grade":"Sahih"},{"name":"Muhammad Muhyi Al-Din Abdul Hamid","grade":"Sahih"},{"name":"Zubair Ali Zai","grade":"Isnaad Sahih"}]}]}'),d=JSON.parse('{"name":"ترمذی","sections":{"1":"طہارت پر کتاب"},"hadiths":[{"id":1,"text":"عبداللہ بن عمر رضی الله عنہما سے روایت ہے کہ نبی اکرم صلی الله علیہ وسلم نے فرمایا: ”نماز بغیر وضو کے قبول نہیں کی جاتی ۲؎ اور نہ صدقہ حرام مال سے قبول کیا جاتا ہے“۔ امام ترمذی کہتے ہیں: ۱- اس باب میں یہ حدیث سب سے صحیح اور حسن ہے ۳؎۔ ۲- اس باب میں ابوالملیح کے والد اسامہ، ابوہریرہ اور انس رضی الله عنہم سے بھی احادیث آئی ہیں۔","section":1,"grades":[{"name":"Ahmad Muhammad Shakir","grade":"Sahih"},{"name":"Al-Albani","grade":"Sahih"},{"name":"Zubair Ali Zai","grade":"Sahih - Bukhari And Muslim"}]},{"id":2,"text":"ابوہریرہ رضی الله عنہ کہتے ہیں کہ رسول اللہ صلی الله علیہ وسلم نے فرمایا: ”جب مسلمان یا مومن بندہ وضو کرتا اور اپنا چہرہ دھوتا ہے تو پانی کے ساتھ یا پانی کے آخری قطرے کے ساتھ اس کے چہرے سے وہ تمام گناہ جھڑ جاتے ہیں ۱؎، جو اس کی آنکھوں نے کیے تھے یا اسی طرح کی کوئی اور بات فرمائی، پھر جب وہ اپنے ہاتھوں کو دھوتا ہے تو پانی کے ساتھ یا پانی کے آخری قطرے کے ساتھ وہ تمام گناہ جھڑ جاتے ہیں جو اس کے ہاتھوں سے ہوئے ہیں، یہاں تک کہ وہ گناہوں سے پاک و صاف ہو کر نکلتا ہے“ ۲؎۔ امام ترمذی کہتے ہیں: ۱- یہ حدیث حسن صحیح ہے ۳؎، ۲- اس باب میں عثمان بن عفان، ثوبان، صنابحی، عمرو بن عبسہ، سلمان اور عبداللہ بن عمرو رضی الله عنہم سے بھی احادیث آئی ہیں، ۳- صنابحی جنہوں نے ابوبکر صدیق رضی الله عنہ سے روایت کی ہے، ان کا سماع رسول اللہ صلی الله علیہ وسلم سے نہیں ہے، ان کا نام عبدالرحمٰن بن عسیلہ، اور کنیت ابوعبداللہ ہے، انہوں نے رسول اللہ صلی الله علیہ وسلم کے پاس سفر کیا، راستے ہی میں تھے کہ رسول اللہ صلی الله علیہ وسلم کا انتقال ہو گیا، انہوں نے نبی اکرم صلی الله علیہ وسلم سے متعدد احادیث روایت کی ہیں۔ اور صنابح بن اعسرا حمسی صحابی رسول ہیں، ان کو صنابحی بھی کہا جاتا ہے، انہی کی حدیث ہے کہ میں نے نبی اکرم صلی الله علیہ وسلم کو فرماتے سنا: ”میں تمہارے ذریعہ سے دوسری امتوں میں اپنی اکثریت پر فخر کروں گا تو میرے بعد تم ہرگز ایک دوسرے کو قتل نہ کرنا“۔","section":1,"grades":[{"name":"Ahmad Muhammad Shakir","grade":"Sahih"},{"name":"Al-Albani","grade":"Sahih"},{"name":"Bashar Awad Maarouf","grade":"Hasan Sahih"},{"name":"Zubair Ali Zai","grade":"Sahih Muslim"}]},{"id":3,"text":"علی رضی الله عنہ کہتے ہیں کہ رسول اللہ صلی الله علیہ وسلم نے فرمایا: ”نماز کی کنجی وضو ہے، اور اس کا تحریمہ صرف «اللہ اکبر» کہنا ہے ۱؎ اور نماز میں جو چیزیں حرام تھیں وہ «السلام علیکم ورحمة اللہ» کہنے ہی سے حلال ہوتی ہیں“ ۲؎۔ امام ترمذی کہتے ہیں: ۱- اس باب میں یہ حدیث سب سے صحیح اور حسن ہے، ۲- عبداللہ بن محمد بن عقیل صدوق ہیں ۳؎، بعض اہل علم نے ان کے حافظہ کے تعلق سے ان پر کلام کیا ہے، میں نے محمد بن اسماعیل بخاری کو یہ کہتے ہوئے سنا کہ احمد بن حنبل، اسحاق بن ابراہیم بن راہویہ اور حمیدی: عبداللہ بن محمد بن عقیل کی روایت سے حجت پکڑتے تھے، اور وہ مقارب الحدیث ۴؎ ہیں، ۳- اس باب میں جابر اور ابو سعید خدری رضی الله عنہما سے بھی احادیث آئی ہیں۔","section":1,"grades":[{"name":"Ahmad Muhammad Shakir","grade":"Hasan Sahih"},{"name":"Al-Albani","grade":"Hasan Sahih"},{"name":"Bashar Awad Maarouf","grade":"Hasan"},{"name":"Zubair Ali Zai","grade":"Hasan"}]},{"id":4,"text":"جابر بن عبداللہ رضی الله عنہما کہتے ہیں کہ رسول اللہ صلی الله علیہ وسلم نے فرمایا: ”نماز جنت کی کنجی ہے، اور نماز کی کنجی وضو ہے“۔","section":1,"grades":[{"name":"Ahmad Muhammad Shakir","grade":"Sahih Lighairihi"},{"name":"Al-Albani","grade":"Sahih"},{"name":"Zubair Ali Zai","grade":"Daif"}]},{"id":5,"text":"انس بن مالک رضی الله عنہ کہتے ہیں کہ نبی اکرم صلی الله علیہ وسلم جب قضائے حاجت کے لیے پاخانہ میں داخل ہوتے تو یہ دعا پڑھتے: «اللهم إني أعوذ بك من الخبث والخبيث أو الخبث والخبائث» ”اے اللہ! میں تیری پناہ چاہتا ہوں ناپاکی سے اور ناپاک شخص سے، یا ناپاک جنوں سے اور ناپاک جنیوں سے“ ۱؎۔ شعبہ کہتے ہیں: عبدالعزیز نے دوسری بار «اللهم إني أعوذ بك» کے بجائے «أعوذ بالله» کہا۔ امام ترمذی کہتے ہیں: ۱- اس باب میں علی، زید بن ارقم، جابر اور ابن مسعود رضی الله عنہم سے بھی احادیث آئی ہیں، ۲- انس رضی الله عنہ کی حدیث اس باب میں سب سے صحیح اور عمدہ ہے، ۳- زید بن ارقم کی سند میں اضطراب ہے، امام بخاری کہتے ہیں: کہ ہو سکتا ہے قتادہ نے اسے ( زید بن ارقم سے اور نضر بن انس عن أبیہ ) دونوں سے ایک ساتھ روایت کیا ہو۔","section":1,"grades":[{"name":"Ahmad Muhammad Shakir","grade":"Sahih"},{"name":"Al-Albani","grade":"Sahih"},{"name":"Zubair Ali Zai","grade":"Isnaad Sahih Bukhari And Muslim"}]},{"id":6,"text":"انس بن مالک کہتے ہیں کہ نبی اکرم صلی الله علیہ وسلم جب قضائے حاجت کے لیے بیت الخلاء میں داخل ہوتے تو پڑھتے: «اللهم إني أعوذ بك من الخبث والخبائث» ”اے اللہ میں تیری پناہ چاہتا ہوں ناپاک جنوں اور ناپاک جنیوں سے“ ۱؎۔ امام ترمذی کہتے ہیں: یہ حدیث حسن صحیح ہے۔","section":1,"grades":[{"name":"Ahmad Muhammad Shakir","grade":"Sahih"},{"name":"Al-Albani","grade":"Sahih"},{"name":"Bashar Awad Maarouf","grade":"Hasan Sahih"},{"name":"Zubair Ali Zai","grade":"Sahih - Agreed Upon"}]},{"id":7,"text":"ام المؤمنین عائشہ رضی الله عنہا کہتی ہیں کہ نبی اکرم صلی الله علیہ وسلم قضائے حاجت کے بعد جب پاخانہ سے نکلتے تو فرماتے: «غفرانك‏» یعنی ”اے اللہ: میں تیری بخشش کا طلب گار ہوں“ ۱؎۔ امام ترمذی کہتے ہیں: ۱- یہ حدیث حسن غریب ہے ۲؎، ۲- اس باب میں عائشہ رضی الله عنہا ہی کی حدیث معروف ہے ۳؎۔","section":1,"grades":[{"name":"Ahmad Muhammad Shakir","grade":"Sahih"},{"name":"Al-Albani","grade":"Sahih"},{"name":"Zubair Ali Zai","grade":"Isnaad Sahih"}]},{"id":8,"text":"ابوایوب انصاری رضی الله عنہ کہتے ہیں کہ رسول اللہ صلی الله علیہ وسلم نے فرمایا: ”جب تم قضائے حاجت کے لیے جاؤ تو پاخانہ یا پیشاب کے وقت قبلہ کی طرف منہ نہ کرو اور نہ پیٹھ، بلکہ منہ کو پورب یا پچھم کی طرف کرو“ ۱؎۔ ابوایوب انصاری کہتے ہیں: ہم شام آئے تو ہم نے دیکھا کہ پاخانے قبلہ رخ بنائے گئے ہیں تو قبلہ کی سمت سے ترچھے مڑ جاتے اور ہم اللہ سے مغفرت طلب کرتے۔ امام ترمذی کہتے ہیں: ۱- اس باب میں عبداللہ بن حارث بن جزء زبیدی، معقل بن ابی ہیشم ( معقل بن ابی معقل ) ابوامامہ، ابوہریرہ اور سہل بن حنیف رضی الله عنہم سے بھی احادیث آئی ہیں، ۲- ابوایوب کی حدیث اس باب میں سب سے عمدہ اور سب سے صحیح ہے، ۳- ابوالولید مکی کہتے ہیں: ابوعبداللہ محمد بن ادریس شافعی کا کہنا ہے کہ نبی اکرم صلی الله علیہ وسلم نے جو یہ فرمایا ہے کہ پاخانہ یا پیشاب کے وقت قبلہ کی طرف منہ نہ کرو اور نہ پیٹھ، اس سے مراد صرف صحراء ( میدان ) میں نہ کرنا ہے، رہے بنے بنائے پاخانہ گھر تو ان میں قبلہ کی طرف منہ کرنا جائز ہے، اسی طرح اسحاق بن ابراہیم بن راہویہ نے بھی کہا ہے، احمد بن حنبل کہتے ہیں کہ نبی اکرم صلی الله علیہ وسلم سے پاخانہ یا پیشاب کے وقت قبلہ کی طرف صرف پیٹھ کرنے کی رخصت ہے، رہا قبلہ کی طرف منہ کرنا تو یہ کسی بھی طرح جائز نہیں، گویا کہ ( امام احمد ) قبلہ کی طرف منہ کرنے کو نہ صحراء میں جائز قرار دیتے ہیں اور نہ ہی بنے بنائے پاخانہ گھر میں ( البتہ پیٹھ کرنے کو بیت الخلاء میں جائز سمجھتے ہیں ) ۔","section":1,"grades":[{"name":"Ahmad Muhammad Shakir","grade":"Sahih"},{"name":"Al-Albani","grade":"Sahih"},{"name":"Zubair Ali Zai","grade":"Sahih - Agreed Upon"}]},{"id":9,"text":"جابر بن عبداللہ رضی الله عنہما کہتے ہیں کہ نبی اکرم صلی الله علیہ وسلم نے اس بات سے منع فرمایا کہ ہم پیشاب کے وقت قبلہ کی طرف منہ کریں، پھر میں نے وفات سے ایک سال پہلے آپ کو قبلہ کی طرف منہ کر کے پیشاب کرتے ہوئے دیکھا۔ امام ترمذی کہتے ہیں: ۱- اس باب میں جابر رضی الله عنہ کی یہ حدیث حسن غریب ہے، ۲- اس باب میں ابوقتادہ، عائشہ، اور عمار بن یاسر رضی الله عنہم سے بھی احادیث آئی ہیں۔","section":1,"grades":[{"name":"Ahmad Muhammad Shakir","grade":"Sahih"},{"name":"Al-Albani","grade":"Sahih"},{"name":"Bashar Awad Maarouf","grade":"Hasan"},{"name":"Zubair Ali Zai","grade":"Hasan"}]},{"id":10,"text":"عبداللہ بن لہیعہ نے یہ حدیث ابوالزبیر سے اور ابوالزبیر نے جابر رضی الله عنہ سے کہ ابوقتادہ رضی الله عنہ نے نبی اکرم صلی الله علیہ وسلم کو قبلہ کی طرف منہ کر کے پیشاب کرتے ہوئے دیکھا ہے۔ جابر رضی الله عنہ کی نبی اکرم صلی الله علیہ وسلم سے یہ حدیث ابن لہیعہ کی حدیث ( جس میں جابر کے بعد ابوقتادہ رضی الله عنہ کا واسطہ ہے ) سے زیادہ صحیح ہے، ابن لہیعہ محدّثین کے نزدیک ضعیف ہیں، یحییٰ بن سعیدالقطان وغیرہ نے ان کی حفظ کے اعتبار سے تضعیف کی ہے۔","section":1,"grades":[{"name":"Ahmad Muhammad Shakir","grade":"Daif Isnaad"},{"name":"Al-Albani","grade":"Daif Isnaad"},{"name":"Bashar Awad Maarouf","grade":"Daif"},{"name":"Zubair Ali Zai","grade":"Daif"}]},{"id":11,"text":"عبداللہ بن عمر رضی الله عنہما کہتے ہیں کہ ایک روز میں ( اپنی بہن ) حفصہ رضی الله عنہا کے گھر کی چھت پر چڑھا تو نبی اکرم صلی الله علیہ وسلم کو دیکھا کہ آپ شام کی طرف منہ اور کعبہ کی طرف پیٹھ کر کے قضائے حاجت فرما رہے ہیں ۱؎۔ امام ترمذی کہتے ہیں: یہ حدیث حسن صحیح ہے۔","section":1,"grades":[{"name":"Ahmad Muhammad Shakir","grade":"Sahih"},{"name":"Al-Albani","grade":"Sahih"},{"name":"Bashar Awad Maarouf","grade":"Hasan Sahih"},{"name":"Zubair Ali Zai","grade":"Sahih - Agreed Upon"}]},{"id":12,"text":"ام المؤمنین عائشہ رضی الله عنہا کہتی ہیں کہ جو تم سے یہ کہے کہ نبی اکرم صلی الله علیہ وسلم کھڑے ہو کر پیشاب کرتے تھے تو تم اس کی تصدیق نہ کرنا، آپ بیٹھ کر ہی پیشاب کرتے تھے ۱؎۔ امام ترمذی کہتے ہیں: ۱- اس باب میں عمر، بریدہ، عبدالرحمٰن بن حسنہ رضی الله عنہم سے بھی احادیث آئی ہیں، ۲- اس باب میں عائشہ رضی الله عنہا کی یہ حدیث سب سے زیادہ عمدہ اور صحیح ہے، ۳- عمر رضی الله عنہ کی حدیث میں ہے کہ مجھے نبی اکرم صلی الله علیہ وسلم نے کھڑے ہو کر پیشاب کرتے ہوئے دیکھا تو فرمایا: ”عمر! کھڑے ہو کر پیشاب نہ کرو“، چنانچہ اس کے بعد سے میں نے کبھی بھی کھڑے ہو کر پیشاب نہیں کیا۔ عمر رضی الله عنہ کی اس حدیث کو عبدالکریم ابن ابی المخارق نے مرفوعاً روایت کیا ہے اور وہ محدثین کے نزدیک ضعیف ہیں، ایوب سختیانی نے ان کی تضعیف کی ہے اور ان پر کلام کیا ہے، نیز یہ حدیث عبیداللہ نے نافع سے اور نافع نے ابن عمر سے کہ عمر رضی الله عنہ کہتے ہیں کہ میں نے جب سے اسلام قبول کیا کبھی کھڑے ہو کر پیشاب نہیں کیا۔ یہ حدیث عبدالکریم بن ابی المخارق کی حدیث سے ( روایت کے اعتبار سے ) زیادہ صحیح ہے ۲؎، ۴- اس باب میں بریدۃ رضی الله عنہ کی حدیث محفوظ نہیں ہے، ۵- کھڑے ہو کر پیشاب کرنے کی ممانعت ادب کے اعتبار سے ہے حرام نہیں ہے ۳؎، ۶- عبداللہ بن مسعود رضی الله عنہ سے منقول ہے کہ تم کھڑے ہو کر پیشاب کرو یہ پھوہڑ پن ہے ۴؎۔","section":1,"grades":[{"name":"Ahmad Muhammad Shakir","grade":"Sahih"},{"name":"Al-Albani","grade":"Daif"},{"name":"Bashar Awad Maarouf","grade":"Daif"},{"name":"Zubair Ali Zai","grade":"Daif"}]},{"id":13,"text":"حذیفہ بن یمان رضی الله عنہ کہتے ہیں کہ نبی اکرم صلی الله علیہ وسلم کا گزر ایک قوم کے کوڑے کرکٹ کے ڈھیر پر سے ہوا تو آپ نے اس پر کھڑے ہو کر پیشاب کیا، میں آپ کے لیے وضو کا پانی لایا، اسے رکھ کر میں پیچھے ہٹنے لگا، تو آپ نے مجھے اشارے سے بلایا، میں ( آ کر ) آپ کی ایڑیوں کے پاس کھڑا ہو گیا، آپ نے وضو کیا اور اپنے موزوں پر مسح کیا۔ امام ترمذی کہتے ہیں: ۱- وکیع کہتے ہیں: یہ حدیث مسح کے سلسلہ میں نبی اکرم صلی الله علیہ وسلم سے مروی حدیثوں میں سب سے زیادہ صحیح ہے۔ ۲- یہ حدیث بروایت مغیرہ بن شعبہ رضی الله عنہ بھی نبی اکرم صلی الله علیہ وسلم سے مروی ہے ۱؎ ابووائل کی حدیث جسے انہوں نے حذیفہ سے روایت کیا ( مغیرہ کی روایت سے ) زیادہ صحیح ہے ۲؎، ۳- محدثین میں سے اہل علم کی ایک جماعت نے کھڑے ہو کر پیشاب کرنے کی اجازت دی ہے۔","section":1,"grades":[{"name":"Ahmad Muhammad Shakir","grade":"Sahih"},{"name":"Al-Albani","grade":"Sahih"},{"name":"Zubair Ali Zai","grade":"Sahih - Agreed Upon"}]},{"id":14,"text":"انس رضی الله عنہ کہتے ہیں کہ نبی اکرم صلی الله علیہ وسلم جب قضائے حاجت کا ارادہ فرماتے تو جب تک زمین سے بالکل قریب نہ ہو جاتے اپنے کپڑے نہیں اٹھاتے تھے۔ دوسری سند میں اعمش سے روایت ہے، ابن عمر رضی الله عنہما کہتے ہیں کہ نبی اکرم صلی الله علیہ وسلم جب قضائے حاجت کا ارادہ فرماتے کپڑے جب تک زمین سے قریب نہیں ہو جاتے نہیں اٹھاتے تھے ۱؎۔ امام ترمذی کہتے ہیں: یہ دونوں احادیث مرسل ہیں، اس لیے کہ کہا جاتا ہے: دونوں احادیث کے راوی سلیمان بن مہران الأعمش نے نہ ہی تو انس بن مالک رضی الله عنہ سے سماعت کی ہے اور نہ ہی کسی اور صحابی سے، صرف اتنا ہے کہ انس کو صرف انہوں نے دیکھا ہے، اعمش کہتے ہیں کہ میں نے انہیں نماز پڑھتے دیکھا ہے پھر ان کی نماز کی کیفیت بیان کی۔","section":1,"grades":[{"name":"Ahmad Muhammad Shakir","grade":"Sahih"},{"name":"Al-Albani","grade":"Sahih"},{"name":"Zubair Ali Zai","grade":"Daif"}]},{"id":15,"text":"ابوقتادہ حارث بن ربعی انصاری رضی الله عنہ کہتے ہیں کہ نبی اکرم صلی الله علیہ وسلم نے اس بات سے منع فرمایا ہے کہ آدمی اپنے داہنے ہاتھ سے اپنا ذکر ( عضو تناسل ) چھوئے ۱؎۔ اس باب میں عائشہ، سلمان، ابوہریرہ اور سھل بن حنیف رضی الله عنہم سے بھی احادیث آئی ہیں۔ امام ترمذی کہتے ہیں: ۱- یہ حدیث حسن صحیح ہے، ۲- اکثر اہل علم کا اسی پر عمل ہے، ان لوگوں نے داہنے ہاتھ سے استنجاء کرنے کو مکروہ جانا ہے۔","section":1,"grades":[{"name":"Ahmad Muhammad Shakir","grade":"Sahih"},{"name":"Al-Albani","grade":"Sahih"},{"name":"Bashar Awad Maarouf","grade":"Hasan Sahih"},{"name":"Zubair Ali Zai","grade":"Sahih - Agreed Upon"}]},{"id":16,"text":"عبدالرحمٰن بن یزید کہتے ہیں کہ سلمان فارسی رضی الله عنہ سے بطور طنز یہ بات کہی گئی کہ تمہارے نبی نے تمہیں ساری چیزیں سکھائی ہیں حتیٰ کہ پیشاب پاخانہ کرنا بھی، تو سلمان فارسی رضی الله عنہ نے بطور فخر کہا: ہاں، ایسا ہی ہے ہمارے نبی نے ہمیں پیشاب پاخانہ کے وقت قبلہ کی طرف منہ کرنے، داہنے ہاتھ سے استنجاء کرنے، اور تین پتھر سے کم سے استنجاء کرنے، اور گوبر اور ہڈی سے استنجاء کرنے سے ہمیں منع فرمایا ہے۔ امام ترمذی کہتے ہیں: ۱- اس باب میں عائشہ، خزیمہ بن ثابت جابر اور خلاد بن السائب رضی الله عنہم سے بھی احادیث آئی ہیں، ۲- سلمان رضی الله عنہ کی حدیث اس باب میں حسن صحیح ہے، ۳- صحابہ و تابعین میں سے اکثر اہل علم کا یہی قول ہے کہ پتھر سے استنجاء کر لینا کافی ہے جب وہ پاخانہ اور پیشاب کے اثر کو زائل و پاک کر دے اگرچہ پانی سے استنجاء نہ کیا گیا ہو، یہی قول ثوری، ابن مبارک، شافعی، احمد اور اسحاق بن راہویہ کا بھی ہے۔","section":1,"grades":[{"name":"Ahmad Muhammad Shakir","grade":"Sahih"},{"name":"Al-Albani","grade":"Sahih"},{"name":"Bashar Awad Maarouf","grade":"Hasan Sahih"},{"name":"Zubair Ali Zai","grade":"Sahih Muslim"}]},{"id":17,"text":"عبداللہ بن مسعود رضی الله عنہ کہتے ہیں کہ نبی اکرم صلی الله علیہ وسلم قضائے حاجت کے لیے نکلے تو آپ نے فرمایا: ”میرے لیے تین پتھر ڈھونڈ لاؤ“، میں دو پتھر اور ایک گوبر کا ٹکڑا لے کر آپ کی خدمت میں آیا تو آپ نے دونوں پتھروں کو لے لیا اور گوبر کے ٹکڑے کو پھینک دیا اور فرمایا: ”یہ ناپاک ہے“ ۱؎۔ ( ابواسحاق سبیعی ثقہ اور مدلس راوی ہیں، بڑھاپے میں حافظہ میں اختلاط ہو گیا تھا اس لیے جن رواۃ نے ان سے اختلاط سے پہلے سنا ان کی روایت مقبول ہے، اور جن لوگوں نے اختلاط کے بعد سنا ان کی روایت ضعیف، یہ حدیث ابواسحاق سے ان کے تلامذہ نے مختلف انداز سے روایت کی ہے ) ۔ امام ترمذی نے یہاں: ابن مسعود کی اس حدیث کو بسند «اسرائیل عن ابی اسحاق عن ابی عبیدہ عن ابن مسعود» روایت کرنے کے بعد اسرائیل کی متابعت ۲؎ میں قیس بن الربیع کی روایت کا ذکر کیا ہے، پھر بسند «معمر و عمار بن رزیق عن ابی اسحاق عن علقمہ عن ابن مسعود» کی روایت ذکر کی ہے، پھر بسند «زکریا بن ابی زائدہ و زہیر عن ابی اسحاق عن عبدالرحمٰن بن یزید عن اسود بن یزید عن عبداللہ بن مسعود» روایت ذکر کی اور فرمایا کہ اس حدیث میں اضطراب ہے، نیز اسرائیل کی روایت کو صحیح ترین قرار دیا، یہ بھی واضح کیا کہ ابو عبیدۃ کا سماع اپنے والد ابن مسعود سے نہیں ہے پھر واضح کیا کہ زہیر نے اس حدیث کو بسند «ابواسحاق عن عبدالرحمٰن بن الاسود عن أبیہ عن عبداللہ بن مسعود» روایت کیا ہے، تو ان محمد بن اسماعیل بخاری نے اپنی صحیح میں اس کو جگہ دے کر اپنی ترجیح کا ذکر کر دیا ہے، جب کہ ترمذی کا استدلال یہ ہے کہ «اسرائیل و قیس عن أبی اسحاق» زیادہ صحیح روایت اس لیے ہے کہ اسرائیل ابواسحاق کی حدیث کے زیادہ حافظ و متقن ہیں، قیس نے بھی اسرائیل کی متابعت کی ہے، اور واضح رہے کہ زہیر نے ابواسحاق سے آخر میں اختلاط کے بعد سنا ہے، اس لیے ان کی روایت اسرائیل کی روایت کے مقابلے میں قوی نہیں ہے ۳؎۔","section":1,"grades":[{"name":"Ahmad Muhammad Shakir","grade":"Sahih"},{"name":"Al-Albani","grade":"Sahih"},{"name":"Zubair Ali Zai","grade":"Sahih"}]},{"id":18,"text":"عبداللہ بن مسعود رضی الله عنہ کہتے ہیں کہ رسول اللہ صلی الله علیہ وسلم نے فرمایا: ”گوبر اور ہڈی سے استنجاء نہ کرو کیونکہ وہ تمہارے بھائیوں جنوں کی خوراک ہے“ ۱؎۔ امام ترمذی کہتے ہیں: ۱- اس باب میں ابوہریرہ، سلمان، جابر، ابن عمر رضی الله عنہم سے بھی احادیث مروی ہیں۔ ۲- اسماعیل بن ابراہیم وغیرہ نے بسند «داود ابن ابی ہند عن شعبی عن علقمہ» روایت کی ہے کہ عبداللہ بن مسعود رضی الله عنہ «لیلة الجن» میں نبی اکرم صلی الله علیہ وسلم کے ساتھ تھے ۲؎ آگے انہوں نے پوری حدیث ذکر کی جو لمبی ہے، شعبی کہتے ہیں کہ نبی اکرم صلی الله علیہ وسلم نے فرمایا گوبر اور ہڈی سے استنجاء نہ کرو کیونکہ یہ تمہارے بھائیوں ( جنوں ) کی خوراک ہے، ۳- گویا اسماعیل بن ابراہیم کی روایت حفص بن غیاث کی روایت سے زیادہ صحیح ہے ۳؎، ۴- اہل علم کا اسی حدیث پر عمل ہے، ۵- اور اس باب میں جابر اور ابن عمر رضی الله عنہما سے بھی احادیث آئی ہیں۔","section":1,"grades":[{"name":"Ahmad Muhammad Shakir","grade":"Sahih"},{"name":"Al-Albani","grade":"Daif"},{"name":"Zubair Ali Zai","grade":"Sahih - Bukhari And Muslim"}]},{"id":19,"text":"ام المؤمنین عائشہ رضی الله عنہا کہتی ہیں کہ تم عورتیں اپنے شوہروں سے کہو کہ وہ پانی سے استنجاء کیا کریں، میں ان سے ( یہ بات کہتے ) شرما رہی ہوں، کیونکہ رسول اللہ صلی الله علیہ وسلم ایسا ہی کرتے تھے۔ امام ترمذی کہتے ہیں: ۱- یہ حدیث حسن صحیح ہے، ۲- اس باب میں جریر بن عبداللہ بجلی، انس، اور ابوہریرہ رضی الله عنہم سے بھی احادیث آئی ہیں، ۳- اسی پر اہل علم کا عمل ہے ۱؎، وہ پانی سے استنجاء کرنے کو پسند کرتے ہیں اگرچہ پتھر سے استنجاء ان کے نزدیک کافی ہے پھر بھی پانی سے استنجاء کو انہوں نے مستحب اور افضل قرار دیا ہے۔ سفیان ثوری، ابن مبارک، شافعی، احمد، اسحاق بن راہویہ بھی اسی کے قائل ہیں۔","section":1,"grades":[{"name":"Ahmad Muhammad Shakir","grade":"Sahih"},{"name":"Al-Albani","grade":"Sahih"},{"name":"Bashar Awad Maarouf","grade":"Hasan Sahih"},{"name":"Zubair Ali Zai","grade":"Sahih"}]},{"id":20,"text":"مغیرہ بن شعبہ رضی الله عنہ کہتے ہیں کہ میں نبی اکرم صلی الله علیہ وسلم کے ساتھ ایک سفر میں تھا، آپ قضائے حاجت کے لیے نکلے تو بہت دور نکل گئے ۱؎۔ امام ترمذی کہتے ہیں: ۱- یہ حدیث حسن صحیح ہے، ۲- اس باب میں عبدالرحمٰن بن ابی قراد، ابوقتادہ، جابر، یحییٰ بن عبید عن أبیہ، ابو موسیٰ، ابن عباس اور بلال بن حارث رضی الله عنہم سے بھی احادیث آئی ہیں، ۳- روایت کی جاتی ہے کہ نیز نبی اکرم صلی الله علیہ وسلم پیشاب کے لیے اس طرح جگہ ڈھونڈتے تھے جس طرح مسافر اترنے کے لیے جگہ ڈھونڈتا ہے۔ ۴- ابوسلمہ کا نام عبداللہ بن عبدالرحمٰن بن عوف زہری ہے۔","section":1,"grades":[{"name":"Ahmad Muhammad Shakir","grade":"Sahih"},{"name":"Al-Albani","grade":"Sahih"},{"name":"Bashar Awad Maarouf","grade":"Hasan Sahih"},{"name":"Zubair Ali Zai","grade":"Isnaad Hasan"}]},{"id":21,"text":"عبداللہ بن مغفل رضی الله عنہ کہتے ہیں کہ عبداللہ بن مغفل ؓ کہتے ہیں کہ نبی اکرم ﷺ نے اس بات سے منع فرمایا ہے کہ آدمی اپنے غسل خانہ میں پیشاب کرے اور فرمایا : ” زیادہ تر وسوسے اسی سے پیدا ہوتے ہیں “ ۔ امام ترمذی کہتے ہیں : ۱- اس باب میں ایک اور صحابی سے بھی روایت ہے ، ۲- یہ حدیث غریب ہے ، ہم اسے صرف اشعث بن عبداللہ کی روایت سے مرفوع جانتے ہیں ، انہیں اشعث اعمی بھی کہا جاتا ہے ، ۳- اہل علم میں سے کچھ لوگوں نے غسل خانے میں پیشاب کرنے کو مکروہ قرار دیا ہے ، ان لوگوں کا کہنا ہے کہ زیادہ تر وسوسے اسی سے جنم لیتے ہیں ، ۴- بعض اہل علم نے اس کی رخصت دی ہے جن میں سے ابن سیرین بھی ہیں ، ابن سیرین سے کہا گیا : کہا جاتا ہے کہ اکثر وسوسے اسی سے جنم لیتے ہیں ؟ تو انہوں نے جواب دیا کہ ہمارا رب اللہ ہے ، اس کا کوئی شریک نہیں ، عبداللہ بن مبارک کہتے ہیں کہ غسل خانے میں پیشاب کرنے کو جائز قرار دیا گیا ہے ، بشرطیکہ اس میں سے پانی بہ جاتا ہو","section":1,"grades":[{"name":"Ahmad Muhammad Shakir","grade":"Sahih"},{"name":"Al-Albani","grade":"Sahih"},{"name":"Bashar Awad Maarouf","grade":"Hasan"},{"name":"Zubair Ali Zai","grade":"Daif"}]},{"id":22,"text":"ابوہریرہ رضی الله عنہ کہتے ہیں کہ رسول اللہ صلی الله علیہ وسلم نے فرمایا: ”اگر مجھے اپنی امت کو حرج اور مشقت میں مبتلا کرنے کا خطرہ نہ ہوتا تو میں انہیں ہر نماز کے وقت مسواک کرنے کا حکم دیتا“ ۱؎۔ امام ترمذی کہتے ہیں: ۱- بروایت ابوسلمہ، ابوہریرہ اور زید بن خالد رضی الله عنہما کی مروی دونوں حدیثیں میرے نزدیک صحیح ہیں، محمد بن اسماعیل بخاری کا خیال ہے کہ ابوسلمہ کی زید بن خالد رضی الله عنہ سے مروی حدیث زیادہ صحیح ہے ۲؎، ۲- اس باب میں ابوبکر صدیق، علی، عائشہ، ابن عباس، حذیفہ، زید بن خالد، انس، عبداللہ بن عمرو، ابن عمر، ام حبیبہ، ابوامامہ، ابوایوب، تمام بن عباس، عبداللہ بن حنظلہ، ام سلمہ، واثلہ بن الاسقع اور ابوموسیٰ اشعری رضی الله عنہم سے بھی احادیث آئی ہیں۔","section":1,"grades":[{"name":"Ahmad Muhammad Shakir","grade":"Sahih"},{"name":"Al-Albani","grade":"Sahih"},{"name":"Bashar Awad Maarouf","grade":"Sahih"},{"name":"Zubair Ali Zai","grade":"Sahih"}]},{"id":23,"text":"زید بن خالد جہنی رضی الله عنہ کہتے ہیں کہ میں نے رسول اللہ صلی الله علیہ وسلم کو یہ فرماتے ہوئے سنا ہے: ”اگر مجھے اپنی امت کو حرج و مشقت میں مبتلا کرنے کا خطرہ نہ ہوتا تو میں انہیں ہر صلاۃ کے وقت ( وجوباً ) مسواک کرنے کا حکم دیتا، نیز میں عشاء کو تہائی رات تک مؤخر کرتا ( راوی حدیث ) ابوسلمہ کہتے ہیں: اس لیے زید بن خالد رضی الله عنہ نماز کے لیے مسجد آتے تو مسواک ان کے کان پر بالکل اسی طرح ہوتی جیسے کاتب کے کان پر قلم ہوتا ہے، وہ نماز کے لیے کھڑے ہوتے تو مسواک کرتے پھر اسے اس کی جگہ پر واپس رکھ لیتے ۱؎۔ امام ترمذی کہتے ہیں: یہ حدیث حسن صحیح ہے۔","section":1,"grades":[{"name":"Ahmad Muhammad Shakir","grade":"Sahih"},{"name":"Al-Albani","grade":"Sahih"},{"name":"Bashar Awad Maarouf","grade":"Hasan Sahih"},{"name":"Zubair Ali Zai","grade":"Daif"}]},{"id":24,"text":"ابوہریرہ رضی الله عنہ سے روایت ہے کہ نبی اکرم صلی الله علیہ وسلم نے فرمایا: ”جب تم میں سے کوئی رات کو نیند سے اٹھے تو اپنا ہاتھ برتن ۱؎ میں نہ ڈالے جب تک کہ اس پر دو یا تین بار پانی نہ ڈال لے، کیونکہ وہ نہیں جانتا کہ اس کا ہاتھ رات میں کہاں کہاں رہا ہے“۔ امام ترمذی کہتے ہیں: ۱- اس باب میں ابن عمر، جابر اور عائشہ رضی الله عنہم سے بھی احادیث آئی ہیں، ۲- یہ حدیث حسن صحیح ہے، ۳- شافعی کہتے ہیں: میں ہر سو کر اٹھنے والے کے لیے – چاہے وہ دوپہر میں قیلولہ کر کے اٹھا ہو یا کسی اور وقت میں – پسند کرتا ہوں کہ وہ جب تک اپنا ہاتھ نہ دھوئے اسے وضو کے پانی میں نہ ڈالے اور اگر اس نے دھونے سے پہلے ہاتھ ڈال دیا تو میں اس کے اس فعل کو مکروہ سمجھتا ہوں لیکن اس سے پانی فاسد نہیں ہو گا بشرطیکہ اس کے ہاتھ میں کوئی نجاست نہ لگی ہو ۲؎، احمد بن حنبل کہتے ہیں: جب کوئی رات کو جاگے اور دھونے سے پہلے پانی میں ہاتھ ڈال دے تو اس پانی کو میرے نزدیک بہا دینا بہتر ہے، اسحاق بن راہویہ کہتے ہیں: جب وہ رات یا دن کسی بھی وقت نیند سے جاگے تو اپنا ہاتھ وضو کے پانی میں نہ ڈالے جب تک کہ اسے دھو نہ لے۔","section":1,"grades":[{"name":"Ahmad Muhammad Shakir","grade":"Sahih"},{"name":"Al-Albani","grade":"Sahih"},{"name":"Bashar Awad Maarouf","grade":"Hasan Sahih"},{"name":"Zubair Ali Zai","grade":"Sahih"}]},{"id":25,"text":"سعید بن زید رضی الله عنہ کہتے ہیں کہ میں نے رسول اللہ صلی الله علیہ وسلم کو فرماتے سنا: جو «بسم اللہ» کر کے وضو شروع نہ کرے اس کا وضو نہیں ہوتا ۱؎۔ امام ترمذی کہتے ہیں: ۱- اس باب میں عائشہ، ابوہریرہ، ابو سعید خدری، سہل بن سعد اور انس رضی الله عنہم سے بھی احادیث آئی ہیں، ۲- احمد بن حنبل کہتے ہیں: مجھے اس باب میں کوئی ایسی حدیث نہیں معلوم جس کی سند عمدہ ہو، ۳- اسحاق بن راہویہ کہتے ہیں: اگر کوئی قصداً «بسم اللہ» کہنا چھوڑ دے تو وہ دوبارہ وضو کرے اور اگر بھول کر چھوڑے یا وہ اس حدیث کی تاویل کر رہا ہو تو یہ اسے کافی ہو جائے گا، ۴- محمد بن اسماعیل بخاری کہتے ہیں کہ اس باب میں سب سے اچھی یہی مذکورہ بالا حدیث رباح بن عبدالرحمٰن کی ہے، یعنی سعید بن زید بن عمرو بن نفیل کی حدیث۔","section":1,"grades":[{"name":"Ahmad Muhammad Shakir","grade":"Hasan"},{"name":"Al-Albani","grade":"Hasan"},{"name":"Bashar Awad Maarouf","grade":"Hasan"},{"name":"Zubair Ali Zai","grade":"Hasan"}]},{"id":26,"text":"اس سند سے بھی سعید بن زید رضی الله عنہ سے اوپر والی حدیث کے مثل مروی ہے۔","section":1,"grades":[{"name":"Bashar Awad Maarouf","grade":"Hasan"},{"name":"Zubair Ali Zai","grade":"Hasan"}]},{"id":27,"text":"سلمہ بن قیس رضی الله عنہ کہتے ہیں کہ رسول اللہ صلی الله علیہ وسلم نے فرمایا: ”جب تم وضو کرو تو ناک جھاڑو اور جب ڈھیلے سے استنجاء کرو تو طاق ڈھیلے لو“۔ امام ترمذی کہتے ہیں: ۱- اس باب میں عثمان، لقیط بن صبرہ، ابن عباس، مقدام بن معدیکرب، وائل بن حجر اور ابوہریرہ رضی الله عنہم سے بھی احادیث آئی ہیں، ۲- سلمہ بن قیس والی حدیث حسن صحیح ہے، ۳- جو کلی نہ کرے اور ناک میں پانی نہ چڑھائے اس کے بارے میں اہل علم میں اختلاف ہے: ایک گروہ کا کہنا ہے کہ جب کوئی ان دونوں چیزوں کو وضو میں چھوڑ دے اور نماز پڑھ لے تو وہ نماز کو لوٹائے ۱؎ ان لوگوں کی رائے ہے کہ وضو اور جنابت دونوں میں یہ حکم یکساں ہے، ابن ابی لیلیٰ، عبداللہ بن مبارک، احمد اور اسحاق بن راہویہ یہی کہتے ہیں، امام احمد ( مزید ) کہتے ہیں کہ ناک میں پانی چڑھانا کلی کرنے سے زیادہ تاکیدی حکم ہے، اور اہل علم کی ایک جماعت کہتی ہے کہ جنابت میں کلی نہ کرنے اور ناک نہ جھاڑنے کی صورت میں نماز لوٹائے اور وضو میں نہ لوٹائے ۲؎ یہ سفیان ثوری اور بعض اہل کوفہ کا قول ہے، ایک گروہ کا کہنا ہے کہ نہ وضو میں لوٹائے اور نہ جنابت میں کیونکہ یہ دونوں چیزیں مسنون ہیں، تو جو انہیں وضو اور جنابت میں چھوڑ دے اس پر نماز لوٹانا واجب نہیں، یہ مالک اور شافعی کا آخری قول ہے ۳؎۔","section":1,"grades":[{"name":"Ahmad Muhammad Shakir","grade":"Sahih"},{"name":"Al-Albani","grade":"Sahih"},{"name":"Bashar Awad Maarouf","grade":"Hasan Sahih"},{"name":"Zubair Ali Zai","grade":"Isnaad Sahih"}]},{"id":28,"text":"عبداللہ بن زید رضی الله عنہ کہتے ہیں کہ میں نے نبی اکرم صلی الله علیہ وسلم کو دیکھا کہ آپ نے ایک ہی چلو سے کلی کی اور ناک میں پانی ڈالا، تین بار آپ نے ایسا کیا ۱؎۔ امام ترمذی کہتے ہیں: ۱- اس باب میں عبداللہ بن عباس رضی الله عنہما سے بھی روایت ہے، ۲- عبداللہ بن زید رضی الله عنہما کی یہ حدیث حسن غریب ہے، ۳- مالک، سفیان، ابن عیینہ اور دیگر کئی لوگوں نے یہ حدیث عمرو بن یحییٰ سے روایت کی ہے۔ لیکن ان لوگوں نے یہ بات ذکر نہیں کی کہ نبی اکرم صلی الله علیہ وسلم نے ایک ہی چلو سے کلی کی اور ناک میں پانی ڈالا، اسے صرف خالد ہی نے ذکر کیا ہے اور خالد محدثین کے نزدیک ثقہ اور حافظ ہیں۔ بعض اہل علم نے کہا ہے کہ ایک ہی چلو سے کلی کرنا اور ناک میں پانی ڈالنا کافی ہو گا، اور بعض نے کہا ہے کہ دونوں کے لیے الگ الگ پانی لینا ہمیں زیادہ پسند ہے، شافعی کہتے ہیں کہ اگر ان دونوں کو ایک ہی چلو میں جمع کرے تو جائز ہے لیکن اگر الگ الگ چلّو سے کرے تو یہ ہمیں زیادہ پسند ہے ۲؎۔","section":1,"grades":[{"name":"Ahmad Muhammad Shakir","grade":"Sahih"},{"name":"Al-Albani","grade":"Sahih"},{"name":"Zubair Ali Zai","grade":"Sahih - Agreed Upon"}]},{"id":29,"text":"حسان بن بلال کہتے ہیں کہ میں نے عمار بن یاسر رضی الله عنہما کو دیکھا کہ انہوں نے وضو کیا تو اپنی داڑھی میں خلال کیا ۱؎ ان سے کہا گیا یا راوی حدیث حسان نے کہا کہ میں نے ان سے کہا: کیا آپ اپنی داڑھی کا خلال کر رہے ہیں؟ تو انہوں نے جواب دیا کہ میں داڑھی کا خلال کیوں نہ کروں جب کہ میں نے رسول اللہ صلی الله علیہ وسلم کو داڑھی کا خلال کرتے دیکھا ہے۔","section":1,"grades":[{"name":"Ahmad Muhammad Shakir","grade":"Sahih"},{"name":"Al-Albani","grade":"Sahih"},{"name":"Zubair Ali Zai","grade":"Daif"}]},{"id":30,"text":"اس سند سے بھی عمار بن یاسر سے اوپر ہی کی حدیث کے مثل مرفوعاً مروی ہے۔ امام ترمذی کہتے ہیں: ۱- اس باب میں عثمان، عائشہ، ام سلمہ، انس، ابن ابی اوفی اور ابوایوب رضی الله عنہم سے بھی احادیث آئی ہیں، ۲- محمد بن اسماعیل بخاری کہتے ہیں کہ اس باب میں سب سے زیادہ صحیح حدیث عامر بن شقیق کی ہے، جسے انہوں نے ابووائل سے اور ابووائل نے عثمان رضی الله عنہ سے روایت کیا ہے ( جو آگے آ رہی ہے ) ، ۳- صحابہ اور تابعین میں سے اکثر اہل علم اسی کے قائل ہیں، ان لوگوں کی رائے ہے کہ داڑھی کا خلال ( مسنون ) ہے اور اسی کے قائل شافعی بھی ہیں، احمد کہتے ہیں کہ اگر کوئی داڑھی کا خلال کرنا بھول جائے تو وضو جائز ہو گا، اسحاق بن راہویہ کہتے ہیں کہ اگر کوئی بھول کر چھوڑ دے یا خلال والی حدیث کی تاویل کر رہا ہو تو اسے کافی ہو جائے گا اور اگر قصداً جان بوجھ کر چھوڑے تو وہ اسے ( وضو کو ) لوٹائے۔","section":1,"grades":[{"name":"Zubair Ali Zai","grade":"Daif"}]}]}'),h=JSON.parse('{"name":"نسائی","sections":{"1":"طہارت کی کتاب"},"hadiths":[{"id":1,"text":"ابوہریرہ رضی اللہ عنہ سے روایت ہے کہ نبی اکرم صلی اللہ علیہ وسلم نے فرمایا: جب تم میں سے کوئی شخص نیند سے جاگ جائے تو اپنا ہاتھ اپنے وضو کے پانی میں نہ ڈالے، یہاں تک کہ اسے تین بار دھو لے، کیونکہ وہ نہیں جانتا کہ اس کا ہاتھ رات میں کہاں کہاں رہا ہے ۔","section":1,"grades":[{"name":"Abu Ghuddah","grade":"Sahih"},{"name":"Al-Albani","grade":"Sahih"},{"name":"Zubair Ali Zai","grade":"Sahih Muslim"}]},{"id":2,"text":"حذیفہ رضی اللہ عنہ کہتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم جب رات کو ( نماز تہجد کے لیے ) اٹھتے تو اپنا منہ مسواک سے خوب صاف کرتے ۱؎۔","section":1,"grades":[{"name":"Abu Ghuddah","grade":"Sahih"},{"name":"Al-Albani","grade":"Sahih"},{"name":"Zubair Ali Zai","grade":"Sahih - Agreed Upon"}]},{"id":3,"text":"ابوموسیٰ اشعری رضی اللہ عنہ کہتے ہیں کہ میں رسول اللہ صلی اللہ علیہ وسلم کے پاس آیا، آپ مسواک کر رہے تھے اور مسواک کا سرا آپ صلی اللہ علیہ وسلم کی زبان پر تھا، اور آپ: «عأعأ‏» کی آواز نکال رہے تھے ۱؎۔","section":1,"grades":[{"name":"Abu Ghuddah","grade":"Sahih"},{"name":"Al-Albani","grade":"Sahih"},{"name":"Zubair Ali Zai","grade":"Sahih - Agreed Upon"}]},{"id":4,"text":"ابوموسیٰ اشعری رضی اللہ عنہ کہتے ہیں کہ میں نبی اکرم صلی اللہ علیہ وسلم کے پاس آیا، میرے ساتھ قبیلہ اشعر کے دو آدمی تھے، ان میں سے ایک میرے دائیں اور دوسرا میرے بائیں تھا، رسول اللہ صلی اللہ علیہ وسلم مسواک کر رہے تھے، تو ان دونوں نے آپ صلی اللہ علیہ وسلم سے کام ( نوکری ) کی درخواست کی ۲؎، میں نے عرض کیا: اس ذات کی قسم جس نے آپ کو نبی برحق بنا کر بھیجا ہے، ان دونوں نے اپنے ارادے سے مجھے آگاہ نہیں کیا تھا، اور نہ ہی مجھے اس کا احساس تھا کہ وہ کام ( نوکری ) کے طلب گار ہیں، گویا میں آپ صلی اللہ علیہ وسلم کی مسواک کو ( جو اس وقت آپ کر رہے تھے ) آپ کے ہونٹ کے نیچے دیکھ رہا ہوں اور ہونٹ اوپر اٹھا ہوا ہے، تو آپ صلی اللہ علیہ وسلم نے فرمایا: ہم کام پر اس شخص سے مدد نہیں لیتے جو اس کا طلب گار ہو ۳؎، لیکن ( اے ابوموسیٰ! ) تم جاؤ ( یعنی ان دونوں کے بجائے میں تمہیں کام دیتا ہوں ) ، چنانچہ آپ صلی اللہ علیہ وسلم نے ان کو یمن کا ذمہ دار بنا کر بھیجا، پھر معاذ بن جبل رضی اللہ عنہم کو ان کے پیچھے بھیجا۔","section":1,"grades":[{"name":"Abu Ghuddah","grade":"Sahih"},{"name":"Al-Albani","grade":"Sahih"},{"name":"Zubair Ali Zai","grade":"Sahih - Agreed Upon"}]},{"id":5,"text":"ام المؤمنین عائشہ رضی اللہ عنہا نبی اکرم صلی الله علیہ وسلم سے روایت کرتی ہیں کہ آپ صلی اللہ علیہ وسلم نے فرمایا: مسواک منہ کی پاکیزگی، رب تعالیٰ کی رضا کا ذریعہ ہے ۔","section":1,"grades":[{"name":"Abu Ghuddah","grade":"Sahih"},{"name":"Al-Albani","grade":"Sahih"},{"name":"Zubair Ali Zai","grade":"Sahih"}]},{"id":6,"text":"انس بن مالک رضی اللہ عنہ کہتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: میں نے مسواک کے سلسلے میں تم لوگوں سے بارہا کہا ہے ۱؎۔","section":1,"grades":[{"name":"Abu Ghuddah","grade":"Sahih"},{"name":"Al-Albani","grade":"Sahih"},{"name":"Zubair Ali Zai","grade":"Sahih Bukhari"}]},{"id":7,"text":"ابوہریرہ رضی اللہ عنہ سے روایت ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: اگر میں اپنی امت کے لیے باعث مشقت نہ سمجھتا تو انہیں ہر نماز کے وقت مسواک کرنے کا حکم دیتا ۱؎۔","section":1,"grades":[{"name":"Abu Ghuddah","grade":"Sahih"},{"name":"Al-Albani","grade":"Sahih"},{"name":"Zubair Ali Zai","grade":"Sahih - Agreed Upon"}]},{"id":8,"text":"شریح کہتے ہیں: میں نے ام المؤمنین عائشہ رضی اللہ عنہا سے پوچھا کہ نبی اکرم صلی اللہ علیہ وسلم جب اپنے گھر میں داخل ہوتے تو کون سا کام پہلے کرتے؟ انہوں نے کہا: مسواک سے ( پہل کرتے ) ۱؎۔","section":1,"grades":[{"name":"Abu Ghuddah","grade":"Sahih"},{"name":"Al-Albani","grade":"Sahih"},{"name":"Zubair Ali Zai","grade":"Sahih Muslim"}]},{"id":9,"text":"ابوہریرہ رضی اللہ عنہ رسول اللہ صلی اللہ علیہ وسلم سے روایت کرتے ہیں کہ آپ نے فرمایا: فطری ( پیدائشی ) سنتیں پانچ ہیں، ختنہ کرنا، زیر ناف کے بال صاف کرنا، مونچھ کترنا، ناخن تراشنا، اور بغل کے بال اکھیڑنا ۔","section":1,"grades":[{"name":"Abu Ghuddah","grade":"Sahih"},{"name":"Al-Albani","grade":"Sahih"},{"name":"Zubair Ali Zai","grade":"Sahih - Agreed Upon"}]},{"id":10,"text":"ابوہریرہ رضی اللہ عنہ کہتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: پانچ چیزیں فطرت میں سے ہیں: مونچھ کترنا، بغل کے بال اکھیڑنا، ناخن تراشنا، زیر ناف کے بال صاف کرنا، اور ختنہ کرنا ۔","section":1,"grades":[{"name":"Abu Ghuddah","grade":"Sahih"},{"name":"Al-Albani","grade":"Sahih"},{"name":"Zubair Ali Zai","grade":"Hasan"}]},{"id":11,"text":"ابوہریرہ رضی اللہ عنہ نبی اکرم صلی اللہ علیہ وسلم سے روایت کرتے ہیں کہ آپ صلی اللہ علیہ وسلم نے فرمایا: پانچ چیزیں فطرت میں سے ہیں: ختنہ کرنا، زیر ناف کے بال مونڈنا، بغل کے بال اکھیڑنا، ناخن تراشنا، اور مونچھ کے بال لینا ( یعنی کاٹنا ) ۔","section":1,"grades":[{"name":"Abu Ghuddah","grade":"Sahih"},{"name":"Al-Albani","grade":"Sahih"},{"name":"Zubair Ali Zai","grade":"Sahih - Agreed Upon"}]},{"id":12,"text":"عبداللہ بن عمر رضی اللہ عنہم سے روایت ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ناخن تراشنا، مونچھ کے بال لینا، اور زیر ناف کے بال مونڈنا فطری ( پیدائشی ) سنتیں ہیں ۔","section":1,"grades":[{"name":"Abu Ghuddah","grade":"Sahih"},{"name":"Al-Albani","grade":"Sahih"},{"name":"Zubair Ali Zai","grade":"Sahih Bukhari"}]},{"id":13,"text":"زید بن ارقم رضی اللہ عنہ کہتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: جو اپنی مونچھ کے بال نہ لے وہ ہم میں سے نہیں ۱؎۔","section":1,"grades":[{"name":"Abu Ghuddah","grade":"Sahih"},{"name":"Al-Albani","grade":"Sahih"},{"name":"Zubair Ali Zai","grade":"Sahih"}]},{"id":14,"text":"انس بن مالک رضی اللہ عنہ کہتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے مونچھ کترنے، ناخن تراشنے، زیر ناف کے بال صاف کرنے، اور بغل کے بال اکھیڑنے کی مدت ہمارے لیے مقرر فرما دی ہے کہ ان چیزوں کو چالیس دن سے زیادہ نہ چھوڑے رکھیں ۱؎، راوی نے دوسری بار «أربعين يومًا» کے بجائے «أربعين ليلة» کے الفاظ کی روایت کی ہے۔","section":1,"grades":[{"name":"Abu Ghuddah","grade":"Sahih"},{"name":"Al-Albani","grade":"Sahih"},{"name":"Zubair Ali Zai","grade":"Sahih Muslim"}]},{"id":15,"text":"عبداللہ بن عمر رضی اللہ عنہم کہتے ہیں کہ نبی اکرم صلی اللہ علیہ وسلم نے فرمایا: مونچھوں کو خوب کترو ۱؎، اور داڑھیوں کو چھوڑے رکھو ۲؎۔","section":1,"grades":[{"name":"Abu Ghuddah","grade":"Sahih"},{"name":"Al-Albani","grade":"Sahih"},{"name":"Zubair Ali Zai","grade":"Sahih - Agreed Upon"}]},{"id":16,"text":"عبدالرحمٰن بن ابی قراد رضی اللہ عنہ کہتے ہیں کہ میں رسول اللہ صلی اللہ علیہ وسلم کے ساتھ قضائے حاجت کے لیے نکلا، اور آپ جب قضائے حاجت کا ارادہ فرماتے تو دور جاتے ۱؎۔","section":1,"grades":[{"name":"Abu Ghuddah","grade":"Sahih"},{"name":"Al-Albani","grade":"Sahih"},{"name":"Zubair Ali Zai","grade":"Isnaad Hasan"}]},{"id":17,"text":"مغیرہ بن شعبہ رضی اللہ عنہ سے روایت ہے کہ نبی اکرم صلی اللہ علیہ وسلم جب پاخانے کے لیے جاتے تو دور جاتے، مغیرہ بن شعبہ کہتے ہیں کہ آپ اپنے ایک سفر میں قضائے حاجت کے لیے تشریف لے گئے ( تو واپس آ کر ) آپ نے فرمایا: میرے لیے وضو کا پانی لاؤ ، میں آپ کے پاس پانی لے کر آیا، تو آپ نے وضو کیا اور دونوں موزوں پر مسح کیا۔ امام نسائی کہتے ہیں اسمائیل سے مراد: ابن جعفر بن ابی کثیر القاری ہیں۔","section":1,"grades":[{"name":"Abu Ghuddah","grade":"Hasan Sahih"},{"name":"Al-Albani","grade":"Hasan Sahih"},{"name":"Zubair Ali Zai","grade":"Sahih"}]},{"id":18,"text":"حذیفہ رضی اللہ عنہ کہتے ہیں کہ میں رسول اللہ صلی اللہ علیہ وسلم کے ساتھ چل رہا تھا کہ آپ لوگوں کے ایک کوڑے خانہ پر پہنچے تو آپ صلی اللہ علیہ وسلم نے کھڑے ہو کر پیشاب کیا ۱؎، میں آپ سے دور ہٹ گیا، تو آپ نے مجھے بلایا ۲؎، ( تو جا کر ) میں آپ کی دونوں ایڑیوں کے پاس ( کھڑا ) ہو گیا یہاں تک کہ آپ ( پیشاب سے ) فارغ ہو گئے، پھر آپ نے وضو کیا اور اپنے دونوں موزوں پر مسح کیا۔","section":1,"grades":[{"name":"Abu Ghuddah","grade":"Sahih"},{"name":"Al-Albani","grade":"Sahih"},{"name":"Zubair Ali Zai","grade":"Sahih - Agreed Upon"}]},{"id":19,"text":"انس بن مالک رضی اللہ عنہ کہتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم جب پاخانہ کی جگہ میں داخل ہوتے تو یہ دعا پڑھتے: «اللہم إني أعوذ بك من الخبث والخبائث» اے اللہ! میں ناپاک جنوں اور جنیوں ( کے شر ) سے تیری پناہ چاہتا ہوں ۔","section":1,"grades":[{"name":"Abu Ghuddah","grade":"Sahih"},{"name":"Al-Albani","grade":"Sahih"},{"name":"Zubair Ali Zai","grade":"Sahih - Agreed Upon"}]},{"id":20,"text":"رافع بن اسحاق سے روایت ہے کہ انہوں نے ابوایوب انصاری رضی اللہ عنہ کو مصر میں ان کے قیام کے دوران کہتے سنا: اللہ کی قسم! میری سمجھ میں نہیں آتا کہ ان کھڈیوں کو کیا کروں؟ رسول اللہ صلی اللہ علیہ وسلم کا فرمان ہے: جب تم میں سے کوئی پاخانے یا پیشاب کے لیے جائے تو قبلہ کی طرف منہ یا پیٹھ نہ کرے ۔","section":1,"grades":[{"name":"Abu Ghuddah","grade":"Sahih"},{"name":"Al-Albani","grade":"Sahih"},{"name":"Zubair Ali Zai","grade":"Isnaad Sahih"}]},{"id":21,"text":"ابوایوب انصاری رضی اللہ عنہ سے روایت ہے کہ نبی اکرم صلی اللہ علیہ وسلم نے فرمایا: پاخانہ و پیشاب کے لیے قبلہ کی طرف منہ یا پیٹھ نہ کرو، بلکہ پورب یا پچھم کی طرف کرو ۔","section":1,"grades":[{"name":"Abu Ghuddah","grade":"Sahih"},{"name":"Al-Albani","grade":"Sahih"},{"name":"Zubair Ali Zai","grade":"Sahih - Agreed Upon"}]},{"id":22,"text":"ابوایوب انصاری رضی اللہ عنہ کہتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: جب تم میں سے کوئی قضائے حاجت کے لیے جائے تو قبلہ کی طرف رخ نہ کرے، بلکہ پورب یا پچھم کی طرف کرے ۔","section":1,"grades":[{"name":"Abu Ghuddah","grade":"Sahih"},{"name":"Al-Albani","grade":"Sahih"},{"name":"Zubair Ali Zai","grade":"Sahih - Agreed Upon"}]},{"id":23,"text":"عبداللہ بن عمر رضی اللہ عنہم کہتے ہیں کہ میں اپنے گھر کی چھت پر چڑھا، تو میں نے رسول اللہ صلی اللہ علیہ وسلم کو دو کچی اینٹوں پر قضائے حاجت کے لیے بیت المقدس کی طرف منہ کئے ہوئے بیٹھے دیکھا ۱؎۔","section":1,"grades":[{"name":"Abu Ghuddah","grade":"Sahih"},{"name":"Al-Albani","grade":"Sahih"},{"name":"Zubair Ali Zai","grade":"Sahih - Agreed Upon"}]},{"id":24,"text":"ابوقتادہ رضی اللہ عنہ سے روایت ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: جب تم میں سے کوئی پیشاب کرے تو داہنے ہاتھ سے اپنا ذکر ( عضو تناسل ) نہ پکڑے ۱؎۔","section":1,"grades":[{"name":"Abu Ghuddah","grade":"Sahih"},{"name":"Al-Albani","grade":"Sahih"},{"name":"Zubair Ali Zai","grade":"Sahih - Agreed Upon"}]},{"id":25,"text":"ابوقتادہ رضی اللہ عنہ کہتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: جب تم میں سے کوئی پاخانہ کی جگہ میں داخل ہو تو اپنے داہنے ہاتھ سے اپنا ذکر نہ چھوئے ۔","section":1,"grades":[{"name":"Abu Ghuddah","grade":"Sahih"},{"name":"Al-Albani","grade":"Sahih"},{"name":"Zubair Ali Zai","grade":"Sahih - Agreed Upon"}]},{"id":26,"text":"حذیفہ رضی اللہ عنہ سے روایت ہے کہ رسول اللہ صلی اللہ علیہ وسلم لوگوں کے کوڑا خانہ پر آئے تو کھڑے ہو کر پیشاب کیا۔","section":1,"grades":[{"name":"Abu Ghuddah","grade":"Sahih"},{"name":"Al-Albani","grade":"Sahih"},{"name":"Zubair Ali Zai","grade":"Sahih - Agreed Upon"}]},{"id":27,"text":"حذیفہ رضی اللہ عنہ نے کہا کہ رسول اللہ صلی اللہ علیہ وسلم لوگوں کے کوڑا خانہ پر آئے تو کھڑے ہو کر پیشاب کیا۔","section":1,"grades":[{"name":"Abu Ghuddah","grade":"Sahih"},{"name":"Al-Albani","grade":"Sahih"},{"name":"Zubair Ali Zai","grade":"Sahih - Agreed Upon"}]},{"id":28,"text":"حذیفہ رضی اللہ عنہ سے روایت ہے کہ نبی اکرم صلی اللہ علیہ وسلم لوگوں کے ایک کوڑا خانہ پر چل کر آئے تو آپ نے کھڑے ہو کر پیشاب کیا۔","section":1,"grades":[{"name":"Abu Ghuddah","grade":"Sahih"},{"name":"Al-Albani","grade":"Sahih"},{"name":"Zubair Ali Zai","grade":"Sahih - Agreed Upon"}]},{"id":29,"text":"ام المؤمنین عائشہ رضی اللہ عنہا کہتی ہیں کہ جو تم سے یہ بیان کرے کہ رسول اللہ صلی اللہ علیہ وسلم نے کھڑے ہو کر پیشاب کیا، تو تم اس کی تصدیق نہ کرو، آپ صلی اللہ علیہ وسلم بیٹھ کر ہی پیشاب کیا کرتے تھے ۱؎۔","section":1,"grades":[{"name":"Abu Ghuddah","grade":"Sahih"},{"name":"Al-Albani","grade":"Sahih"},{"name":"Zubair Ali Zai","grade":"Daif"}]},{"id":30,"text":"عبدالرحمٰن بن حسنہ رضی اللہ عنہ کہتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم ہمارے پاس تشریف لائے، آپ کے ہاتھ میں ڈھال کی طرح کوئی چیز تھی، تو آپ نے اسے رکھا، پھر اس کے پیچھے بیٹھے، اور اس کی طرف منہ کر کے پیشاب کیا، اس پر لوگوں نے کہا: ان کو دیکھو! یہ عورت کی طرح پیشاب کر رہے ہیں، آپ صلی اللہ علیہ وسلم نے سنا تو فرمایا: کیا تمہیں اس چیز کی خبر نہیں جو بنی اسرائیل کے ایک شخص کو پیش آئی، انہیں جب پیشاب میں سے کچھ لگ جاتا تو اسے قینچی سے کاٹ ڈالتے تھے، تو ان کے ایک شخص نے انہیں ( ایسا کرنے سے ) روکا، چنانچہ اس کی وجہ سے وہ اپنی قبر میں عذاب دیا گیا ۔","section":1,"grades":[{"name":"Abu Ghuddah","grade":"Sahih"},{"name":"Al-Albani","grade":"Sahih"},{"name":"Zubair Ali Zai","grade":"Daif"}]}]}'),n=JSON.parse('{"name":"ابن ماجہ","sections":{"0":"کتاب وسنت"},"hadiths":[{"id":1,"text":"ابوہریرہ رضی اللہ عنہ کہتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: میں تمہیں جس چیز کا حکم دوں اسے مانو، اور جس چیز سے روک دوں اس سے رک جاؤ ۔","section":0,"grades":[{"name":"Al-Albani","grade":"Sahih"},{"name":"Muhammad Fouad Abd al-Baqi","grade":"Sahih"},{"name":"Shuaib Al Arnaut","grade":"Sahih"},{"name":"Zubair Ali Zai","grade":"Sahih"}]},{"id":2,"text":"ابوہریرہ رضی اللہ عنہ کہتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: جو چیز میں نے تمہیں نہ بتائی ہو اسے یوں ہی رہنے دو ۱؎، اس لیے کہ تم سے پہلے کی امتیں زیادہ سوال اور اپنے انبیاء سے اختلاف کی وجہ سے ہلاک ہوئیں، لہٰذا جب میں تمہیں کسی چیز کا حکم دوں تو طاقت بھر اس پر عمل کرو، اور جب کسی چیز سے منع کر دوں تو اس سے رک جاؤ ۔","section":0,"grades":[{"name":"Al-Albani","grade":"Sahih"},{"name":"Muhammad Fouad Abd al-Baqi","grade":"Sahih"},{"name":"Shuaib Al Arnaut","grade":"Sahih"},{"name":"Zubair Ali Zai","grade":"Sahih Muslim"}]},{"id":3,"text":"ابوہریرہ رضی اللہ عنہ کہتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: جس نے میری اطاعت کی اس نے اللہ کی اطاعت کی، اور جس نے میری نافرمانی کی اس نے اللہ کی نافرمانی کی ۱؎۔","section":0,"grades":[{"name":"Al-Albani","grade":"Sahih"},{"name":"Muhammad Fouad Abd al-Baqi","grade":"Sahih"},{"name":"Shuaib Al Arnaut","grade":"Sahih"},{"name":"Zubair Ali Zai","grade":"Sahih"}]},{"id":4,"text":"ابو جعفر کہتے ہیں کہ عبداللہ بن عمر رضی اللہ عنہما جب رسول اللہ صلی اللہ علیہ وسلم سے کوئی حدیث سنتے تو نہ اس میں کچھ بڑھاتے، اور نہ ہی کچھ گھٹاتے ۱؎۔","section":0,"grades":[{"name":"Al-Albani","grade":"Sahih"},{"name":"Muhammad Fouad Abd al-Baqi","grade":"Sahih"},{"name":"Shuaib Al Arnaut","grade":"Sahih"},{"name":"Zubair Ali Zai","grade":"Isnaad Sahih"}]},{"id":5,"text":"ابو الدرداء رضی اللہ عنہ کہتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم ہمارے پاس آئے، ہم اس وقت غربت و افلاس اور فقر کا تذکرہ کر رہے تھے، اور اس سے ڈر رہے تھے، آپ صلی اللہ علیہ وسلم نے فرمایا: کیا تم لوگ فقر سے ڈرتے ہو؟ قسم ہے اس ذات کی جس کے ہاتھ میں میری جان ہے، ضرور تم پر دنیا آئندہ ایسی لائی جائے گی کہ اس کی طلب مزید تمہارے دل کو حق سے پھیر دے گی ۱؎، قسم اللہ کی! میں نے تم کو ایسی تابناک اور روشن شریعت پر چھوڑا ہے جس کی رات ( تابناکی میں ) اس کے دن کی طرح ہے ۔ ابوالدرداء رضی اللہ عنہ کہتے ہیں کہ قسم اللہ کی! رسول اللہ صلی اللہ علیہ وسلم نے سچ فرمایا، قسم اللہ کی! آپ نے ہم کو ایک تابناک اور روشن شریعت پر چھوڑا، جس کی رات ( تابناکی میں ) اس کے دن کی طرح ہے ۲؎۔","section":0,"grades":[{"name":"Al-Albani","grade":"Hasan"},{"name":"Muhammad Fouad Abd al-Baqi","grade":"Hasan"},{"name":"Shuaib Al Arnaut","grade":"Hasan"},{"name":"Zubair Ali Zai","grade":"Isnaad Hasan"}]},{"id":6,"text":"قرہ بن ایاس رضی اللہ عنہ کہتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: میری امت میں سے ایک گروہ کو ہمیشہ قیامت تک اللہ تعالیٰ کی مدد حاصل رہے گی ۱؎، اور جو اس کی تائید و مدد نہ کرے گا اسے کوئی نقصان نہیں پہنچا سکے گا ۔","section":0,"grades":[{"name":"Al-Albani","grade":"Sahih"},{"name":"Muhammad Fouad Abd al-Baqi","grade":"Sahih"},{"name":"Zubair Ali Zai","grade":"Isnaad Sahih"}]},{"id":7,"text":"ابوہریرہ رضی اللہ عنہ کہتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: میری امت میں ایک گروہ ہمیشہ اللہ کے حکم ( دین ) پر قائم رہنے والا ہو گا، اس کی مخالفت کرنے والا اس کا کچھ نہ بگاڑ سکے گا ۔","section":0,"grades":[{"name":"Al-Albani","grade":"Hasan Sahih"},{"name":"Muhammad Fouad Abd al-Baqi","grade":"Hasan Sahih"},{"name":"Shuaib Al Arnaut","grade":"Sahih"},{"name":"Zubair Ali Zai","grade":"Isnaad Hasan"}]},{"id":8,"text":"ابوعنبہ خولانی رضی اللہ عنہ سے روایت ہے کہ انہوں نے رسول اللہ صلی اللہ علیہ وسلم کے ساتھ دونوں قبلوں کی طرف نماز پڑھی تھی، وہ کہتے ہیں: میں نے رسول اللہ صلی اللہ علیہ وسلم کو فرماتے ہوئے سنا: اللہ ہمیشہ اس دین میں نئے پودے اگا کر ان سے اپنی اطاعت کراتا رہے گا ۱؎ ۔","section":0,"grades":[{"name":"Al-Albani","grade":"Hasan"},{"name":"Muhammad Fouad Abd al-Baqi","grade":"Hasan"},{"name":"Shuaib Al Arnaut","grade":"Hasan"},{"name":"Zubair Ali Zai","grade":"Isnaad Hasan"}]},{"id":9,"text":"شعیب کہتے ہیں کہ معاویہ رضی اللہ عنہ خطبہ دینے کے لیے کھڑے ہوئے اور کہا: تمہارے علماء کہاں ہیں؟ تمہارے علماء کہاں ہیں؟ میں نے رسول اللہ صلی اللہ علیہ وسلم کو فرماتے سنا ہے: قیامت تک میری امت میں سے ایک گروہ لوگوں پر غالب رہے گا، کوئی اس کی مدد کرے یا نہ کرے اسے اس کی پرواہ نہ ہو گی ۔","section":0,"grades":[{"name":"Al-Albani","grade":"Sahih"},{"name":"Muhammad Fouad Abd al-Baqi","grade":"Sahih"},{"name":"Zubair Ali Zai","grade":"Sahih"}]},{"id":10,"text":"ثوبان رضی اللہ عنہ کہتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: میری امت میں سے ایک گروہ ہمیشہ نصرت الٰہی سے بہرہ ور ہو کر حق پر قائم رہے گا، مخالفین کی مخالفت اسے ( اللہ کے امر یعنی: ) ۱؎ قیامت تک کوئی نقصان نہ پہنچا سکے گی ۔","section":0,"grades":[{"name":"Al-Albani","grade":"Sahih"},{"name":"Muhammad Fouad Abd al-Baqi","grade":"Sahih"},{"name":"Shuaib Al Arnaut","grade":"Sahih"},{"name":"Zubair Ali Zai","grade":"Sahih Muslim"}]},{"id":11,"text":"جابر بن عبداللہ رضی اللہ عنہما کہتے ہیں کہ ہم نبی اکرم صلی اللہ علیہ وسلم کے پاس تھے، آپ نے ایک لکیر کھینچی اور دو لکیریں اس کے دائیں جانب اور دو بائیں جانب کھینچیں، پھر اپنا ہاتھ بیچ والی لکیر پر رکھا اور فرمایا: یہ اللہ کا راستہ ہے ، پھر اس آیت کی تلاوت کی: «وأن هذا صراطي مستقيما فاتبعوه ولا تتبعوا السبل فتفرق بكم عن سبيله» یہی میرا سیدھا راستہ ہے پس تم اسی پر چلو، اور دوسرے راستوں پر نہ چلو ورنہ یہ تمہیں اللہ تعالیٰ کے راستہ سے بھٹکا دیں گے ( سورۃ الانعام: ۱۵۳ ) ۱؎۔","section":0,"grades":[{"name":"Al-Albani","grade":"Sahih"},{"name":"Muhammad Fouad Abd al-Baqi","grade":"Sahih"},{"name":"Zubair Ali Zai","grade":"Daif"}]},{"id":12,"text":"مقدام بن معدیکرب کندی رضی اللہ عنہ کہتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: قریب ہے کہ کوئی آدمی اپنے آراستہ تخت پر ٹیک لگائے بیٹھا ہو اور اس سے میری کوئی حدیث بیان کی جائے تو وہ کہے: ہمارے اور تمہارے درمیان اللہ کی کتاب کافی ہے، ہم اس میں جو چیز حلال پائیں گے اسی کو حلال سمجھیں گے اور جو چیز حرام پائیں گے اسی کو حرام جانیں گے ، تو سن لو! جسے رسول اللہ صلی اللہ علیہ وسلم نے حرام قرار دیا ہے وہ ویسے ہی ہے جیسے اللہ نے حرام قرار دیا ہے ۔","section":0,"grades":[{"name":"Al-Albani","grade":"Sahih"},{"name":"Muhammad Fouad Abd al-Baqi","grade":"Sahih"},{"name":"Shuaib Al Arnaut","grade":"Hasan"},{"name":"Zubair Ali Zai","grade":"Isnaad Hasan"}]},{"id":13,"text":"ابورافع رضی اللہ عنہ کہتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: میں تم میں سے کسی کو ہرگز اس حال میں نہ پاؤں کہ وہ اپنے آراستہ تخت پر ٹیک لگائے ہو، اور اس کے پاس جن چیزوں کا میں نے حکم دیا ہے، یا جن چیزوں سے منع کیا ہے میں سے کوئی بات پہنچے تو وہ یہ کہے کہ میں نہیں جانتا، ہم نے تو اللہ کی کتاب میں جو چیز پائی اس کی پیروی کی ۔","section":0,"grades":[{"name":"Al-Albani","grade":"Sahih"},{"name":"Muhammad Fouad Abd al-Baqi","grade":"Sahih"},{"name":"Shuaib Al Arnaut","grade":"Hasan Sahih"},{"name":"Zubair Ali Zai","grade":"Isnaad Sahih"}]},{"id":14,"text":"ام المؤمنین عائشہ رضی اللہ عنہا کہتی ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: جس شخص نے ہمارے اس دین میں کوئی ایسی نئی چیز ایجاد کی جو اس میں سے نہیں ہے، تو وہ قابل رد ہے ۱؎ ۔","section":0,"grades":[{"name":"Al-Albani","grade":"Sahih"},{"name":"Muhammad Fouad Abd al-Baqi","grade":"Sahih"},{"name":"Shuaib Al Arnaut","grade":"Sahih"},{"name":"Zubair Ali Zai","grade":"Sahih - Bukhari And Muslim"}]},{"id":15,"text":"عبداللہ بن زبیر رضی اللہ عنہما کہتے ہیں کہ ایک انصاری نے زبیر رضی اللہ عنہ سے رسول اللہ صلی اللہ علیہ وسلم کے پاس مقام حرہ کی اس نالی کے بارے میں جھگڑا کیا جس سے لوگ کھجور کے باغات کی سینچائی کرتے تھے، انصاری نے زبیر رضی اللہ عنہ سے کہا: پانی چھوڑ دو تاکہ میرے کھیت میں چلا جائے، زبیر رضی اللہ عنہ نے انکار کیا، ان دونوں نے اپنا مقدمہ رسول اللہ صلی اللہ علیہ وسلم کے پاس پیش کیا تو آپ صلی اللہ علیہ وسلم نے فرمایا: زبیر! تم اپنا کھیت سینچ لو! پھر اپنے پڑوسی کی طرف پانی چھوڑ دو ، انصاری غضبناک ہو کر بولا: اللہ کے رسول! یہ اس وجہ سے کہ وہ آپ کے پھوپھی کے بیٹے ہیں؟ یہ سن کر رسول اللہ صلی اللہ علیہ وسلم کا چہرہ مبارک متغیر ہو گیا، آپ صلی اللہ علیہ وسلم نے فرمایا: زبیر! تم اپنا باغ سینچ لو، پھر پانی روکے رکھو یہاں تک کہ وہ مینڈوں تک پہنچ جائے ، عبداللہ بن زبیر رضی اللہ عنہما کہتے ہیں: زبیر نے کہا: قسم اللہ کی! میرا خیال ہے کہ یہ آیت اسی سلسلہ میں نازل ہوئی ہے: «فلا وربك لا يؤمنون حتى يحكموك فيما شجر بينهم ثم لا يجدوا في أنفسهم حرجا مما قضيت ويسلموا تسليما» قسم ہے آپ کے رب کی! یہ مومن نہیں ہو سکتے جب تک کہ آپس کے سارے اختلافات اور جھگڑوں میں آپ کو حاکم نہ مان لیں، پھر جو فیصلہ آپ ان میں کر دیں اس سے اپنے دل میں کسی طرح کی تنگی اور ناخوشی نہ پائیں، اور فرمانبرداری کے ساتھ قبول کر لیں ( سورة النساء: 65 ) ۔","section":0,"grades":[{"name":"Al-Albani","grade":"Sahih"},{"name":"Muhammad Fouad Abd al-Baqi","grade":"Sahih"},{"name":"Shuaib Al Arnaut","grade":"Sahih"},{"name":"Zubair Ali Zai","grade":"Sahih - Agreed Upon"}]},{"id":16,"text":"عبداللہ بن عمر رضی اللہ عنہما کہتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: تم اللہ کی بندیوں ( عورتوں ) کو مسجد میں نماز پڑھنے سے نہ روکو ، تو ان کے ایک بیٹے نے ان سے کہا: ہم تو انہیں ضرور روکیں گے، یہ سن کر ابن عمر رضی اللہ عنہما سخت ناراض ہوئے اور بولے: میں تم سے رسول اللہ صلی اللہ علیہ وسلم کی حدیث بیان کر رہا ہوں اور تم کہتے ہو کہ ہم انہیں ضرور روکیں گے؟ ۱؎۔","section":0,"grades":[{"name":"Al-Albani","grade":"Sahih"},{"name":"Muhammad Fouad Abd al-Baqi","grade":"Sahih"},{"name":"Shuaib Al Arnaut","grade":"Sahih"},{"name":"Zubair Ali Zai","grade":"Sahih Bukhari"}]},{"id":17,"text":"عبداللہ بن مغفل رضی اللہ عنہ سے روایت ہے کہ ان کا ایک بھتیجا ان کے بغل میں بیٹھا ہوا تھا، اس نے دو انگلیوں کے درمیان کنکری رکھ کر پھینکی، تو انہوں نے اسے منع کیا اور کہا: رسول اللہ صلی اللہ علیہ وسلم نے اس کام سے روکا ہے اور فرمایا ہے کہ: یہ کنکری نہ تو کوئی شکار کرتی ہے، اور نہ ہی دشمن کو زخمی کرتی ہے، البتہ یہ دانت توڑ دیتی ہے اور آنکھ پھوڑ دیتی ہے ۔ سعید بن جبیر کہتے ہیں کہ ان کا بھتیجا دوبارہ کنکریاں پھینکنے لگا تو انہوں نے کہا: میں تم سے رسول اللہ صلی اللہ علیہ وسلم کی حدیث بیان کرتا ہوں کہ آپ صلی اللہ علیہ وسلم نے اس کام سے روکا ہے اور تم پھر اسے کرنے لگے، میں تم سے کبھی بات نہیں کروں گا۔","section":0,"grades":[{"name":"Al-Albani","grade":"Sahih"},{"name":"Muhammad Fouad Abd al-Baqi","grade":"Sahih"},{"name":"Shuaib Al Arnaut","grade":"Sahih"},{"name":"Zubair Ali Zai","grade":"Sahih Muslim"}]},{"id":18,"text":"قبیصہ سے روایت ہے کہ عبادہ بن صامت انصاری رضی اللہ عنہ نے ( جو کہ عقبہ کی رات میں رسول اللہ صلی اللہ علیہ وسلم سے بیعت کرنے والے صحابی ہیں ) معاویہ رضی اللہ عنہ کے ساتھ سر زمین روم میں جہاد کیا، وہاں لوگوں کو دیکھا کہ وہ سونے کے ٹکڑوں کو دینار ( اشرفی ) کے بدلے اور چاندی کے ٹکڑوں کو درہم کے بدلے بیچتے ہیں، تو کہا: لوگو! تم سود کھاتے ہو، میں نے رسول اللہ صلی اللہ علیہ وسلم کو فرماتے سنا ہے: تم سونے کو سونے سے نہ بیچو مگر برابر برابر، نہ تو اس میں زیادتی ہو اور نہ ادھار ۱؎ ، تو معاویہ رضی اللہ عنہ نے ان سے کہا: ابوالولید! میری رائے میں تو یہ سود نہیں ہے، یعنی نقدا نقد میں تفاضل ( کمی بیشی ) جائز ہے، ہاں اگر ادھار ہے تو وہ سود ہے، عبادہ رضی اللہ عنہ نے کہا: میں آپ سے حدیث رسول بیان کر رہا ہوں اور آپ اپنی رائے بیان کر رہے ہیں، اگر اللہ تعالیٰ نے مجھے یہاں سے صحیح سالم نکال دیا تو میں کسی ایسی سر زمین میں نہیں رہ سکتا جہاں میرے اوپر آپ کی حکمرانی چلے، پھر جب وہ واپس لوٹے تو مدینہ چلے گئے، تو ان سے عمر بن خطاب رضی اللہ عنہ نے پوچھا: ابوالولید! مدینہ آنے کا سبب کیا ہے؟ تو انہوں نے ان سے پورا واقعہ بیان کیا، اور معاویہ رضی اللہ عنہ سے ان کے زیر انتظام علاقہ میں نہ رہنے کی جو بات کہی تھی اسے بھی بیان کیا، عمر رضی اللہ عنہ نے کہا: ابوالولید! آپ اپنی سر زمین کی طرف واپس لوٹ جائیں، اللہ اس سر زمین میں کوئی بھلائی نہ رکھے جس میں آپ اور آپ جیسے لوگ نہ ہوں ، اور معاویہ رضی اللہ عنہ کو لکھا کہ عبادہ پر آپ کا حکم نہیں چلے گا، آپ لوگوں کو ترغیب دیں کہ وہ عبادہ کی بات پر چلیں کیونکہ شرعی حکم دراصل وہی ہے جو انہوں نے بیان کیا۔","section":0,"grades":[{"name":"Al-Albani","grade":"Sahih Hadith"},{"name":"Muhammad Fouad Abd al-Baqi","grade":"Sahih"},{"name":"Zubair Ali Zai","grade":"Isnaad Hasan"}]},{"id":19,"text":"عبداللہ بن مسعود رضی اللہ عنہ کہتے ہیں کہ جب میں تم سے رسول اللہ صلی اللہ علیہ وسلم کی کوئی حدیث بیان کروں تو تم رسول اللہ صلی اللہ علیہ وسلم کے متعلق یہی ( خیال و گمان ) رکھو کہ آپ کی بات سب سے زیادہ عمدہ، اور ہدایت و تقویٰ میں سب سے بڑھی ہوئی ہے۔","section":0,"grades":[{"name":"Al-Albani","grade":"Daif"},{"name":"Muhammad Fouad Abd al-Baqi","grade":"Daif"},{"name":"Shuaib Al Arnaut","grade":"Daif"},{"name":"Zubair Ali Zai","grade":"Daif"}]},{"id":20,"text":"علی بن ابی طالب رضی اللہ عنہ کہتے کہ جب میں رسول اللہ صلی اللہ علیہ وسلم سے کوئی حدیث بیان کروں تو تم یہی ( خیال گمان ) رکھو کہ آپ صلی اللہ علیہ وسلم کی بات سب سے زیادہ عمدہ، اور ہدایت و تقویٰ میں سب سے بڑھی ہوئی ہے ۱؎۔","section":0,"grades":[{"name":"Al-Albani","grade":"Sahih"},{"name":"Muhammad Fouad Abd al-Baqi","grade":"Sahih"},{"name":"Zubair Ali Zai","grade":"Isnaad Sahih"}]},{"id":21,"text":"ابوہریرہ رضی اللہ عنہ کہتے ہیں کہ کہ نبی اکرم صلی اللہ علیہ وسلم نے فرمایا: میں یہ ہرگز نہ پاؤں کہ تم میں سے کسی سے میری حدیث بیان کی جا رہی ہو اور وہ اپنے آراستہ تخت پر ٹیک لگائے یہ کہتا ہو: قرآن پڑھو، سنو! جو بھی اچھی بات کہی گئی ہے وہ میری ہی کہی ہوئی ہے ۔","section":0,"grades":[{"name":"Al-Albani","grade":"Mawdu"},{"name":"Muhammad Fouad Abd al-Baqi","grade":"Munkar"},{"name":"Shuaib Al Arnaut","grade":"Very Daif"},{"name":"Zubair Ali Zai","grade":"Daif"}]},{"id":22,"text":"ابوسلمہ (ابوسلمہ ابن عبدالرحمٰن بن عوف) سے روایت ہے کہ ابوہریرہ رضی اللہ عنہ نے ایک آدمی سے کہا: میرے بھتیجے! جب میں تم سے رسول اللہ صلی اللہ علیہ وسلم کی کوئی حدیث بیان کروں تو تم اس پر کہاوتیں اور مثالیں نہ بیان کیا کرو۔","section":0,"grades":[{"name":"Al-Albani","grade":"Hasan"},{"name":"Muhammad Fouad Abd al-Baqi","grade":"Hasan"},{"name":"Shuaib Al Arnaut","grade":"Hasan"},{"name":"Zubair Ali Zai","grade":"Isnaad Hasan"}]},{"id":23,"text":"عمرو بن میمون کہتے ہیں کہ میں بلا ناغہ ہر جمعرات کی شام کو عبداللہ بن مسعود رضی اللہ عنہ کے پاس جاتا تھا، میں نے کبھی بھی آپ کو کسی چیز کے بارے میں «قال رسول الله صلى الله عليه وسلم» کہتے نہیں سنا، ایک شام آپ نے کہا: «قال رسول الله صلى الله عليه وسلم» اور اپنا سر جھکا لیا، میں نے ان کو دیکھا کہ اپنے کرتے کی گھنڈیاں کھولے کھڑے ہیں، آنکھیں بھر آئی ہیں اور گردن کی رگیں پھول گئی ہیں اور کہہ رہے ہیں: آپ صلی اللہ علیہ وسلم نے اس سے کچھ کم یا زیادہ یا اس کے قریب یا اس کے مشابہ فرمایا ۱؎۔","section":0,"grades":[{"name":"Al-Albani","grade":"Sahih"},{"name":"Muhammad Fouad Abd al-Baqi","grade":"Sahih"},{"name":"Shuaib Al Arnaut","grade":"Sahih"},{"name":"Zubair Ali Zai","grade":"Isnaad Sahih"}]},{"id":24,"text":"محمد بن سیرین کہتے ہیں کہ انس بن مالک رضی اللہ عنہ جب رسول اللہ صلی اللہ علیہ وسلم سے کوئی حدیث بیان کرتے، اور اس سے فارغ ہوتے تو کہتے: «أو كما قال رسول الله صلى الله عليه وسلم» یا جیسا رسول اللہ صلی اللہ علیہ وسلم نے فرمایا ۱؎۔","section":0,"grades":[{"name":"Al-Albani","grade":"Sahih"},{"name":"Muhammad Fouad Abd al-Baqi","grade":"Sahih"},{"name":"Shuaib Al Arnaut","grade":"Sahih"},{"name":"Zubair Ali Zai","grade":"Isnaad Sahih"}]},{"id":25,"text":"عبدالرحمٰن بن ابی لیلیٰ کہتے ہیں کہ ہم نے زید بن ارقم رضی اللہ عنہ سے کہا کہ ہم سے رسول اللہ صلی اللہ علیہ وسلم کی حدیث بیان کریں، تو وہ کہنے لگے: ہم بوڑھے ہو گئے ہیں، ہم پر نسیان غالب ہو گیا ہے، اور رسول اللہ صلی اللہ علیہ وسلم کی حدیث بیان کرنا مشکل کام ہے۔","section":0,"grades":[{"name":"Al-Albani","grade":"Sahih"},{"name":"Muhammad Fouad Abd al-Baqi","grade":"Sahih"},{"name":"Shuaib Al Arnaut","grade":"Sahih"},{"name":"Zubair Ali Zai","grade":"Isnaad Sahih"}]},{"id":26,"text":"عبداللہ بن ابی السفر کہتے ہیں کہ میں نے شعبی کو کہتے سنا: میں سال بھر ابن عمر رضی اللہ عنہما کی مجلسوں میں رہا لیکن میں نے ان سے رسول اللہ صلی اللہ علیہ وسلم سے کوئی چیز بیان کرتے ہوئے نہیں سنا۔","section":0,"grades":[{"name":"Al-Albani","grade":"Sahih"},{"name":"Muhammad Fouad Abd al-Baqi","grade":"Sahih"},{"name":"Shuaib Al Arnaut","grade":"Sahih"},{"name":"Zubair Ali Zai","grade":"Sahih Bukhari"}]},{"id":27,"text":"طاؤس کہتے ہیں کہ میں نے عبداللہ بن عباس رضی اللہ عنہما کو کہتے سنا: ہم تو بس حدیثیں یاد کرتے تھے اور حدیث رسول تو یاد کی ہی جاتی ہے، لیکن جب تم مشکل اور آسان راستوں پر چلنے لگے تو ہم نے دوری اختیار کر لی ۱؎۔","section":0,"grades":[{"name":"Al-Albani","grade":"Sahih"},{"name":"Muhammad Fouad Abd al-Baqi","grade":"Sahih"},{"name":"Shuaib Al Arnaut","grade":"Sahih"},{"name":"Zubair Ali Zai","grade":"Sahih Muslim"}]},{"id":28,"text":"قرظہ بن کعب کہتے ہیں کہ ہمیں عمر بن خطاب رضی اللہ عنہ نے کوفہ بھیجا، اور ہمیں رخصت کرنے کے لیے آپ ہمارے ساتھ مقام صرار تک چل کر آئے اور کہنے لگے: کیا تم جانتے ہو کہ میں تمہارے ساتھ کیوں چل کر آیا ہوں؟ قرظہ کہتے ہیں کہ ہم نے کہا: رسول اللہ صلی اللہ علیہ وسلم کی صحبت کے حق اور انصار کے حق کی ادائیگی کی خاطر آئے ہیں، کہا: نہیں، بلکہ میں تمہارے ساتھ ایک بات بیان کرنے کے لیے آیا ہوں، میں نے چاہا کہ میرے ساتھ آنے کی وجہ سے تم اسے یاد رکھو گے: تم ایسے لوگوں کے پاس جا رہے ہو جن کے سینوں میں قرآن ہانڈی کی طرح جوش مارتا ہو گا، جب وہ تم کو دیکھیں گے تو ( مارے شوق کے ) اپنی گردنیں تمہاری طرف لمبی کریں گے ۱؎، اور کہیں گے: یہ اصحاب محمد ہیں، تم ان سے رسول اللہ صلی اللہ علیہ وسلم کی حدیثیں کم بیان کرنا، جاؤ میں بھی تمہارا شریک ہوں ۔","section":0,"grades":[{"name":"Al-Albani","grade":"Sahih"},{"name":"Muhammad Fouad Abd al-Baqi","grade":"Sahih"},{"name":"Zubair Ali Zai","grade":"Daif"}]},{"id":29,"text":"سائب بن یزید کہتے ہیں کہ میں سعد بن مالک رضی اللہ عنہ کے ساتھ مدینہ سے مکہ تک گیا، لیکن راستے بھر میں نے آپ کو نبی اکرم صلی اللہ علیہ وسلم سے ایک حدیث بھی بیان کرتے ہوئے نہیں سنا۔","section":0,"grades":[{"name":"Al-Albani","grade":"Sahih"},{"name":"Muhammad Fouad Abd al-Baqi","grade":"Sahih"},{"name":"Shuaib Al Arnaut","grade":"Sahih"},{"name":"Zubair Ali Zai","grade":"Isnaad Sahih"}]},{"id":30,"text":"عبداللہ بن مسعود رضی اللہ عنہ کہتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: جس شخص نے مجھ پر جان بوجھ کر جھوٹ گھڑا تو اس کو چاہیئے کہ وہ اپنا ٹھکانا جہنم میں بنا لے ۱؎۔","section":0,"grades":[{"name":"Al-Albani","grade":"Sahih"},{"name":"Muhammad Fouad Abd al-Baqi","grade":"Sahih"},{"name":"Shuaib Al Arnaut","grade":"Sahih"},{"name":"Zubair Ali Zai","grade":"Sahih"}]}]}'),r={bukhari:a,muslim:i,abudawud:e,tirmidhi:d,nasai:h,ibnmajah:n};export{e as abudawud,a as bukhari,r as default,n as ibnmajah,i as muslim,h as nasai,d as tirmidhi};
